// REQ-339e — session-boundary proactive NPC beats (default off).
function npcProactiveBoundaryOn(): boolean { return (process.env.TTRPG_NPC_PROACTIVE_BOUNDARY ?? "off") === "on"; }
if (npcProactiveBoundaryOn() && !npcAutonomyOn()) {
  process.stderr.write("[holonovel] TTRPG_NPC_PROACTIVE_BOUNDARY=on has no effect unless TTRPG_NPC_AUTONOMY=on (REQ-339e)\n");
}
// REQ-075g — talkativeness defaults to the neutral midpoint when unset.
function npcTalkativeness(npc: any): number {
  const value = Number(npc?.talkativeness);
  return Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 50;
}
// REQ-233a — World in Motion reactivity master switch (default active). A
// narrative directive carrying reactivity keywords overrides it for the
// session (P46: "the world reacts" enables, "freeze the world" disables).
let worldReactivityOverride: boolean | null = null;
function worldReactivityOn(): boolean {
  if (worldReactivityOverride !== null) return worldReactivityOverride;
  // REQ-233a2/a3 — the setting defaults to active; the documented "off" value
  // (and the conventional false forms) disable the cycle.
  const raw = (process.env.TTRPG_WORLD_REACTIVITY ?? "true").trim().toLowerCase();
  return !["false", "off", "0", "no"].includes(raw);
}
function worldGenMaxRooms(): number { return configInt("TTRPG_WORLD_GEN_MAX_ROOMS", 20); }

// REQ-431 — generation tables carry no role marker. Roles come from an explicit
// options.roles override, else from documented name/title tokens. Unmatched
// tables are ignored rather than repurposed, so generation never fabricates a
// mechanic the ruleset did not define (REQ-431b).
type WorldGenRole = "room" | "objects" | "persons" | "hazards" | "secrets";
const WORLD_GEN_ROLES: WorldGenRole[] = ["room", "objects", "persons", "hazards", "secrets"];
const WORLD_GEN_ROLE_TOKENS: Record<WorldGenRole, string[]> = {
  room: ["dungeon", "room", "chamber", "site", "location", "crypt", "hall"],
  objects: ["treasure", "trinket", "loot", "item", "equipment", "container", "supporter", "vehicle"],
  persons: ["encounter", "npc", "monster", "inhabitant", "creature", "person"],
  hazards: ["trap", "hazard", "quirk"],
  secrets: ["secret", "rumor", "clue", "mystery"],
};

// REQ-431d — object draws resolve to a kind from the rolled text or table
// title, so containment follows the kind contracts (REQ-200). Unmatched draws
// stay plain things.
const GENERATION_KIND_TOKENS: Array<{ kind: WorldKind; tokens: string[] }> = [
  { kind: "vehicle", tokens: ["wagon", "cart", "boat", "ship", "carriage"] },
  { kind: "container", tokens: ["chest", "box", "crate", "coffer", "barrel", "urn", "pouch", "bag", "case"] },
  { kind: "supporter", tokens: ["table", "altar", "shelf", "rack", "pedestal", "bench", "desk"] },
  { kind: "door", tokens: ["door", "gate", "portal"] },
];

function generationObjectKind(result: string, title: string): WorldKind {
  const hay = `${result} ${title}`.toLowerCase();
  for (const { kind, tokens } of GENERATION_KIND_TOKENS) {
    if (tokens.some((token) => new RegExp(`\\b${token}s?\\b`).test(hay))) return kind;
  }
  return "thing";
}

// REQ-431d — a generated secret carries its discovery path and the room it
// links to (REQ-363).
interface GeneratedSecret {
  key: string;
  content: string;
  triggers: string[];
  badge_scope: "game_master" | "shared";
  world_target: string;
  clue: string;
  container: string;
}

interface GeneratedWitness {
  name: string;
  room: string;
}

// REQ-431d — validate the batch before offering it: connectivity, reciprocal
// exits, containment references, secret reachability/discovery, and witness
// perceivability. A failure refuses the batch rather than offering a broken
// world for apply.
function validateGeneratedWorld(
  world: WorldModel,
  secrets: GeneratedSecret[],
  witness: GeneratedWitness | null,
  personTablePresent: boolean,
): string[] {
  const failures: string[] = [];
  const roomKeys = [...world.rooms.keys()];
  if (roomKeys.length === 0) return ["no rooms generated"];
  const visited = new Set<string>();
  const queue: string[] = [roomKeys[0]];
  visited.add(roomKeys[0]);
  while (queue.length > 0) {
    const key = queue.shift()!;
    const room = world.rooms.get(key)!;
    for (const [, dest] of room.exits) {
      const destKey = dest.toLowerCase();
      if (!world.rooms.has(destKey)) { failures.push(`exit from '${room.name}' targets missing room '${dest}'`); continue; }
      if (!visited.has(destKey)) { visited.add(destKey); queue.push(destKey); }
    }
  }
  for (const key of roomKeys) {
    if (!visited.has(key)) failures.push(`room '${world.rooms.get(key)!.name}' is unreachable`);
  }
  for (const key of roomKeys) {
    const room = world.rooms.get(key)!;
    for (const [dir, dest] of room.exits) {
      const destRoom = world.rooms.get(dest.toLowerCase());
      if (!destRoom) continue;
      const reciprocal = [...destRoom.exits.values()].some((back) => back.toLowerCase() === key);
      if (!reciprocal) failures.push(`exit ${dir} of '${room.name}' has no reverse exit`);
    }
  }
  for (const thing of world.things.values()) {
    if (!thing.location) continue;
    const loc = thing.location.toLowerCase();
    if (world.rooms.has(loc) || world.things.has(loc)) continue;
    failures.push(`thing '${thing.name}' is placed in missing location '${thing.location}'`);
  }
  for (const secret of secrets) {
    const targetKey = secret.world_target.toLowerCase();
    if (!world.rooms.has(targetKey)) { failures.push(`secret '${secret.key}' targets missing room '${secret.world_target}'`); continue; }
    if (!visited.has(targetKey)) failures.push(`secret '${secret.key}' targets unreachable room '${secret.world_target}'`);
    const clue = world.things.get(secret.clue.toLowerCase());
    if (!clue) { failures.push(`secret '${secret.key}' clue '${secret.clue}' was not placed`); continue; }
    if ((thingRoom(world, clue) ?? "").toLowerCase() !== targetKey) failures.push(`secret '${secret.key}' clue is not in '${secret.world_target}'`);
    if (!clue.readable) failures.push(`secret '${secret.key}' clue has no readable discovery path`);
    const container = world.things.get(secret.container.toLowerCase());
    if (!container) { failures.push(`secret '${secret.key}' container '${secret.container}' was not placed`); continue; }
    if (container.locked) failures.push(`secret '${secret.key}' container is locked`);
  }
  if (secrets.length > 0 && personTablePresent) {
    if (!witness) failures.push("secret placed but no witness was generated");
    else if (!isAudibleFrom(world, secrets[0].world_target, witness.room)) failures.push(`witness '${witness.name}' cannot perceive the secret room`);
  }
  return failures;
}

interface WorldGenTable {
  key: string;
  title: string;
  dice_expression: string;
  ranges: { min: number; max: number; result: unknown }[];
}

interface WorldGenRoll {
  table: string;
  die: string;
  range: string;
  result: string;
}

function worldGenRoleOf(key: string, title: string): WorldGenRole | null {
  const hay = `${key} ${title}`.toLowerCase();
  for (const role of WORLD_GEN_ROLES) {
    if (WORLD_GEN_ROLE_TOKENS[role].some((token) => new RegExp(`\\b${token}s?\\b`).test(hay))) return role;
  }
  return null;
}

function sanitizeGenerationText(value: unknown): string {
  return String(value ?? "")
    .replace(/["\u201c\u201d]/g, "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 240)
    .trim();
}

function sanitizeGenerationName(value: unknown): string {
  const text = sanitizeGenerationText(value).split(/\.\s+/)[0].replace(/\.+$/, "").trim();
  return text.replace(/\s+is\s+(?:in|on)\s+/gi, " near ").slice(0, 60).trim();
}

// Rolls the table's dice expression and returns the matched row. A roll outside
// every defined range yields null so the caller can fall back to the table's
// title, never to an invented result.
function rollGenerationTable(rng: Rng, table: WorldGenTable): WorldGenRoll | null {
  const expr = table.dice_expression;
  let die: number;
  if (/^\d+d\d+([+-]\d+)?$/i.test(expr)) {
    die = rollNotationWithRng(rng, expr).total;
  } else if (/^d\d+$/i.test(expr)) {
    die = rng.roll(parseInt(expr.slice(1), 10));
  } else {
    die = rng.roll(100);
  }
  const range = table.ranges.find((r) => die >= r.min && die <= r.max);
  if (!range) return null;
  const result = sanitizeGenerationText(range.result);
  if (!result) return null;
  return { table: table.title, die: String(die), range: `${range.min}-${range.max}`, result };
}
function maxVoiceCorrections(): number { return configInt("TTRPG_MAX_VOICE_CORRECTIONS_PER_SESSION", 3); }
function vowSuggestionMinChars(): number { return configInt("TTRPG_VOW_SUGGESTION_GOAL_MIN_CHARS", 20); }

// REQ-433 — event notification surface: a session-scoped subscription set. The
// server emits read-only echoes of already-recorded audit events as
// server-to-client notifications; subscriptions are dropped on connection
// close and never persist across restart. REQ-030 is unchanged — this is a
// single-connection push channel, not multi-connection badge synchronization.
// REQ-433 — per-consumer event subscriptions. The MCP notification channel and
// each in-process façade hold their own topic set, so subscribing or closing
// one consumer never clears another's subscriptions.
type EventListener = (topic: string, payload: Record<string, unknown>) => void;
const eventHub = new EventHub();
let transportConnected = false;
let engineSequence = 0;
eventHub.add("mcp", [], (topic, payload) => {
  if (!transportConnected) return;
  try {
    void (server.server as any).notification({ method: "notifications/holonovel/event", params: { topic, ...payload } });
  } catch { /* notification delivery is best-effort — never affects tool results */ }
});
function emitEvent(topic: string, payload: Record<string, unknown>): void {
  eventHub.dispatch(topic, payload);
}
function notifyForBadge(topic: string, payload: Record<string, unknown>, badge: Badge | undefined, gmOnly: boolean): void {
  // REQ-433b — Player-badge connections receive no GM-only notification content.
  if (gmOnly && badge !== "game_master" && badge !== "none") return;
  emitEvent(topic, payload);
}

// REQ-075f — NPC mind content is GM-only: every Player-badge surface strips the
// `mind` object before serialization. GM surfaces include it verbatim.
function sanitizeNpcForBadge(npc: any, isGM: boolean): any {
  if (isGM) return npc;
  // REQ-075f — mind is GM-only. REQ-075g — talkativeness is GM-only on read.
  const { mind, talkativeness, ...rest } = npc;
  return rest;
}

const DISPOSITION_SCALE = ["hostile", "suspicious", "neutral", "friendly"];

function shiftDisposition(current: string, toward: "hostile" | "friendly"): string {
  const idx = DISPOSITION_SCALE.indexOf(current);
  const base = idx === -1 ? DISPOSITION_SCALE.indexOf("neutral") : idx;
  if (toward === "hostile") return DISPOSITION_SCALE[Math.max(0, base - 1)];
  return DISPOSITION_SCALE[Math.min(DISPOSITION_SCALE.length - 1, base + 1)];
}

// P48 — shift one step toward a target disposition. An NPC already at or
// beyond the target is not softened.
function shiftDispositionToward(current: string, target: "hostile" | "suspicious"): string {
  const idx = DISPOSITION_SCALE.indexOf(current);
  const targetIdx = DISPOSITION_SCALE.indexOf(target);
  const base = idx === -1 ? DISPOSITION_SCALE.indexOf("neutral") : idx;
  if (base <= targetIdx) return DISPOSITION_SCALE[base];
  return DISPOSITION_SCALE[base - 1];
}

// The pacing counter increments on every read of a scene-affecting surface;
// the transition hook (REQ-125, REQ-336) resets it. Counted in badge_briefing.
function currentBeat(novel: NovelState): string {
  return novel.scene_beat || DEFAULT_BEAT;
}

// REQ-336 — the pacing counter counts tool calls, not briefing renders. It is
// session-scoped in memory: incrementing a persisted Novel field on every
// read-only call would change the live state hash (REQ-601) and make
// `manage_diagnostics (action: verify)` report divergence (REQ-605).
interface PacingSession { count: number; fired: boolean }
const pacingSessions = new Map<string, PacingSession>();

// REQ-236b — scene-scoped relationship-change markers. The list lives for the
// current scene and is cleared on the next scene transition, matching the
// pacing session. It is deliberately in memory: a persisted Novel field would
// need a §7.7 class contract for a transient briefing line.
interface RelationshipMarker { text: string; entity_ids: string[] }
const relationshipMarkers = new Map<string, RelationshipMarker[]>();

// REQ-236a — an ally↔rival flip prompts the GM to consider a lore entry. Like
// the marker list, the prompt lives for the current scene and is deliberately
// in memory (a persisted Novel field would need a §7.7 class contract).
const relationshipLorePrompts = new Map<string, RelationshipMarker[]>();

function pacingSession(novel: NovelState): PacingSession {
  let session = pacingSessions.get(novel.slug);
  if (!session) {
    session = { count: novel.pacing_counter, fired: novel.pacing_autonomy_fired };
    pacingSessions.set(novel.slug, session);
  }
  return session;
}

// Called by the tool-registry wrapper after every completed tool call.
function bumpPacing(novel: NovelState): void {
  pacingSession(novel).count++;
}

// Drop the in-memory pacing session when a Novel leaves its slug: end,
// archive, or artifact removal. Prevents a stale counter from being inherited
// by a later Novel that reuses the slug.
function forgetPacingSession(slug: string): void {
  pacingSessions.delete(slug);
}

// Rename keeps the same Novel, so its pacing session moves with it; only the
// stale map key is dropped.
function renamePacingSession(oldSlug: string, newSlug: string): void {
  const session = pacingSessions.get(oldSlug);
  if (!session) return;
  pacingSessions.delete(oldSlug);
  pacingSessions.set(newSlug, session);
}

// REQ-336 — pacing signal fires when the tool-call counter exceeds the window.
// Called by badge_briefing (a read surface); the counter increments in the
// tool-registry wrapper.
function pacingSignalText(novel: NovelState): string | null {
  const window = pacingWindow();
  if (window <= 0) return null;
  const count = pacingSession(novel).count;
  return count > window ? `[pacing] Scene stabilized — ${count} actions since last transition.` : null;
}

// REQ-351 — pacing-triggered autonomy. When the pacing signal fires, perform one
// autonomous advancement cycle (faction tick + NPC goal pursuit), at most once
// per pacing window. REQ-348 — faction-NPC coordination suppresses a suggestion
// whose goal overlaps the faction's advanced goal.
function triggerPacingAutonomy(novel: NovelState): void {
  if (pacingSignalText(novel) === null) return;
  const session = pacingSession(novel);
  if (session.fired) return;
  session.fired = true;
  novel.pacing_autonomy_fired = true;
  novel.pacing_counter = session.count;

  const affectedFactions: string[] = [];
  for (const f of novel.factions) {
    if (!hasFactionClock(f)) continue;
    advanceFactionClock(novel, f, 1);
    affectedFactions.push(f.id);
  }
  const affectedNpcs: string[] = [];
  for (const [, npc] of novel.npcs) {
    const goal = npc.personality?.goals;
    if (!goal) continue;
    // REQ-348 — suppress when a faction goal overlaps this NPC's goal.
    const overlap = novel.factions.some((f) => goalsOverlap(f.goals, goal));
    if (overlap) {
      audit("faction-npc-coordination", { npc: npc.id, goal, factions: novel.factions.map((f) => f.id) });
      continue;
    }
    ensureGoalSuggestion(novel, npc.id, npc.name, goal);
    affectedNpcs.push(npc.id);
  }
  audit("pacing-autonomy", { factions: affectedFactions, npcs: affectedNpcs });
}

// DISPOSITION / goal-overlap helpers shared by REQ-348 / REQ-338 / REQ-339.
function goalsOverlap(factionGoals: string[], npcGoal: string): boolean {
  const tokens = npcGoal.toLowerCase().split(/\s+/).filter((t) => t.length > 3);
  return factionGoals.some((g) => {
    const gt = g.toLowerCase();
    return tokens.some((t) => gt.includes(t) || gt.split(/\s+/).includes(t));
  });
}

// REQ-339 — generate/fetch a goal-pursuit suggestion for a goal-carrying NPC.
function ensureGoalSuggestion(novel: NovelState, npcId: string, name: string, goal: string): void {
  const existing = novel.npc_goal_suggestions.find((s) => s.npc_id === npcId);
  if (existing) return;
  novel.npc_goal_suggestions.push({ npc_id: npcId, text: `${name} pursues "${goal}" off-screen`, state: "pending" });
}

// REQ-339e — a session-boundary beat fires once per session. Prior surfacing
// is derived from the audit log rather than a new persisted marker.
function boundaryBeatFiredThisSession(novel: NovelState): boolean {
  let boundary = -1;
  let beat = -1;
  for (let i = 0; i < novel.audit_log.length; i++) {
    const tool = novel.audit_log[i].tool;
    if (tool === "[session-boundary]") boundary = i;
    else if (tool === "npc-boundary-beat") beat = i;
  }
  return boundary >= 0 && beat > boundary;
}

// REQ-355 through REQ-365 — navigational coupling advisories surfaced in
// narrative_threads. Each is advisory: the server suggests; the GM decides.
function collectCouplingAdvisories(novel: NovelState, entity: any): string[] {
  const out: string[] = [];
  const sceneLoc = (novel.scene_location ?? "").toLowerCase();

  // REQ-355 — secret-countdown: revealed secret whose key appears in a countdown scope/direction.
  for (const s of novel.secrets) {
    if (!s.known_by.length) continue;
    for (const [name, cd] of novel.countdowns) {
      const hay = `${cd.scope ?? ""} ${cd.direction ?? ""}`.toLowerCase();
      if (hay.includes(s.key.toLowerCase())) {
        out.push(`Countdown-advancement advisory: secret "${s.key}" relates to countdown "${name}" — advance or ignore.`);
      }
    }
  }

  // REQ-356 — vow-lore: vow name/description intersects lore triggers/keys.
  for (const v of novel.vows) {
    if (v.state !== "active") continue;
    for (const [, entry] of novel.lore) {
      const hay = `${entry.triggers.join(" ")} ${entry.key}`.toLowerCase();
      const vowText = `${v.name} ${v.description}`.toLowerCase();
      if (entry.triggers.some((t) => vowText.includes(t.toLowerCase())) || vowText.includes(entry.key.toLowerCase())) {
        out.push(`[vow-relevant] ${entry.key}`);
      }
    }
  }

  // REQ-357 — story journal-faction: consequence/moment referencing faction goal text.
  for (const s of novel.story_journal) {
    if (s.type !== "consequence" && s.type !== "moment") continue;
    for (const f of novel.factions) {
      for (const g of f.goals) {
        const gTokens = g.toLowerCase().split(/\s+/).filter((t) => t.length > 3);
        if (gTokens.some((t) => s.entry.toLowerCase().includes(t))) {
          out.push(`Faction-clock-advancement advisory: ${f.name} (goal "${g}") — advance or ignore.`);
        }
      }
    }
  }

  // REQ-359 — relationship-countdown: ally → rival/hostile flip referencing matched countdown.
  for (const [name, cd] of novel.countdowns) {
    const hay = `${cd.scope ?? ""} ${cd.direction ?? ""}`.toLowerCase();
    if (hay.length < 3) continue;
    for (const r of novel.relationships) {
      if (r.type === "rival" || (r.type as string) === "hostile") {
        if (hay.includes(r.entity_a.toLowerCase()) || hay.includes(r.entity_b.toLowerCase())) {
          out.push(`Relationship-countdown advisory: ${r.entity_a} -> ${r.entity_b} (${r.type}) relates to countdown "${name}".`);
        }
      }
    }
  }

  // REQ-360 — lore-countdown: lore with temporal urgency triggers suggests countdown creation.
  const urgencyWords = ["imminent", "approaching", "deadline", "ticking", "countdown"];
  for (const [, entry] of novel.lore) {
    if (!entry.enabled) continue;
    const matches = entry.triggers.filter((t) => urgencyWords.includes(t.toLowerCase()));
    if (!matches.length) continue;
    const existing = [...novel.countdowns.keys()].some((n) => n.toLowerCase().includes(entry.key.toLowerCase()) || (entry.key && n.toLowerCase().includes(entry.key.toLowerCase())));
    if (!existing) out.push(`Countdown-creation advisory: lore "${entry.key}" mentions urgency ("${matches.join(", ")}") — create a countdown or ignore.`);
  }

  // REQ-361 — NPC-vow: goal-carrying NPC suggests vow creation.
  for (const [, npc] of novel.npcs) {
    const goal = npc.personality?.goals;
    if (!goal || goal.length < vowSuggestionMinChars()) continue;
    const alreadyVowed = novel.vows.some((v) => v.state === "active" && (v.description ?? "").toLowerCase().includes(goal.toLowerCase()));
    if (!alreadyVowed) out.push(`Vow-creation suggestion: ${npc.name} seeks "${goal}" — create a vow via manage_vow (action: set) or ignore.`);
  }

  // REQ-077 / §7.7.1a P4 (NPC → Countdown) — goal-carrying NPCs in the current
  // scene produce a countdown-advancement advisory when their goal-text length
  // is at or above TTRPG_NPC_URGENCY_THRESHOLD.
  const urgencyThreshold = configInt("TTRPG_NPC_URGENCY_THRESHOLD", 40);
  const currentSceneLoc = (novel.scene_location ?? "").toLowerCase();
  for (const [, npc] of novel.npcs) {
    const goal = npc.personality?.goals;
    if (!goal || goal.length < urgencyThreshold) continue;
    const inScene = !currentSceneLoc || (npc.location ?? "").toLowerCase() === currentSceneLoc || (npc.room_id ?? "") === currentSceneLoc;
    if (!inScene) continue;
    out.push(`Countdown-advancement advisory: ${npc.name}'s urgent goal "${goal}" — advance a countdown or ignore.`);
  }

  // REQ-362 — faction-vow: faction goal intersecting known entities/locations prompts vow.
  for (const f of novel.factions) {
    for (const g of f.goals) {
      const knownText = `${[...novel.lore.values()].map((l) => l.content).join(" ")} ${novel.story_journal.map((s) => s.entry).join(" ")}`.toLowerCase();
      const gTokens = g.toLowerCase().split(/\s+/).filter((t) => t.length > 3);
      const intersects = gTokens.some((t) => knownText.includes(t));
      if (!intersects) continue;
      const alreadyVowed = novel.vows.some((v) => v.state === "active" && (v.description ?? "").toLowerCase().includes(g.toLowerCase()));
      if (!alreadyVowed) out.push(`Faction-vow suggestion: ${f.name} seeks "${g}" — create a vow or ignore.`);
    }
  }

  // REQ-363 — secret-world: world_target secret surfaces [world-linked] when scene resolves.
  for (const s of novel.secrets) {
    if (!s.world_target) continue;
    const targetRoom = [...novel.world.rooms.keys()].find((k) => k.toLowerCase() === s.world_target!.toLowerCase());
    if (targetRoom && sceneLoc && sceneLoc.startsWith(targetRoom.toLowerCase())) {
      out.push(`[world-linked] ${s.key}`);
    }
  }

  // REQ-364 — faction-world: territorial factions surface when scene matches territory.
  for (const f of novel.factions) {
    if (!f.territory?.length) continue;
    for (const t of f.territory) {
      if (sceneLoc && sceneLoc.startsWith(t.toLowerCase())) {
        out.push(hasFactionClock(f) ? `[territorial] ${f.name} (clock ${f.clock ?? 0}/${f.clock_max})` : `[territorial] ${f.name}`);
      }
    }
  }

  return out;
}

// REQ-083d/083e — `visibility` gates lore read access; `badge_scope` remains
// the briefing presentation priority. The GM and Editor badges see every
// entry; Player and Observer see shared and player-discovered entries
// (REQ-366 keeps Observer out of GM-only surfaces).
function loreVisible(entry: LoreEntry, badge: Badge): boolean {
  if (badge === "game_master" || badge === "none") return true;
  return entry.visibility === "shared" || entry.visibility === "player_discovered";
}

// REQ-083f — gm_only/player_discovered entries fire only when a knowing entity
// attends the scene; shared entries fire on keyword match regardless.
function lorePresenceSatisfied(novel: NovelState, entry: LoreEntry, badge: Badge): boolean {
  if (badge === "game_master" || badge === "none") return true;
  if (entry.visibility === "shared") return true;
  return (entry.known_by ?? []).some((id) => isPresent(novel, id));
}

// REQ-083a/REQ-155a/REQ-328a — activation for the briefing lore section:
// keyword match, a live sticky counter, or a world target reachable from the
// active entity's room. World-target activation is placement-based rather than
// a per-interaction log; the substitution is recorded in holonovel/DECISIONS.md
// under accepted tradeoffs with governing REQ-328a.
function loreActiveForSection(novel: NovelState, entry: LoreEntry): boolean {
  if (!entry.enabled) return false;
  const scene = (novel.scene_description ?? "").toLowerCase();
  if ((entry.triggers ?? []).some((t: string) => scene.includes(String(t).toLowerCase()))) return true;
  if ((entry as any).sticky_remaining > 0) return true;
  if ((entry as any).world_target) {
    const target = String((entry as any).world_target).toLowerCase();
    const activeId = novel.active_entity_id;
    const actor: any = activeId ? (novel.entities.get(activeId) ?? novel.npcs.get(activeId)) : null;
    const room = String(actor?.current_room ?? novel.scene_location ?? "").toLowerCase();
    if (target && room && (room === target || room.includes(target) || target.includes(room))) return true;
    for (const thing of novel.world.things.values()) {
      const names = [String((thing as any).name ?? ""), String((thing as any).id ?? "")].map((s) => s.toLowerCase());
      if (names.includes(target) && String((thing as any).location ?? "").toLowerCase() === room) return true;
    }
  }
  return false;
}

// REQ-083a/REQ-328b — rendered budget accounting, read by spec_health.
let recordedLoreBudget: { max_tokens: number | null; used_tokens: number; omitted_entries: number } | null = null;

// REQ-083a/REQ-083f/REQ-155a/REQ-328b — triggered lore section. Entries render
// in priority order (key breaks ties), world-targeted rows carry `[world]
// <target>`, and TTRPG_MAX_LORE_TOKENS caps the rendered set.
function composeLoreSection(novel: NovelState, badge: Badge): string {
  const active = [...novel.lore.values()]
    .filter((e) => loreVisible(e, badge) && loreActiveForSection(novel, e) && lorePresenceSatisfied(novel, e, badge))
    .sort((a, b) => ((b as any).priority ?? 0) - ((a as any).priority ?? 0) || a.key.localeCompare(b.key));
  const budget = state.maxLoreTokens;
  const lines: string[] = [];
  let usedChars = 0;
  let omitted = 0;
  for (const entry of active) {
    const world = (entry as any).world_target ? ` [world] ${(entry as any).world_target}` : "";
    const line = `- [${entry.key}]${world} ${entry.content}`;
    if (budget !== null && Math.ceil((usedChars + line.length) / 4) > budget) { omitted++; continue; }
    usedChars += line.length;
    lines.push(line);
  }
  recordedLoreBudget = { max_tokens: budget, used_tokens: Math.ceil(usedChars / 4), omitted_entries: omitted };
  if (lines.length === 0) return "";
  return `\n\n### Lore\n${lines.join("\n")}`;
}

// REQ-197c — the set of lore entries active for the current badge; `rich`
// detail reports newly active keys by diffing this set around a command.
function activeLoreKeys(novel: NovelState): Set<string> {
  const badge = getBadge();
  const keys = new Set<string>();
  for (const entry of novel.lore.values()) {
    if (loreVisible(entry, badge) && loreActiveForSection(novel, entry) && lorePresenceSatisfied(novel, entry, badge)) keys.add(entry.key);
  }
  return keys;
}

// REQ-286 — knowledge_state section: revealed secrets, participant relationships,
// presence-scoped lore, background knowledge, discovered consequences. Badge-filtered.
function composeKnowledgeState(novel: NovelState, entity: any, badge: Badge): string {
  let section = "";
  if (!entity) {
    section += `\n\n### Knowledge state\n[No active entity — knowledge state unavailable.]`;
    return section;
  }
  const activeId = entity.id;
  const present = isPresent(novel, activeId);

  const lines: string[] = [];
  // Revealed secrets (REQ-234/286).
  const knownSecrets = novel.secrets.filter((s) => s.known_by.includes(activeId));
  for (const s of knownSecrets) lines.push(`Secret: ${s.key} — ${s.content}`);

  // Participant relationships (REQ-236/286).
  const rels = dedupeRelationships(novel).filter((r) => isRelationshipInvolving(novel, r, activeId));
  for (const r of rels) {
    const { a, b } = relationshipEndpoints(novel, r);
    lines.push(`Relationship: ${a.name} -> ${b.name} (${r.type})`);
  }

  // Presence-scoped shared lore (REQ-286/308): lore triggered while entity present.
  for (const [, entry] of novel.lore) {
    if (!entry.enabled || entry.visibility !== "shared") continue;
    const triggered = entry.triggers.some((t) => novel.scene_description.toLowerCase().includes(t.toLowerCase()));
    if (triggered && present) lines.push(`Lore: [${entry.key}] ${entry.content}`);
  }

  // REQ-083d/083f — discovered lore is per-entity knowledge. It renders only
  // for an entity recorded by reveal, and only while that entity attends.
  for (const [, entry] of novel.lore) {
    if (!entry.enabled || entry.visibility !== "player_discovered") continue;
    if (!(entry.known_by ?? []).includes(activeId)) continue;
    const triggered = entry.triggers.some((t) => novel.scene_description.toLowerCase().includes(t.toLowerCase()));
    if (triggered && present) lines.push(`Lore: [${entry.key}] ${entry.content}`);
  }

  // Discovered consequences (REQ-340/349): [discovered] entries populate knowledge
  // only for the entities recorded as discoverers. Legacy entries with no
  // attribution fail closed; the GM story-journal surface still shows them.
  const discovered = novel.story_journal.filter((s) =>
    s.type === "consequence" && s.discovered && Array.isArray(s.entity_ids) && s.entity_ids.includes(activeId));
  for (const s of discovered) {
    // REQ-349a — the knowledge entry carries its source and countdown name.
    const source = s.countdown_name
      ? ` (source: discovered_consequence, countdown: ${s.countdown_name})`
      : ` (source: discovered_consequence)`;
    lines.push(`[discovered] ${s.entry}${source}`);
  }

  // REQ-345 — background knowledge directive when entity has a background.
  const background = entity.personality?.background;
  if (background) {
    lines.push(`Background knowledge: ${background} — the character may know things their background implies (regional geography, academic knowledge, underworld contacts) without having witnessed them in a scene.`);
    // REQ-350 — background lore triggering: match background tokens against shared lore triggers.
    const bgTokens = background.toLowerCase().split(/\s+/).filter((t: string) => t.length > 3);
    for (const [, entry] of novel.lore) {
      if (!entry.enabled || entry.visibility !== "shared") continue;
      const matched = entry.triggers.find((t: string) => bgTokens.some((bt: string) => bt.includes(t.toLowerCase()) || t.toLowerCase().includes(bt)));
      if (matched) lines.push(`[background-relevant] ${entry.key} (matched "${matched}")`);
    }
  }

  // REQ-330 — exploration-derived knowledge (rooms visited, things taken),
  // retained regardless of current presence; grouped as "Explored".
  const explored = (entity.knowledge?.explored ?? []) as Array<{ type: string; name: string; at: string }>;
  if (explored.length > 0) {
    const rooms = explored.filter((e) => e.type === "room").map((e) => e.name);
    const things = explored.filter((e) => e.type === "thing").map((e) => e.name);
    const exploredLines = [`Explored: ${rooms.join(", ") || "(none)"}`];
    if (things.length > 0) exploredLines.push(`Seen things: ${things.join(", ")}`);
    lines.push(exploredLines.join(" | "));
  }

  // REQ-594/REQ-595 — POV overlay: the active entity's derived perceptions,
  // each carrying how it was witnessed and its event provenance. Only the
  // active entity's own records are read here (REQ-545).
  const perceptions = novel.perception_ledger.filter((p) => p.entity_id === activeId).slice(-10);
  for (const p of perceptions) {
    const ordinal = p.event_ordinal !== null ? ` [#${p.event_ordinal}]` : "";
    lines.push(`Perceived (${p.witness}${p.sense ? `/${p.sense}` : ""}): ${p.summary}${ordinal}`);
  }

  section += `\n\n### Knowledge state`;
  if (!present) section += `\n[Entity not present in this scene]`;
  if (lines.length === 0) {
    section += `\n[No known information.]`;
  } else {
    section += `\n${lines.join("\n")}`;
  }
  return section;
}

// REQ-242b — notes reach badge_briefing under the `notes` token: the Game
// Master (and the Editor) see every scope; the Player and Observer see only
// `player` and `shared` entries. Empty notes render no section.
function composeNotesSection(novel: NovelState, badge: Badge): string {
  const allScopes = badge === "game_master" || badge === "none";
  const visible = novel.notes.filter((n) => allScopes || n.badge_scope !== "game_master");
  if (visible.length === 0) return "";
  const lines = visible.map((n) => `- ${n.key} [${n.badge_scope}]: ${n.content.length > 100 ? n.content.slice(0, 100) + "…" : n.content}`);
  return `\n\n### Notes (notes)\n${lines.join("\n")}`;
}

// REQ-236b — the transition set: ally ↔ rival, ally ↔ suspicious,
// rival ↔ suspicious, and any change involving neutral. A new row's previous
// type reads as neutral.
function shouldMarkRelationshipChange(previous: string | undefined, next: string | undefined): boolean {
  if (!next || previous === next) return false;
  if (!previous || previous === "neutral" || next === "neutral") return true;
  const pair = [previous, next].sort().join("|");
  return pair === "ally|rival" || pair === "ally|suspicious" || pair === "rival|suspicious";
}

function recordRelationshipMarker(novel: NovelState, row: Relationship, type: string, previousType?: string): void {
  const { a, b } = relationshipEndpoints(novel, row);
  const text = `Relationship changed: ${a.name} and ${b.name} are now ${type}.`;
  const list = relationshipMarkers.get(novel.slug) ?? [];
  if (!list.some((marker) => marker.text === text)) {
    list.push({ text, entity_ids: [a.id, b.id] });
    relationshipMarkers.set(novel.slug, list);
  }
  // REQ-233a1/a3 — the state change traces one hop immediately: the connected
  // endpoint records a campaign-memory fact naming the shift. The GM-facing
  // pending entry is enqueued from the scene's markers at the next transition.
  recordCampaignMemory(novel, "threads", `${b.name} now regards ${a.name} as ${type}.`, "game_master");
  enqueueWorldChange(novel, "relationship", `Relationship shift: ${a.name} and ${b.name} are now ${type}.`, [a.id, b.id]);

  // REQ-236a — only a flip between ally and rival (either direction) prompts
  // the lore consideration.
  const pair = [previousType ?? "neutral", type].sort().join("|");
  if (pair === "ally|rival") {
    const promptText = `Consider recording a lore entry for the shift between ${a.name} and ${b.name}.`;
    const prompts = relationshipLorePrompts.get(novel.slug) ?? [];
    if (!prompts.some((p) => p.text === promptText)) {
      prompts.push({ text: promptText, entity_ids: [a.id, b.id] });
      relationshipLorePrompts.set(novel.slug, prompts);
    }
  }
}

function relationshipMarkerLines(novel: NovelState, badge: Badge, activeId?: string): string[] {
  const list = relationshipMarkers.get(novel.slug) ?? [];
  if (badge === "game_master" || badge === "none") {
    // REQ-236a — the lore consideration follows the marker it belongs to.
    return [...list.map((marker) => marker.text), ...(relationshipLorePrompts.get(novel.slug) ?? []).map((p) => p.text)];
  }
  if (badge === "player" && activeId) {
    return list.filter((marker) => marker.entity_ids.includes(activeId)).map((marker) => marker.text);
  }
  return [];
}

// P48 — each involved NPC shifts one step toward suspicious on a flip to
// rival. Characters and factions are skipped; a more-hostile NPC is not
// softened.
function shiftRelationshipDispositions(novel: NovelState, row: Relationship): void {
  for (const token of [row.entity_a, row.entity_b]) {
    const party = resolveRelationshipParty(novel, token);
    if (!party) continue;
    const npc = novel.npcs.get(party.id);
    if (!npc) continue;
    const previous = npc.disposition ?? "neutral";
    const next = shiftDispositionToward(previous, "suspicious");
    if (next === previous) continue;
    npc.disposition = next;
    audit("relationship_disposition", {
      npc: npc.id,
      relationship: `${row.entity_a} -> ${row.entity_b}`,
      from: previous,
      to: next,
    });
  }
}

// REQ-598 — narrator clearance follows the AI's narrative role (REQ-304), not
// the human's badge. Under the counterpart setting the two diverge: the human
// may wear the Game Master badge while the AI inhabits a Player character, and
// the reverse. Clearance keyed to the badge would leak GM-only facts into the
// Player-role narrator's context.
type NarrativeRole = "game_master" | "player";

function narrativeRole(novel: NovelState): NarrativeRole | null {
  const setting = (process.env.TTRPG_AI_ROLE ?? "counterpart").toLowerCase();
  if (setting === "game_master" || setting === "player") return setting;
  if (novel.badge === "none") return null;
  return novel.badge === "game_master" ? "player" : "game_master";
}

// REQ-599 — visibility mode. An unknown value falls back to advisory once.
let visibilityModeWarned = false;
function narratorVisibilityMode(): "strict" | "advisory" {
  const raw = (process.env.TTRPG_NARRATOR_VISIBILITY ?? "advisory").toLowerCase();
  if (raw === "strict" || raw === "advisory") return raw;
  if (!visibilityModeWarned) {
    visibilityModeWarned = true;
    process.stderr.write(`[holonovel] unknown TTRPG_NARRATOR_VISIBILITY '${raw}'; using advisory\n`);
  }
  return "advisory";
}

interface ClearedFacts {
  role: NarrativeRole;
  audience: Badge;
  pov: { entity_id: string | null; entity_name: string | null; mode: "character" | "omniscient" };
  scene: string;
  knowledge: string;
  npcs: Array<Record<string, any>>;
  gm_only: string[];
}

// REQ-598 — derive narration facts from the existing knowledge-state composer
// (REQ-286) and NPC mind stripper (REQ-075f). Only the role gate is new; no
// parallel knowledge system is introduced.
function composeClearedFacts(novel: NovelState, role: NarrativeRole): ClearedFacts {
  const entity = state.getActiveEntity();
  const isGM = role === "game_master";
  const knowledge = composeKnowledgeState(novel, entity, isGM ? "game_master" : "player");
  const npcs = [...novel.npcs.values()].map((npc) => sanitizeNpcForBadge(npc, isGM));
  const gm_only: string[] = [];
  if (isGM) {
    for (const s of novel.secrets) gm_only.push(`Secret: ${s.key} — ${s.content}`);
    for (const [, entry] of novel.lore) {
      if (entry.enabled && entry.visibility !== "shared") gm_only.push(`Lore: [${entry.key}] ${entry.content}`);
    }
    for (const note of novel.notes) {
      if (note.badge_scope === "game_master") gm_only.push(`Note: [${note.key}] ${note.content}`);
    }
    for (const [, npc] of novel.npcs) {
      if (npc.mind) gm_only.push(`NPC mind (${npc.name}): ${JSON.stringify(npc.mind)}`);
    }
  }
  return {
    role,
    audience: novel.badge,
    pov: { entity_id: entity?.id ?? null, entity_name: entity?.name ?? null, mode: novel.pov_mode },
    scene: novel.scene_description ?? "",
    knowledge,
    npcs,
    gm_only,
  };
}

// REQ-598 — narrator-facing contract. The tool surface hands the host raw
// state (counters, exits, inventory); this contract keeps that state out of
// the prose and out of unvisited-place spoilers.
const NARRATION_CONTRACT_SHORT =
  "Prose only: never state counters, dials, resource numbers, dispositions, inventory or exit lists, or tool output in the narration; name no floor, room, or destination the character has not entered or been told about, and no authorial theme; keep any permitted numeric status on a separate line after the prose.";
const NARRATION_CONTRACT =
  `${NARRATION_CONTRACT_SHORT} Tool output lines beginning "You can see:" and "Exits:" are UI state, not narration.`;

// REQ-598 — the narrator prompt. `badge_briefing` stays the human-badge
// briefing (REQ-220/286); this surface is role-scoped.
// REQ-598a — scene-type anchoring (§7.3a). The narrator receives a tone
// directive per active scene type; because the tags are Novel state re-read on
// every render, the directive persists for the scene's duration without a
// second stored surface. Scene types outside this table (ruleset-extracted
// tags) contribute no directive of their own.
const SCENE_TONE: Record<string, string> = {
  combat: "danger and momentum — short sentences, physical stakes, no comic relief",
  social: "interpersonal tension — subtext, posture, and what characters avoid saying",
  exploration: "discovery — unfamiliar detail, distance, and the cost of moving",
  neutral: "observational — steady pacing, no dramatic emphasis",
};

function sceneToneLines(sceneTypes: readonly string[] | undefined): string[] {
  const active = (sceneTypes ?? []).map((t) => String(t).toLowerCase());
  const directives = active
    .map((t) => SCENE_TONE[t])
    .filter((d): d is string => Boolean(d));
  const chosen = directives.length > 0 ? directives : [SCENE_TONE.neutral];
  return [`### Scene tone`, ...chosen.map((d) => `- ${d}`)];
}

function composeNarrationClearance(novel: NovelState, role: NarrativeRole): string {
  const facts = composeClearedFacts(novel, role);
  const lines: string[] = [
    `## Narration clearance`,
    `**Narrative role:** ${role === "game_master" ? "Game Master" : "Player"}`,
    `**Audience:** ${badgeLabel(facts.audience)}`,
    `**Scene:** ${facts.scene || "[no scene set]"}`,
    ...sceneToneLines(novel.scene_type),
    `### Point of view`,
    facts.pov.mode === "character" && facts.pov.entity_name
      ? `Describe the scene through ${facts.pov.entity_name}'s eyes — what they see, hear, and feel.`
      : "POV: none — narration is omniscient.",
    `### Cleared knowledge`,
    facts.knowledge.trim() || "[No known information.]",
  ];
  if (facts.npcs.length > 0) {
    lines.push(`### Present characters`);
    for (const npc of facts.npcs) {
      const desc = npc.description ? ` — ${npc.description}` : "";
      lines.push(`- ${npc.name}${npc.disposition ? ` (${npc.disposition})` : ""}${desc}`);
    }
  }
  if (role === "game_master" && facts.gm_only.length > 0) {
    lines.push(`### GM-only facts`);
    lines.push(...facts.gm_only);
  }
  // REQ-611/612 — name the deterministic speaker first, then ensemble direction.
  if (facts.npcs.length > 0) {
    const cast = novel.social_cast;
    const selected = cast.selected ? facts.npcs.find((n: any) => n.id === cast.selected) : undefined;
    const unspoken = facts.npcs.find((n: any) => !cast.spoken.includes(n.id));
    const speaker = selected ?? unspoken ?? facts.npcs[0];
    lines.push(`### Speaker this turn`);
    lines.push(`- ${speaker.name}${selected ? " (manual selection)" : ""}.`);
    if (role === "game_master" && facts.npcs.length >= 2) {
      const ordered = [...facts.npcs].sort((a: any, b: any) => (Number(b.talkativeness) || 50) - (Number(a.talkativeness) || 50));
      lines.push(`- Talkativeness order: ${ordered.map((n: any) => `${n.name} ${Number(n.talkativeness) || 50}`).join(", ")}.`);
    }
  }
  // REQ-598 — ensemble cast direction prevents monologue and voice bleed.
  if (facts.npcs.length >= 2) {
    lines.push(`### Cast direction`);
    lines.push(`- Name the speaker for this turn before their dialogue.`);
    lines.push(`- Never speak for the player character or decide the player's actions.`);
    lines.push(`- Render each NPC from its voice and voice examples; keep voices distinct.`);
  }
  lines.push(`### Narration contract`);
  lines.push(NARRATION_CONTRACT);
  if (novel.narrative_directive) {
    lines.push(`### Narrative directive`);
    lines.push(novel.narrative_directive);
  }
  // REQ-598 — active narrative-voice profiles are standing directives; the
  // profile description must reach the narrator, not just its name.
  const voiceProfiles = effectiveWisdomItems("narrative_voices").filter(badgeCanSeeWisdom);
  if (voiceProfiles.length > 0) {
    lines.push(`### Narrative voices`);
    for (const v of voiceProfiles.slice(0, 3)) {
      lines.push(`- ${v.name}${v.description ? ` — ${String(v.description).slice(0, 320)}` : ""}`);
    }
  }
  lines.push(`### Narration instruction`);
  lines.push(`Narrate only from the cleared facts above. Do not state, hint at, or imply anything absent from them. Before emitting prose for a Player or Observer audience, call manage_diagnostics (action: visibility_check, text: "<draft>") and use the returned text.`);
  return applyPromptBudget(lines.join("\n"));
}

// REQ-599 — verbatim visibility scan. Only exact key or content disclosure is
// matched; paraphrase and implication are out of scope. Common-noun keys are
// suppressed so a generic key such as "trap" does not redact ordinary prose.
const VISIBILITY_KEY_ALLOWLIST = new Set([
  "trap", "door", "key", "secret", "treasure", "gold", "map", "clue",
  "tower", "dragon", "murder", "room", "chest", "guard", "king", "queen",
]);

function escapeRegExpLiteral(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function visibilityAudienceScans(audience: Badge): boolean {
  return audience === "player" || audience === "observer";
}

interface VisibilityTarget { kind: string; phrase: string; key: boolean }

function collectVisibilityTargets(novel: NovelState): VisibilityTarget[] {
  const targets: VisibilityTarget[] = [];
  const activeId = state.getActiveEntity()?.id;
  for (const s of novel.secrets) {
    if (s.badge_scope !== "game_master") continue;
    // A secret already revealed to the active entity is legitimately visible
    // through the knowledge-state section (REQ-286), so it is not a leak.
    if (activeId && s.known_by.includes(activeId)) continue;
    targets.push({ kind: "secret key", phrase: s.key, key: true });
    targets.push({ kind: "secret content", phrase: s.content, key: false });
  }
  for (const [, entry] of novel.lore) {
    if (!entry.enabled) continue;
    // REQ-083d/083f — GM-only lore is always a leak target; player-discovered
    // lore is a target for an entity that did not learn it.
    const gmOnly = entry.visibility === "gm_only";
    const undiscovered = entry.visibility === "player_discovered" && !(activeId && entry.known_by.includes(activeId));
    if (!gmOnly && !undiscovered) continue;
    const kind = gmOnly ? "GM-only lore" : "undiscovered lore";
    targets.push({ kind: `${kind} key`, phrase: entry.key, key: true });
    targets.push({ kind: `${kind} content`, phrase: entry.content, key: false });
  }
  for (const note of novel.notes) {
    if (note.badge_scope !== "game_master") continue;
    targets.push({ kind: "GM-only note key", phrase: note.key, key: true });
    targets.push({ kind: "GM-only note content", phrase: note.content, key: false });
  }
  for (const [, npc] of novel.npcs) {
    const directive = (npc as any)?.mind?.directive;
    if (typeof directive === "string" && directive.length > 0) targets.push({ kind: "NPC mind directive", phrase: directive, key: false });
  }
  // REQ-599b — a `secret` memory is a leak target in full; a `guarded` memory
  // withholds its gist from its owner but never its claim or affect.
  for (const r of novel.subjective_memory ?? []) {
    targets.push(...disclosureScanTargets(r, activeId ?? null));
  }
  return targets;
}

function scanDraft(draft: string, targets: VisibilityTarget[]): { text: string; kinds: string[] } {
  let text = draft;
  const kinds: string[] = [];
  for (const target of targets) {
    const phrase = (target.phrase ?? "").trim();
    if (phrase.length < 4) continue;
    if (target.key && VISIBILITY_KEY_ALLOWLIST.has(phrase.toLowerCase())) continue;
    if (!target.key && phrase.length < 12) continue;
    const escaped = escapeRegExpLiteral(phrase);
    const pattern = target.key
      ? new RegExp(`(?<![\\p{L}\\p{N}])${escaped}(?![\\p{L}\\p{N}])`, "giu")
      : new RegExp(escaped, "gi");
    if (!pattern.test(text)) continue;
    pattern.lastIndex = 0;
    kinds.push(target.kind);
    text = text.replace(pattern, "[redacted]");
  }
  return { text, kinds };
}

// ── Helpers ────────────────────────────────────────────────────────
// Badge gating and snapshot helpers provided by core/server.ts

initServer(state);

// ── Performance / token-efficiency contracts (REQ-408, REQ-409, REQ-410, REQ-411) ──

// REQ-408 — tool parameter ceiling, recorded at build time. The reference host
// computes the ceiling from its own registrations rather than hardcoding a
// blind cap: the ceiling is the maximum parameter count any single tool exposes.
// REQ-408 (amended, REQ-413): for an action-discriminator tool, the ceiling is
// evaluated per action — against the tool's *required* parameters (the action
// discriminator plus any required fields of a single operation), not the union
// of every optional field the tool may accept across actions.
const PARAMETER_CEILING = 8;

// REQ-411 — stable-metadata caching. Rendered listings (tool schemas, prompt
// scaffolding) are derived from live registrations and re-render only when the
// registration set changes (registration fingerprint). Cache entries hold the
// rendered bytes plus the fingerprint they were rendered from.
interface MetadataCache {
  fingerprint: string;
  toolsListBytes: number;
  toolParameterCounts: Record<string, number>;
  toolRequiredParamCounts: Record<string, number>;
  actionToolNames: Set<string>;
  promptBytes: number;
}
interface PackagePromptEntry { slug: string; prompt: RulesetPrompt }
const packagePrompts = new Map<string, PackagePromptEntry>();
const packagePromptErrors: Array<{ slug: string; reason: string }> = [];

function registrationFingerprint(): string {
  const tools = registeredToolMap();
  const prompts = (server as any)._registeredPrompts ?? {};
  return crypto.createHash("sha1")
    .update([...Object.keys(tools)].sort().join(","))
    .update("|")
    .update([...Object.keys(prompts)].sort().join(","))
    .update("|")
    .update([...packagePrompts.keys()].sort().join(","))
    .update("|")
    // REQ-389c — the served surface follows the install set, so every cache
    // keyed on this fingerprint must too.
    .update([...rulesets.installedSlugs()].sort().join(","))
    .digest("hex");
}
let metadataCache: MetadataCache | null = null;
let cacheHits = 0;
let cacheMisses = 0;

// REQ-392 — tool-description budget: descriptions fit a recorded budget;
  // spec_health reports `tools_list_bytes` (aggregate default tools/list size).
function isOptionalShape(schema: any, key: string): boolean {
  const field = schema?.shape?.[key];
  if (!field) return true;
  const def = field._def ?? field._zod?.def ?? {};
  const typeName = def.typeName ?? field.constructor?.name ?? "";
  if (typeName === "ZodOptional") return true;
  return !!def.innerType || !!field.isOptional?.();
}
function computeToolMetrics() {
  const tools: Record<string, any> = registeredToolMap();
  let bytes = 0;
  const counts: Record<string, number> = {};
  const requiredCounts: Record<string, number> = {};
  const actionToolNames = new Set<string>();
  for (const [name, tool] of Object.entries(tools)) {
    const desc = (tool?.description ?? "");
    const schema = tool?.inputSchema;
    const shape = (schema && (schema as any).shape) ? Object.keys((schema as any).shape) : [];
    counts[name] = shape.length;
    let required = 0;
    for (const key of shape) {
      if (!isOptionalShape(schema, key)) required++;
    }
    requiredCounts[name] = required;
    if (shape.includes("action")) actionToolNames.add(name);
    bytes += Buffer.byteLength(desc, "utf-8") + 64; // name overhead + description
    for (const key of shape) bytes += Buffer.byteLength(key, "utf-8") + 16;
  }
  return { bytes, counts, requiredCounts, actionToolNames };
}

// REQ-414 — schema-surface economy: count advertised inputs using nested
// structural form (union/array/object) vs. compact scalar form. REQ-413 —
// action-discriminator surface: tools that carry an `action`/`mode`/`kind`
// discriminator parameter are reported with their per-action contracts.
function schemaSurfaceMetrics() {
  const tools: Record<string, any> = registeredToolMap();
  const nestedCount: Record<string, number> = {};
  const discriminators: Record<string, { param: string; type: string }> = {};
  for (const [name, tool] of Object.entries(tools)) {
    const schema = tool?.inputSchema;
    const shape = (schema && (schema as any).shape) ? Object.keys((schema as any).shape) : [];
    const nested = shape.filter((k: string) => {
      const t = (schema as any).shape[k];
      return t && ["ZodUnion", "ZodArray", "ZodObject"].some((s) => t._zod?.constructor?.name === s || t.constructor?.name === s);
    });
    if (nested.length > 0) nestedCount[name] = nested.length;
    for (const d of ["action", "mode", "kind"]) {
      if (shape.includes(d)) {
        discriminators[name] = { param: d, type: String((schema as any).shape[d]?.constructor?.name ?? "enum") };
        break;
      }
    }
  }
  return { nested_input_counts: nestedCount, action_discriminators: discriminators };
}

// REQ-025/REQ-450 — deterministic host-tool quality signals (report-only):
// three-clause structure, non-tautological opening, sibling disambiguation, and
// title length. Mirrors scripts/tool-definitions-lint.ts so definition drift is
// visible at runtime as well as at build time.
function hostToolQuality() {
  const tools: Record<string, any> = registeredToolMap();
  // REQ-430 — ruleset-derived tools are validated separately by
  // rulesets.toolQualityCounts(); this check covers host tools only.
  const hostNames = Object.keys(TOOL_ANNOTATIONS).filter((n) => n in tools);
  const names = new Set(hostNames);
  const defects: Record<string, string[]> = {};
  for (const name of hostNames) {
    const tool = tools[name];
    const desc = typeof tool?.description === "string" ? tool.description : "";
    const lower = desc.toLowerCase();
    const list: string[] = [];
    if (!lower.includes("use when") || !lower.includes("do not use when")) list.push("missing three-clause structure");
    const title = typeof tool?.title === "string" ? tool.title : "";
    if (title.length < name.length) list.push("title shorter than name");
    const notIdx = lower.indexOf("do not use when");
    if (notIdx !== -1) {
      const clause = desc.slice(notIdx);
      if (![...names].some((n) => n !== name && clause.includes(n))) list.push("no sibling tool named in Do-NOT clause");
    }
    if (list.length > 0) defects[name] = list;
  }
  return { checked: hostNames.length, defective: Object.keys(defects).length, defects };
}

// REQ-552/REQ-553/REQ-554/REQ-555 — deterministic TDQS conformance report over
// the live registered surface. The graded TDQS is external; this reports the
// build-contract proxies: hard gates, dimension proxies, coherence, shadowing.
function zodBaseType(value: any): any {
  let current = value;
  for (let i = 0; i < 4 && current; i++) {
    if (current.type === "optional" || current.type === "default" || current.type === "nullable") {
      current = current.unwrap?.() ?? current._def?.innerType ?? null;
      continue;
    }
    break;
  }
  return current;
}
function zodToJsonSchema(schema: any, depth = 0): any {
  if (!schema || typeof schema !== "object" || depth > 4) return { type: "string" };
  const base = zodBaseType(schema);
  const description =
    typeof schema?.description === "string" ? schema.description
    : typeof base?.description === "string" ? base.description
    : undefined;
  const shape = base?.shape;
  if (shape && typeof shape === "object") {
    const properties: Record<string, any> = {};
    const required: string[] = [];
    for (const [key, value] of Object.entries(shape)) {
      if (!isOptionalShape(base, key)) required.push(key);
      properties[key] = zodToJsonSchema(value, depth + 1);
    }
    return { type: "object", properties, required, ...(description ? { description } : {}) };
  }
  if (base?.type === "array") {
    const element = base._def?.element ?? base.element;
    const items = element ? zodToJsonSchema(element, depth + 1) : { type: "string" };
    return { type: "array", items, ...(description ? { description } : {}) };
  }
  if (base?.type === "enum") {
    const values = base.options ?? Object.values(base.enum ?? {});
    return { type: "string", enum: [...values], ...(description ? { description } : {}) };
  }
  const type = base?.type === "number" || base?.type === "bigint" ? "number"
    : base?.type === "boolean" ? "boolean"
    : base?.type === "object" ? "object"
    : "string";
  return { type, ...(description ? { description } : {}) };
}

function registeredToolDefinitions(): ToolDefinition[] {
  const tools: Record<string, any> = registeredToolMap();
  const hidden = hiddenAliasNames(surfaceRegistry());
  return Object.entries(tools).filter(([name]) => !hidden.has(name) && packageToolVisible(name)).map(([name, tool]) => ({
    name,
    title: typeof tool?.title === "string" ? tool.title : "",
    description: typeof tool?.description === "string" ? tool.description : "",
    inputSchema: zodToJsonSchema(tool?.inputSchema),
    outputSchema: tool?.outputSchema ?? null,
    annotations: tool?.annotations ?? null,
    // REQ-379b — the same ruleset annotation the served `tools/list` carries,
    // so the measured footprint and the served catalog cannot drift.
    _meta: { ruleset: packageSlugForTool(name) ?? null },
  }));
}

interface CatalogSize { bytes: number; tokens: number; }
interface MeasuredSurface { full: CatalogSize; standard: CatalogSize; small: CatalogSize; active: CatalogSize; }
// REQ-391a/REQ-391c — the default listing is scoped to infrastructure plus the
// active Novel's ruleset. Package tools are slug-namespaced (REQ-430). With no
// Novel active, no package tools appear, so the default size does not grow with
// the installed-package count.
function scopedCatalog<T extends { name: string }>(tools: T[], all = false): T[] {
  if (all) return tools;
  const slugs = rulesets.installedSlugs();
  if (slugs.length === 0) return tools;
  const active = state.activeNovel?.ruleset;
  return tools.filter((tool) => {
    const pkg = slugs.find((slug) => tool.name.startsWith(`${slug}_`));
    return pkg === undefined || pkg === active;
  });
}
let surfaceMeasurementCache: { fingerprint: string; activeGroup: string; activeSlug: string; result: MeasuredSurface } | null = null;
function catalogSize(tools: unknown[]): CatalogSize {
  const bytes = Buffer.byteLength(JSON.stringify(tools), "utf-8");
  return { bytes, tokens: Math.ceil(bytes / 4) };
}
let liveToolCache: any[] | null = null;
function measuredSurface(): MeasuredSurface {
  const fingerprint = registrationFingerprint();
  const activeGroup = activeSurfaceGroup();
  const activeSlug = state.activeNovel?.ruleset ?? "";
  if (surfaceMeasurementCache
    && surfaceMeasurementCache.fingerprint === fingerprint
    && surfaceMeasurementCache.activeGroup === activeGroup
    && surfaceMeasurementCache.activeSlug === activeSlug) {
    return surfaceMeasurementCache.result;
  }
  const registry = surfaceRegistry();
  const definitions = scopedCatalog((liveToolCache ?? registeredToolDefinitions()) as any[]);
  const sizeFor = (profile: "full" | "standard" | "small", group: string | null = null): CatalogSize =>
    catalogSize(projectSurfaceTools(definitions as any, { profile, group, activeGroup, registry }) as unknown[]);
  const full = sizeFor("full");
  const standard = sizeFor("standard");
  let small: CatalogSize = { bytes: 0, tokens: 0 };
  for (const group of registry?.taxonomy.groups ?? []) {
    const measured = sizeFor("small", group);
    if (measured.bytes > small.bytes) small = measured;
  }
  const result = { full, standard, small, active: { full, standard, small }[surfaceProfile()] };
  surfaceMeasurementCache = { fingerprint, activeGroup, activeSlug, result };
  return result;
}

// REQ-606, REQ-607 — the serialized active catalog is the stable naming surface
// the ledger hashes. It uses the same projection as measuredSurface so the
// prefix and the reported catalog size cannot describe different payloads.
function activeCatalogText(): string {
  const registry = surfaceRegistry();
  const definitions = scopedCatalog((liveToolCache ?? registeredToolDefinitions()) as any[]);
  return JSON.stringify(
    projectSurfaceTools(definitions as any, {
      profile: surfaceProfile(),
      group: null,
      activeGroup: activeSurfaceGroup(),
      registry,
    }) as unknown[],
  );
}

// REQ-606 — side-effect-free section text. `badge_briefing` is deliberately not
// rendered here: it advances the pacing counter (REQ-336/351), and a read-only
// ledger must not mutate Novel state.
function contextSectionTexts(): Record<string, string> {
  const novel = state.activeNovel;
  const isGM = getBadge() === "game_master" || getBadge() === "none";
  const prompts: Record<string, any> = (server as any)._registeredPrompts ?? {};
  const promptText = Object.entries(prompts)
    .map(([name, prompt]) => `${name} ${prompt?.description ?? ""}`.trim())
    .sort()
    .join("\n");
  const resourceText = REQ022_URI_CATALOG.map(({ template, title }) => `${template} ${title}`).join("\n");
  const sceneText = novel
    ? JSON.stringify({
      location: novel.scene_location ?? null,
      description: novel.scene_description ?? "",
      entities: novel.entities.size,
      npcs: novel.npcs.size,
    })
    : "";
  const memoryText = novel
    ? deriveRecentTier(
      isGM ? novel.event_log : novel.event_log.filter((e) => e.source !== "game_master"),
      configInt("TTRPG_MEMORY_RECENT_EVENTS", 10),
    ).text
    : "";
  // REQ-179c — the ledger is the store's second reader: it carries the newest
  // payload the active badge may see, or an empty section.
  let lastOutputKey: string | undefined;
  for (const [key, payload] of outputStore) if (outputReadable(payload)) lastOutputKey = key;
  return {
    tool_catalog: activeCatalogText(),
    registered_prompts: promptText,
    resource_directory: resourceText,
    scene_state: sceneText,
    memory_tiers: memoryText,
    last_tool_output: lastOutputKey ? outputStore.get(lastOutputKey)!.pointer : "",
  };
}

// REQ-606, REQ-607, REQ-610 — the ledger shared by `context_report` and
// `spec_health`; an optional budget adds the allocator's packing decision.
function contextLedgerReport(budgetTokens?: number) {
  const report = buildContextLedger({ profile: surfaceProfile(), sections: contextSectionTexts() });
  if (budgetTokens === undefined) return report;
  return { ...report, allocation: allocateContextBudget(report, budgetTokens) };
}

// REQ-554 — the coherence proxies bind the host tool surface. Ruleset-derived
// tools are namespaced per package and governed by REQ-430 (reported under
// ruleset_tool_quality), so they are excluded here rather than blended into the
// host's verb_noun and tool-count proxies.
function hostToolDefinitions(): ToolDefinition[] {
  const slugs = rulesets.installedSlugs();
  return registeredToolDefinitions().filter(
    (d) => !slugs.some((slug) => d.name.startsWith(`${slug}_`)),
  );
}

let tdqsHealthCache: { fingerprint: string; result: ReturnType<typeof computeTdqsHealth> } | null = null;
function recordedDisambiguationAxes(): Record<string, string[]> | undefined {
  try {
    const data = JSON.parse(fs.readFileSync(path.join(path.dirname(__filename), "..", "tool-disambiguation.json"), "utf-8"));
    const axes: Record<string, string[]> = {};
    for (const [name, entry] of Object.entries(data.axes ?? {})) {
      axes[name] = Array.isArray((entry as any)?.resolves) ? (entry as any).resolves : [];
    }
    return axes;
  } catch {
    // The record is a build artifact; a missing copy leaves the proxy at its
    // conservative default rather than blocking health reporting.
    return undefined;
  }
}
function computeTdqsHealth() {
  const report = conformanceReport(hostToolDefinitions(), undefined, recordedDisambiguationAxes());
  return {
    scope: "host" as const,
    tool_count: report.toolCount,
    mean_tdqs: report.meanTdqs,
    min_tdqs: report.minTdqs,
    description_quality: report.descriptionQuality,
    description_quality_tier: report.descriptionQualityTier,
    below_passing: report.belowPassing,
    hard_gate_defects: report.hardGateDefects,
    coherence: report.coherence,
    shadowing_risks: report.shadowingRisks,
  };
}

function tdqsHealth() {
  const fingerprint = registrationFingerprint();
  if (tdqsHealthCache?.fingerprint === fingerprint) return tdqsHealthCache.result;
  const result = computeTdqsHealth();
  tdqsHealthCache = { fingerprint, result };
  return result;
}

function promptScaffoldBytes() {
  const prompts: any[] = (server as any)._registeredPrompts ? Object.values((server as any)._registeredPrompts) : [];
  const hostBytes = prompts.reduce((n, p) => n + Buffer.byteLength(p?.description ?? "", "utf-8") + Buffer.byteLength(p?.name ?? "", "utf-8") + 32, 0);
  const packageBytes = packagePromptList().reduce((n, p) => n + Buffer.byteLength(p.description, "utf-8") + Buffer.byteLength(p.name, "utf-8") + 32, 0);
  return hostBytes + packageBytes;
}

// Return cached metadata when registrations are unchanged; recompute otherwise.
function cachedMetadata(): MetadataCache {
  const fp = registrationFingerprint();
  if (metadataCache && metadataCache.fingerprint === fp) {
    cacheHits++;
    return metadataCache;
  }
  cacheMisses++;
  const { bytes, counts, requiredCounts, actionToolNames } = computeToolMetrics();
  metadataCache = {
    fingerprint: fp,
    toolsListBytes: bytes,
    toolParameterCounts: counts,
    toolRequiredParamCounts: requiredCounts,
    actionToolNames,
    promptBytes: promptScaffoldBytes(),
  };
  return metadataCache;
}
// ── Tool Surface Contract (REQ-567, REQ-568, REQ-570, REQ-571, REQ-572, REQ-580) ──
interface SurfaceDeclaration {
  group: string;
  phases: string[];
  entry: boolean;
  mutation_class: string;
  ruleset: string | null;
  preconditions: string[];
  successors: string[];
  edges: string[];
  compatibility?: { replacement: string; retired?: boolean };
}
interface SurfaceRegistry {
  schema_version: number;
  taxonomy: { groups: string[]; phases: string[]; mutation_classes: string[] };
  actions: Record<string, SurfaceDeclaration>;
}
let surfaceRegistryCache: SurfaceRegistry | null | undefined;
function surfaceRegistry(): SurfaceRegistry | null {
  if (surfaceRegistryCache !== undefined) return surfaceRegistryCache;
  try {
    const file = path.join(__dirname, "..", "tool-surface-registry.json");
    surfaceRegistryCache = JSON.parse(fs.readFileSync(file, "utf8")) as SurfaceRegistry;
  } catch {
    // The registry is a build artifact; a missing copy degrades to the full
    // catalog rather than failing server startup.
    surfaceRegistryCache = null;
  }
  return surfaceRegistryCache;
}
let surfaceOverrideCount = 0;

// REQ-583 — observed selection signals, accumulated since startup from the
// refusal and dispatch paths. Reported in spec_health beside the static surface
// report; no outbound inference is involved.
const selectionTelemetry = {
  projection_refusals: 0,
  undeclared_cross_group_calls: 0,
  unknown_tool_calls: 0,
  discovery_to_call: 0,
};
let discoveryPendingCall = false;

// REQ-588 — search result budget. Presentation-only: bounds the context one
// search call returns; excess results are suppressed and counted.
function searchMaxTokens(): number {
  const raw = process.env.TTRPG_SEARCH_MAX_TOKENS;
  const n = raw === undefined ? NaN : Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 20000;
}
let searchBudgetStats = { max_tokens: searchMaxTokens(), last_returned: 0, last_suppressed: 0 };

// REQ-574/577 — composite turn handles. A handle is minted by `take_turn` and
// consumed by `manage_story (action: record)`; it is session-scoped, bounded,
// and never persisted.
interface TurnHandle { intent: string; created: number; }
const turnHandles = new Map<string, TurnHandle>();
function mintTurnHandle(intent: string): string {
  const id = crypto.randomUUID();
  turnHandles.set(id, { intent, created: Date.now() });
  while (turnHandles.size > 64) {
    const oldest = turnHandles.keys().next().value;
    if (oldest) turnHandles.delete(oldest);
  }
  return id;
}
function toolResultText(result: any): string {
  return (result?.content ?? []).map((part: any) => part?.text ?? "").join("\n");
}
function surfaceProfile(): "full" | "standard" | "small" {
  return normalizeProfile(process.env.TTRPG_SURFACE_PROFILE);
}
function activeSurfaceGroup(): string {
  const novel = state.activeNovel;
  if (!novel) return "table";
  if (novel.combat?.active) return "resolve";
  return "explore";
}
function toolGroupSet(name: string): Set<string> {
  return surfaceToolGroups(surfaceRegistry(), name);
}
function projectToolList<T extends { name: string }>(
  tools: T[],
  group?: string,
  profile?: string,
): T[] {
  const requested =
    profile === "full" || profile === "standard" || profile === "small" ? profile : surfaceProfile();
  return projectSurfaceTools(tools as any, {
    profile: requested,
    group: group ?? null,
    activeGroup: activeSurfaceGroup(),
    registry: surfaceRegistry(),
  }) as T[];
}
interface GroupDirectoryEntry {
  group: string;
  entry: string | null;
  tools: string[];
  actions: number;
}
function groupDirectory(): GroupDirectoryEntry[] {
  const reg = surfaceRegistry();
  if (!reg) return [];
  const badge = getBadge();
  const out: GroupDirectoryEntry[] = [];
  for (const group of reg.taxonomy.groups) {
    const members = Object.entries(reg.actions).filter(([key, decl]) => {
      if (decl.compatibility) return false;
      if (decl.group !== group) return false;
      const tool = key.includes(".") ? key.slice(0, key.indexOf(".")) : key;
      return toolsVisibleToBadge(tool, badge, toolRegistry.get(tool)?.config.annotations);
    });
    if (members.length === 0) continue;
    const entry = members.find(([, decl]) => decl.entry)?.[0] ?? null;
    const tools = new Set(
      members.map(([key]) => (key.includes(".") ? key.slice(0, key.indexOf(".")) : key)),
    );
    out.push({ group, entry, tools: [...tools].sort(), actions: members.length });
  }
  return out;
}
function liveSurfaceActions(): Set<string> {
  const live = new Set<string>();
  for (const [name, tool] of Object.entries(registeredToolMap())) {
    const action = (tool as { inputSchema?: { shape?: Record<string, any> } })?.inputSchema?.shape?.action;
    const values =
      action?._def?.values ?? action?._def?.innerType?._def?.values ?? action?._def?.type?._def?.values;
    if (Array.isArray(values) && values.length) {
      for (const value of values) live.add(`${name}.${String(value)}`);
    } else {
      live.add(name);
    }
  }
  return live;
}

// REQ-573/575 — mechanical refusal before a tool handler runs. Returns a
// refusal envelope or null. The Editor bypass lives in surfaceGuard.
function surfaceRefusal(name: string, args: Record<string, unknown>): string | null {
  const reg = surfaceRegistry();
  if (!reg) return null;
  const action = typeof args?.action === "string" ? args.action : null;
  const key = action ? `${name}.${action}` : name;
  const decl = reg.actions[key] ?? reg.actions[name];
  if (!decl) return null;

  // Always-visible globals are callable from every group (REQ-570).
  if (SURFACE_GLOBALS.has(name)) return null;

  for (const precondition of decl.preconditions ?? []) {
    if (precondition === "combat_active" && !state.activeNovel?.combat?.active) {
      selectionTelemetry.projection_refusals++;
      return `[ERROR] [STATE_CONFLICT] ${name} (${action}) requires an active combat. Next: manage_combat (action: init).`;
    }
  }

  // REQ-575 — cross-group refusal applies only to the small discovery
  // catalog. Standard is call-complete, so it never costs a group switch.
  if (surfaceProfile() !== "small") return null;
  const active = activeSurfaceGroup();
  if (decl.group === active) return null;
  if (decl.group === "lookup" || decl.group === "maintain") return null;
  if (decl.entry) return null;
  if ((decl.edges ?? []).includes(active)) return null;
  selectionTelemetry.projection_refusals++;
  selectionTelemetry.undeclared_cross_group_calls++;
  return `[ERROR] [STATE_CONFLICT] ${name} (${action}) belongs to group '${decl.group}'. Next: activate group '${decl.group}' or set TTRPG_SURFACE_PROFILE=full.`;
}

// REQ-576 — only a refusal that the Editor badge actually bypasses is counted
// and audited; ordinary Editor calls do not inflate the override surface.
function surfaceGuard(name: string, args: Record<string, unknown>): string | null {
  const refusal = surfaceRefusal(name, args);
  if (!refusal) return null;
  if (getBadge() === "none") {
    surfaceOverrideCount++;
    audit(
      "surface_override",
      { tool: name, action: args?.action ?? null, reason: "editor-badge" },
      "[override]",
    );
    return null;
  }
  return refusal;
}

type GuardRefusal = { content: { type: "text"; text: string }[]; isError: true; structuredContent: Record<string, any> };

// REQ-548c — a dispatcher refusal keeps its exact text and gains a structured
// result: the category, plus the corrective action its text already names
// (`Next: …`, a closing `Use …` sentence, or the category default).
function dispatcherRefusal(code: string, text: string): GuardRefusal {
  const action = text.match(/Next:\s*(.+)$/i)?.[1]?.trim()
    ?? text.match(/(Use .+)$/)?.[1]?.trim()
    ?? CORRECTIVE_ACTIONS[code]
    ?? null;
  const body = text.replace(/^\s*\[ERROR\]\s*\[[A-Z_]+\]\s*/, "").trim();
  return {
    content: [{ type: "text", text }],
    isError: true,
    structuredContent: structured("ERROR", body, { category: code, corrective_action: action }),
  };
}

// REQ-573/575/576/581 — one refusal path shared by the MCP request handler and
// the in-process façade. Returns a refusal envelope or null to proceed.
function guardToolCall(name: unknown, callArgs: Record<string, any>): GuardRefusal | null {
  const toolName = typeof name === "string" ? name : "";
  const registered = toolRegistry.names();
  if (toolName && registered.length > 0 && !registered.includes(toolName)) {
    selectionTelemetry.unknown_tool_calls++;
  }
  if (toolName === "manage_context" && callArgs?.action === "discover") {
    discoveryPendingCall = true;
  } else if (discoveryPendingCall && toolName !== "manage_context") {
    selectionTelemetry.discovery_to_call++;
    discoveryPendingCall = false;
  }
  const retired = retiredAliasRefusal(surfaceRegistry(), toolName, callArgs);
  if (retired) return dispatcherRefusal("NOT_FOUND", retired);
  // REQ-381a/REQ-380c — ruleset scope is enforced at dispatch, not only in
  // tools/list. A package tool whose slug differs from the active Novel's
  // ruleset is refused, naming both scopes.
  const activeRuleset = state.activeNovel?.ruleset;
  if (toolName && activeRuleset) {
    const callee = packageSlugForTool(toolName);
    if (callee && callee !== activeRuleset) {
      return err(
        "INVALID_INPUT",
        `Tool '${toolName}' belongs to ruleset '${callee}'; the active Novel uses '${activeRuleset}'.`,
        `Call a '${activeRuleset}' tool, or create or switch to a Novel bound to '${callee}'.`,
      );
    }
  }
  // REQ-032a/REQ-032c — badge authorization at dispatch. The handler-local
  // guards stay as the backstop; this gate refuses before any handler runs and
  // records the boundary entry itself, because `withForbiddenAudit` only sees
  // results a handler returns or throws (REQ-133a).
  const badgeDenial = registered.includes(toolName)
    ? badgeRefusalFor(
        getBadge(),
        toolName,
        callArgs,
        surfaceRegistry(),
        toolRegistry.get(toolName)?.config.annotations,
        toolGate(toolName) === "GM-only",
      )
    : null;
  if (badgeDenial) {
    state.auditForbidden(getBadge(), toolName, callArgs);
    return dispatcherRefusal("FORBIDDEN", badgeDenial);
  }
  // REQ-447 — the audit cap is enforced before the handler runs, so a refused
  // call cannot persist a mutation whose entry the chain cannot hold.
  const atCapacity = capacityRefusalFor(toolName, callArgs);
  if (atCapacity) return dispatcherRefusal("STATE_CONFLICT", atCapacity);
  const refusal = surfaceGuard(toolName, callArgs);
  if (refusal) return dispatcherRefusal("STATE_CONFLICT", refusal);
  return null;
}

// REQ-447/REQ-040a — audit durability: a call that cannot record its audit
// entry must not run. At capacity the dispatcher refuses an audit-appending
// call before the handler mutates; the compaction path is exempt because it is
// the corrective action and appends nothing before freeing space.
function capacityRefusalFor(name: string, args: Record<string, any>): string | null {
  const novel = state.activeNovel;
  if (!novel || !state.auditLogAtCapacity(novel)) return null;
  const annotations = toolRegistry.get(name)?.config.annotations;
  if (!appendsAuditEntry(surfaceRegistry(), name, args, annotations)) return null;
  if (AUDIT_CAP_EXEMPT_ACTIONS.has(actionKey(name, args))) return null;
  if (name === "respond_decision" && (novel.pending_workflow?.decision ?? "").startsWith("compress_audit:")) return null;
  return capacityRefusal(state.auditLogCapacity(), AUDIT_CAP_CORRECTIVE);
}

// REQ-447/REQ-040a — a call can still cross the cap mid-handler (a first call
// also writes the REQ-237 session-boundary marker; a confirmation workflow
// appends several entries). The pre-call capture is restored so a refusal
// never leaves a persisted mutation behind.
function withCapacityAbort(handler: any, name: string) {
  return async (...handlerArgs: any[]) => {
    const novel = state.activeNovel;
    const args = handlerArgs[0] ?? {};
    // The capture costs one interchange serialization, so it is taken only
    // while the call could actually cross the cap (REQ-447).
    const cap = state.auditLogCapacity();
    const nearCap = novel && cap > 0 && cap - novel.audit_log.length <= AUDIT_APPEND_HEADROOM;
    const capture = nearCap && appendsAuditEntry(surfaceRegistry(), name, args, toolRegistry.get(name)?.config.annotations)
      ? JSON.stringify(exportNovelJSON(novel))
      : null;
    try {
      return await handler(...handlerArgs);
    } catch (e: any) {
      if (!novel || !capture || !/Audit log at capacity/.test(String(e?.message ?? ""))) throw e;
      const restored = importNovelJSON(JSON.parse(capture));
      // `replace` keeps the live undo/redo stacks (an import must not lose
      // them), so the refused call's snapshot push is reverted explicitly.
      applyNovelState(novel, restored, "replace");
      novel.undo_stacks = restored.undo_stacks;
      novel.redo_stacks = restored.redo_stacks;
      state.saveNovel(novel);
      throw e;
    }
  };
}

function installSurfaceGuards(): void {
  const low = (server as unknown as { server?: any }).server;
  const original = low?._requestHandlers?.get?.("tools/call");
  if (typeof original !== "function") {
    process.stderr.write("[holonovel] surface guards unavailable; serving unguarded calls\n");
    return;
  }
  low.setRequestHandler(CallToolRequestSchema, async (req: any, extra: any) => {
    const refusal = guardToolCall(req?.params?.name, req?.params?.arguments ?? {});
    if (refusal) return refusal;
    return original(req, extra);
  });
}

// REQ-409 — enumeration verbosity, session-scoped. Lean (summary) is the
// default; a per-call `detail: true` requests full entries for a single call.
let enumerationVerbosity: "summary" | "detail" = "summary";

// REQ-197c/d — session detail level. `normal` is the default; `terse` and
// `rich` are evaluation-time overrides over the player's chosen room mode
// (`roomDescriptionMode`, set only by brief/verbose/normal), so leaving an
// override always falls back to what the player actually chose.
let detailLevel: "terse" | "normal" | "rich" = "normal";
// REQ-064c/d/f — the player register is session presentation state: it is
// discarded on connection close and does NOT survive a restart, so it lives
// beside detailLevel rather than in Novel state.
let playerRegister: "character" | "meta" = "character";
function effectiveRoomDescriptionMode(): "brief" | "verbose" | "normal" {
  if (detailLevel === "terse") return "brief";
  if (detailLevel === "rich") return "verbose";
  return roomDescriptionMode;
}
// REQ-197 — room description mode, session-scoped (brief/verbose/normal).
let roomDescriptionMode: "brief" | "verbose" | "normal" = "normal";
// REQ-197b — rooms already described in `normal` mode; reset on Novel change.
let visitedRooms = new Set<string>();
let visitedRoomNovel = "";
// REQ-319 — session-local parser state: last command (for `again`/`g`) and the
// last referenced thing (for `it`/`them` pronoun resolution).
let lastCommand: string = "";
let lastReferencedThing: string | null = null;
// REQ-196e — session-local disambiguation record. A bare numeric reply replaces
// the resolved target with the chosen match and re-dispatches the command.
let pendingAmbiguity: { command: string; target: string; matches: Array<{ name: string; location: string }> } | null = null;
function terseMode(terse?: boolean): boolean {
  return terse === true || detailLevel === "terse";
}
function terseOutput(tool: string, args: any, normal: string, terse: string): any {
  return terseMode(args?.terse) ? raw(terse) : ok(normal);
}

// REQ-409 — normalize the per-call detail request: absent → summary (lean
// default); explicit `true` → full entries; explicit `false` → summary.
// REQ-427 — every advertised input parameter carries a JSON Schema description
// (verified by T509); REQ-024 — three-clause tool descriptions ("Use when" /
// "Do NOT use when").
const detailZod = { detail: z.boolean().optional().describe("When true, return full schema and description instead of a summary.") };
function wantsDetail(detail?: boolean): boolean {
  return detail === true;
}

// ── Ruleset packages (REQ-389, REQ-390, REQ-379) ───────────────────

const rulesets = new RulesetManager(RULESET_DIR);
// REQ-389c — package tools registered at startup remain in the SDK registry
// after removal (the SDK has no unregister), so visibility is filtered by this
// set plus the current install set.
const registeredPackageSlugs = new Set<string>();
function packageSlugForTool(name: string): string | undefined {
  for (const slug of registeredPackageSlugs) {
    if (name.startsWith(`${slug}_`)) return slug;
  }
  return undefined;
}
function packageToolVisible(name: string): boolean {
  const slug = packageSlugForTool(name);
  return slug === undefined || rulesets.isInstalled(slug);
}

// Prime the metadata cache once the install set is known, so the first
// tools/list read is warm without the fingerprint touching `rulesets` in TDZ.
cachedMetadata();

// REQ-379b/REQ-379c/REQ-381b — every listed tool reports its ruleset scope in
// the MCP extension slot (`_meta.ruleset`, a slug or null). Under
// `tools/list(scope=all)` a tool whose scope differs from the active Novel's
// is annotated `_meta.inapplicable: true` rather than filtered, so discovery
// survives (REQ-381b). No active Novel means no marks.
function annotateRulesetScope<T extends { name: string; _meta?: Record<string, any> }>(tools: T[], all: boolean): T[] {
  const active = state.activeNovel?.ruleset ?? null;
  return tools.map((tool) => {
    const slug = packageSlugForTool(tool.name) ?? null;
    const meta: Record<string, any> = { ...(tool._meta ?? {}), ruleset: slug };
    if (all && slug !== null && active !== null && slug !== active) meta.inapplicable = true;
    return { ...tool, _meta: meta };
  });
}
const scanErrors = rulesets.scan();
// REQ-420 — incompatible packages are held inactive and surfaced on stderr and
// in spec_health.ruleset_package_alerts, never silently dropped (REQ-393).
for (const e of scanErrors) {
  if (e.includes("[package-incompatible]")) console.error(`holonovel: ${e}`);
}

// REQ-652 — one plain-English startup line when anything is stale or deferred.
// No artifact content is included.
{
  const deferred = startupReconcile.filter((item) => item.outcome === "deferred").length;
  const stale = state.staleData.size + rulesets.incompatibleSlugs().length + deferred;
  if (stale > 0) {
    process.stderr.write(
      `[holonovel] ${stale} item(s) predate the current format; run \`holonovel update\` to reconcile (a writable state directory re-stamps automatically at startup).\n`,
    );
  }
}
const eagerSlugs = (process.env.TTRPG_RULESETS ?? "").split(",").map((s) => s.trim()).filter(Boolean);
for (const slug of eagerSlugs) {
  if (rulesets.isInstalled(slug)) {
    try { rulesets.hydrate(slug); } catch { /* hydration failures surfaced at call time */ }
  }
}

// REQ-023a/REQ-389c — package prompts are host-served at runtime. The map is
// rebuilt from installed packages so install/remove and name collisions resolve
// deterministically without restarting the server.
function reloadPackagePrompts(): void {
  packagePrompts.clear();
  packagePromptErrors.length = 0;
  const hostPrompts = new Set(Object.keys((server as any)._registeredPrompts ?? {}));
  for (const slug of [...rulesets.installedSlugs()].sort()) {
    let declarations: RulesetPrompt[];
    try {
      declarations = rulesets.promptDeclarations(slug);
    } catch (e: any) {
      packagePromptErrors.push({ slug, reason: e?.message ?? String(e) });
      continue;
    }
    for (const prompt of declarations) {
      const name = typeof prompt?.name === "string" ? prompt.name.trim() : "";
      const text = typeof prompt?.text === "string" ? prompt.text : "";
      if (!name || !text.trim()) {
        packagePromptErrors.push({ slug, reason: `prompt '${name || "(unnamed)"}' needs a non-empty name and text` });
        continue;
      }
      if (hostPrompts.has(name)) {
        packagePromptErrors.push({ slug, reason: `prompt '${name}' collides with a host prompt` });
        continue;
      }
      if (packagePrompts.has(name)) {
        packagePromptErrors.push({ slug, reason: `prompt '${name}' collides with package '${packagePrompts.get(name)!.slug}'` });
        continue;
      }
      packagePrompts.set(name, { slug, prompt });
    }
  }
  for (const error of packagePromptErrors) {
    process.stderr.write(`[holonovel] package prompt skipped (${error.slug}): ${error.reason}\n`);
  }
}
function packagePromptList(): Array<{ name: string; title: string; description: string }> {
  return [...packagePrompts.entries()]
    .map(([name, entry]) => ({
      name,
      title: entry.prompt.title ?? name,
      description: `Ruleset prompt from ${entry.slug}.`,
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

// ── REQ-065a / REQ-187a — build-fingerprint persistence and drift ───
// Persist the build fingerprint into the state directory at first start, then
// reload it on subsequent starts and compare field-by-field (REQ-065b). Drift
// is diagnostic: it never blocks startup (REQ-065f) and is surfaced on stderr
// and in spec_health.
state.loadBuildFingerprint({
  ...state.buildFingerprint,
  specHash: SPEC_HASH,
  rulesetHash: rulesets.contentHashDigest(),
});
for (const warning of state.buildDrift) process.stderr.write(`[holonovel] ${warning}\n`);

// ── REQ-088 — TTRPG_NOVEL startup auto-load ────────────────────────
// Activate (resume-or-create) the named Novel before any tool call is
// serviced. Resolution is by *internal slug* against the hydrated registry
// (REQ-065), so a save file whose name diverges from its internal slug is
// still auto-loadable. On a corrupt or otherwise failed activation, report to
// stderr and spec_health (via corruptData) and proceed with no Novel active —
// never silently swallow, and never overwrite an existing (possibly corrupt)
// save.
const startupNovel = process.env.TTRPG_NOVEL;
if (startupNovel) {
  // REQ-659 / §7.1a — the startup name is a derivation site.
  const slug = fitSlug(deriveSlug(startupNovel), DATA_DIR);
  try {
    if (state.novels.has(slug)) {
      const novel = state.activateHydratedNovel(slug);
      if (novel.ruleset) {
        if (!rulesets.isInstalled(novel.ruleset)) {
          throw new Error(`Novel '${slug}' is bound to ruleset '${novel.ruleset}', which is not installed.`);
        }
        rulesets.hydrate(novel.ruleset);
      }
    } else if (fs.existsSync(path.join(DATA_DIR, "novels", `${slug}.json`))) {
      // A save file exists but did not hydrate under this slug — corrupt, or
      // its internal slug diverges from the filename. Refuse to activate or
      // overwrite (REQ-088h1).
      throw new Error(`save file '${slug}.json' exists but did not hydrate under slug '${slug}' (corrupt or mismatched internal slug).`);
    } else {
      state.createNovel(startupNovel);
    }
  } catch (e) {
    state.markCorrupt(slug, `TTRPG_NOVEL activation failed: ${(e as Error).message}`);
  }
}

// Convert a JSON-Schema-style inputSchema (as shipped by a package's tools.json)
// into a Zod raw shape registerTool accepts (REQ-389 — schemas-as-data).
function jsonSchemaToZod(schema: any): any {
  if (!schema || typeof schema !== "object") return z.any();
  const t = schema.type;
  if (t === "string") {
    if (Array.isArray(schema.enum)) return z.enum(schema.enum as any);
    return z.string();
  }
  if (t === "number" || t === "integer") return z.number();
  if (t === "boolean") return z.boolean();
  if (t === "array") return z.array(jsonSchemaToZod(schema.items ?? {}));
  if (t === "object") {
    const shape: Record<string, any> = {};
    const requiredSet = new Set<string>(
      Array.isArray(schema.required) ? schema.required : []
    );
    for (const [k, v] of Object.entries(schema.properties ?? {})) {
      let zs = jsonSchemaToZod(v);
      if (requiredSet.has(k)) {
        if (zs && typeof zs === "object" && zs._def?.typeName === "ZodOptional") {
          zs = zs.unwrap();
        }
      } else if (!zs || typeof zs !== "object" || zs._def?.typeName !== "ZodOptional") {
        zs = zs.optional();
      }
      shape[k] = zs;
    }
    return z.object(shape);
  }
  if (schema.anyOf) {
    const nonNull = schema.anyOf.filter((s: any) => s?.type !== "null");
    if (nonNull.length === 1) return jsonSchemaToZod(nonNull[0]).optional();
    return z.any();
  }
  return z.any();
}

// REQ-210c/REQ-002c1/REQ-445 — extracted catalogue entries carry a declared
// `badge_scope` (absent means `shared`). The Game Master and Editor badges see
// every entry; Player and Observer treat a `game_master` entry as absent, so it
// cannot be resolved, enumerated, hinted at, or read through an info tool.
function rulesetEntryVisible(entry: any, badge: Badge): boolean {
  if (badge === "game_master" || badge === "none") return true;
  return entry?.badge_scope !== "game_master";
}

function visibleRulesetCollection(raw: unknown, badge: Badge): Record<string, any> {
  const out: Record<string, any> = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  for (const [key, entry] of Object.entries(raw as Record<string, any>)) {
    if (rulesetEntryVisible(entry, badge)) out[key] = entry;
  }
  return out;
}

// REQ-210d — a search-index entry carries the same declared `badge_scope` as
// the model entry it indexes, and the legacy `category` refusal (REQ-381b) is
// preserved as a second signal so a package built before the field existed
// never widens its visibility. The composed rule is a floor: an entry is
// visible only when both signals admit it.
function visibleIndexEntry(entry: any, badge: Badge): boolean {
  if (!rulesetEntryVisible(entry, badge)) return false;
  if (badge === "game_master" || badge === "none") return true;
  return !["gm", "game_master"].includes(String(entry?.category ?? "").toLowerCase());
}

// REQ-210d/REQ-002c1/REQ-445 — every host search surface goes through this
// helper: hits and the reported match total are both post-filter, and an
// all-invisible result set is indistinguishable from no match.
function searchIndexVisible(slug: string, query: string, maxResults: number, badge: Badge): RulesetIndexEntry[] {
  return rulesets.search(slug, query, maxResults, (entry) => visibleIndexEntry(entry, badge));
}

// Generic ruleset tool handlers. Tools are expressed as data (REQ-389); the
// host dispatches on the tool's `kind` so a package's tools serve without the
// host re-parsing source Markdown.
function gatedRulesetTool(slug: string, schema: RulesetToolSchema, toolName: string) {
  return async (args: any) => {
    if (!rulesets.isInstalled(slug)) {
      return err("STATE_CONFLICT", `Ruleset '${slug}' is not installed.`);
    }
    // REQ-558 — ruleset content is host-level: an installed package serves its
    // tools whether or not a Novel is bound. Hydrate lazily on first use; a
    // hydration failure (content-hash mismatch, corrupt files) surfaces here.
    let pkg: ReturnType<typeof rulesets.hydrate>;
    try {
      pkg = rulesets.hydrate(slug);
    } catch (e: any) {
      // REQ-389b — record the failed load so spec_health surfaces the rejection.
  rulesets.recordLoadFailure(slug, e.message);
  return err("STATE_CONFLICT", `Ruleset '${slug}' failed to load: ${e.message}`);
    }
    switch (schema.kind) {
      case "lookup": {
        const collection = schema.collection ?? "concepts";
        const key = String(args.key ?? args.name ?? "").toLowerCase();
        // REQ-002c1/REQ-445/REQ-210c — an entry declared `game_master` is
        // absent for the Player and Observer badges: it neither resolves,
        // enumerates, nor hints.
        const coll = visibleRulesetCollection(pkg.model[collection], getBadge());
        // REQ-558b — resolve a lookup by exact key, then by the entry's canonical
        // `name`, then by any declared `alias`. Extraction keys are heading slugs
        // (e.g. `the-veritech-fighters-2`); callers use natural names (e.g.
        // `VF-1A Veritech Fighter`), so key-only resolution is not discoverable.
        const wantNorm = normId(key);
        let entry: any;
        let matchedKey = key;
        if (coll && key in coll) {
          entry = coll[key];
        } else {
          for (const [k, v] of Object.entries(coll ?? {})) {
            const cand = v as any;
            if (normId(k) === wantNorm || normId(cand?.name) === wantNorm
              || (Array.isArray(cand?.aliases) && cand.aliases.some((a: any) => normId(a) === wantNorm))) {
              entry = cand;
              matchedKey = k;
              break;
            }
          }
        }
        if (entry) {
          // REQ-060 — verbose output: full entry; REQ-061 source quoting;
          // REQ-280 source-anchor citation — source block and source_anchor
          // derived from the matching index entry. REQ-004 — truncate.
          // REQ-112 — cross-reference discovery: when the entry's content names
          // another indexed section by anchor, surface a non-recursive pointer.
          const idxEntry = pkg.index.find((i: any) => normId(i.id) === normId(matchedKey) || normId(i.key) === normId(matchedKey));
          const body = JSON.stringify({ ...entry, ...sourceAnchor(idxEntry ?? entry), ...discoverCrossRefs(pkg, entry, idxEntry) }, null, 2);
          const payload = body + sourceBlock(idxEntry ?? entry);
          return raw(payload);
        }
        // REQ-057 canonical lookup, REQ-059 parameter-canon validation, REQ-183
        // live-index enumerations: unknown names return [NOT_FOUND] with the
        // valid values enumerated from the visible collection (REQ-002c1) and
        // a "Did you mean?" hint when a close match exists.
        // REQ-058 — tool-result fidelity: no fabricated entries, no reading of
        // ruleset Markdown after startup; lookups use the loaded index/model.
        // REQ-558b — enumerate canonical names (falling back to keys) so the
        // hint names what a caller can actually ask for.
        const validValues = Object.entries(coll ?? {}).map(([k, v]: [string, any]) => v?.name ?? k);
        const hint = closestMatch(key, validValues);
        const enumList = validValues.length > 0 ? ` Valid values: ${validValues.slice(0, 25).join(", ")}${validValues.length > 25 ? "…" : ""}.` : "";
        const didYouMean = hint ? ` Did you mean '${hint}'?` : "";
        return err("NOT_FOUND", `No '${args.key}' found in ${collection}.${didYouMean}${enumList}`);
      }
      case "search": {
        const q = String(args.query ?? "");
        // REQ-210d — hits and the reported total are both badge-filtered; a
        // blank query takes the same filter.
        const hits = searchIndexVisible(slug, q, args.max_results ?? 10, getBadge());
        if (hits.length === 0) return err("NOT_FOUND", `No ruleset entry matches '${q}'.`);
        const body = hits.map((h: any) => JSON.stringify({ ...h, ...sourceAnchor(h) }, null, 2)).join("\n");
        // REQ-113 — total match count vs returned count.
        const total = searchIndexVisible(slug, q, 100000, getBadge()).length;
        return raw(body + countReport(hits.length, total));
      }
      case "roll": {
        try {
          // REQ-558c — a roll tool may declare `defaultDice` when the notation is
          // fixed by the ruleset (e.g. a percentile skill check). Caller-supplied
          // dice/notation still override it.
          const fallback = schema.defaultDice ?? "1d20";
          const notation = String(args.dice ?? args.notation ?? fallback);
          const label = args.skill ? `${args.skill} check` : (args.notation ?? args.dice ?? fallback);
          let r = rollDice(notation, args.seed);
          const extra = Number(args.modifier ?? 0);
          if (extra !== 0) {
            r = { total: r.total + extra, dice: r.dice, modifier: r.modifier + extra, notation: r.notation };
          }
          // REQ-003 — roll transparency: notation, per-die results, modifiers,
          // total. The selected-faces contract (REQ-003b) is honored when the
          // dice breakdown is reported individually, as here. A zero modifier
          // is still reported so the modifier line is always present.
          const parts = [`${label} (${r.notation}${extra !== 0 ? ` ${extra > 0 ? "+" : "-"} ${Math.abs(extra)}` : ""})`];
          parts.push(`**${r.total}**`);
          if (r.dice.length > 1) parts.push(`(${r.dice.join(" + ")})`);
          if (extra !== 0) parts.push(`modifier ${extra > 0 ? "+" : "-"} ${Math.abs(extra)}`);
          else parts.push(`modifier +0`);
          return ok(parts.join(" → ") + seedWarningSuffix(args.seed));
        } catch (e: any) {
          return err("INVALID_INPUT", e.message);
        }
      }
      case "table": {
        const collection = schema.collection ?? "tables";
        // REQ-558b — a table tool resolves against its declared collection and,
        // when the caller names a generation table, against generation_tables too.
        const tables = { ...(pkg.model.generation_tables ?? {}), ...(pkg.model[collection] ?? {}) } as Record<string, any>;
        const name = String(args.table ?? args.name ?? "");
        // REQ-558b — resolve by exact key, then entry `name`, then `alias`.
        let table = name ? tables[name] ?? tables[name.toLowerCase()] : undefined;
        if (!table && name) {
          const wantNorm = normId(name);
          const hit = Object.entries(tables).find(([k, v]: [string, any]) =>
            normId(k) === wantNorm || normId(v?.name) === wantNorm
            || (Array.isArray(v?.aliases) && v.aliases.some((a: any) => normId(a) === wantNorm)));
          if (hit) table = hit[1];
        }
        if (!table) {
          const valid = Object.entries(tables).map(([k, v]: [string, any]) => v?.name ?? k);
          const hint = closestMatch(name, valid);
          const didYouMean = hint ? ` Did you mean '${hint}'?` : "";
          const enumList = valid.length > 0 ? ` Valid tables: ${valid.slice(0, 25).join(", ")}.` : "";
          return err("NOT_FOUND", `No table '${name}' found.${didYouMean}${enumList}`);
        }
        const rows = Array.isArray(table) ? table : (Array.isArray(table.rows) ? table.rows : null);
        if (rows) {
          const rng = args.seed ? createRng(args.seed) : null;
          const idx = rng ? rng.roll(rows.length) - 1 : sessionRoll(rows.length) - 1;
          const row = rows[Math.max(0, Math.min(idx, rows.length - 1))];
          return withSeedWarning(raw(JSON.stringify(row, null, 2)), args.seed);
        }
        return raw(JSON.stringify(table, null, 2));
      }
      case "info": {
        // REQ-389 — an info-kind tool (e.g. core_mechanic) returns the model
        // entry's content, not the tool's own description. REQ-558a — resolve
        // explicitly from model.info[toolName] first, then scan collections for a
        // key matching the tool name. REQ-210c — an entry declared
        // `game_master` is absent for the Player and Observer badges.
        const badge = getBadge();
        const want = normId(schema.name);
        const declared: any = (pkg.model as any).info?.[schema.name] ?? (pkg.model as any).info?.[want] ?? null;
        let infoEntry: any = declared && rulesetEntryVisible(declared, badge) ? declared : null;
        if (!infoEntry) {
          for (const coll of Object.values(pkg.model) as any[]) {
            if (!coll || typeof coll !== "object" || Array.isArray(coll)) continue;
            const hit = Object.keys(coll).find((k) => normId(k) === want);
            if (hit && rulesetEntryVisible(coll[hit], badge)) { infoEntry = coll[hit]; break; }
          }
        }
        if (infoEntry) {
          const text = typeof infoEntry.description === "string" ? infoEntry.description
            : typeof infoEntry.content === "string" ? infoEntry.content
            : typeof infoEntry.text === "string" ? infoEntry.text
            : JSON.stringify(infoEntry, null, 2);
          return ok(text + sourceBlock({ ...infoEntry, anchor: infoEntry.anchor ?? schema.name }));
        }
        // REQ-558a — an info tool with no backing model entry is an extraction
        // defect; return [NOT_FOUND] rather than echoing the tool description.
        return err("NOT_FOUND", `No model entry backs info tool '${schema.name}' in ruleset '${slug}'.`);
      }
      default:
        return err("UNIMPLEMENTED", `Ruleset tool kind '${(schema as any).kind}' is not supported by this host.`);
    }
  };
}

// Register ruleset-prefixed tools for every installed package (REQ-379).
// REQ-389b/REQ-393 — a package that fails loading (e.g. content-hash mismatch)
// is recorded and skipped; the host boots and serves the other packages.
const rulesetLoadErrors: { slug: string; reason: string }[] = [];
// REQ-558 — register one installed package's derived tools. Extracted from the
// startup loop so `manage_ruleset (action: install)` serves a package
// immediately, without a restart.
function registerPackageTools(slug: string): void {
  if (registeredPackageSlugs.has(slug)) return;
  let schemas: ReturnType<typeof rulesets.toolSchemas>;
  try {
    schemas = rulesets.toolSchemas(slug);
  } catch (e: any) {
    rulesetLoadErrors.push({ slug, reason: e.message });
    return;
  }
  registeredPackageSlugs.add(slug);
  // REQ-430 — flag non-conformant declared tools at load (no index hydration).
  rulesets.validateDeclaredToolSchemas(slug, schemas);
  for (const schema of schemas) {
    const toolName = `${slug}_${schema.name}`;
    // REQ-450/REQ-430 — ruleset-derived tools read indexed data
    // (lookup/search/info) or generate a roll/table result; none mutates Novel
    // state, so read-only is honest and destructiveHint is false throughout.
    const annotations: ToolAnnotation = rulesetAnnotations(schema.kind);
    try {
      server.registerTool(toolName, {
        title: schema.title ?? schema.name,
        description: `${schema.description ?? ""} (ruleset: ${slug})`,
        inputSchema: jsonSchemaToZod(schema.inputSchema),
        annotations,
      }, gatedRulesetTool(slug, schema, toolName));
    } catch (e: any) {
      // Tool name already registered or schema unrecoverable — skip.
    }
  }
}

// REQ-389c — register a package's declared resources and keep the SDK handle so
// removal can deregister them. The handle's remove() deletes the fixed or
// template registration and emits resources/list_changed. Tools have no
// equivalent in this host: ToolRegistry.define has no remove and a reinstall
// would collide, so tools stay filtered by the installed set.
const packageResourceKeys = new Set<string>();
const packageResourceHandles = new Map<string, Array<{ remove(): void }>>();
function registerPackageResources(slug: string): void {
  let declarations: any[];
  try {
    declarations = rulesets.resourceDeclarations(slug);
  } catch {
    // An unreadable resources.json contributes nothing; tools still serve.
    return;
  }
  for (const declaration of declarations) {
    const name = typeof declaration?.name === "string" ? declaration.name.trim() : "";
    if (!name) continue;
    const key = `pkg:${slug}:${name}`;
    if (packageResourceKeys.has(key)) continue;
    const uri = typeof declaration?.uri === "string" && declaration.uri ? declaration.uri : `ruleset://${slug}/${name}`;
    const mimeType = typeof declaration?.mimeType === "string" ? declaration.mimeType : "application/json";
    const text = typeof declaration?.text === "string" ? declaration.text : JSON.stringify(declaration?.content ?? null);
    try {
      const handle = server.registerResource(key, uri, { title: declaration?.title ?? name, mimeType }, async () => ({
        contents: rulesets.isInstalled(slug) ? [{ uri, text, mimeType }] : [],
      }));
      packageResourceKeys.add(key);
      const handles = packageResourceHandles.get(slug) ?? [];
      handles.push(handle as unknown as { remove(): void });
      packageResourceHandles.set(slug, handles);
    } catch {
      // Duplicate URI/name: the first registration wins.
    }
  }
}

// REQ-389c — deregister a removed package's resources and reopen its keys so a
// reinstall can register the same URIs again.
function deregisterPackageResources(slug: string): void {
  for (const handle of packageResourceHandles.get(slug) ?? []) {
    try {
      handle.remove();
    } catch {
      // Already removed, or never registered; nothing left to deregister.
    }
  }
  packageResourceHandles.delete(slug);
  for (const key of [...packageResourceKeys]) {
    if (key.startsWith(`pkg:${slug}:`)) packageResourceKeys.delete(key);
  }
}

for (const slug of rulesets.installedSlugs()) {
  registerPackageTools(slug);
  registerPackageResources(slug);
}

// REQ-310 — campaign memory: engine-recorded facts derived from state-changing
// tool calls, per-NPC/thread/location, prioritized by scene relevance in
// badge_briefing; per-category counts in spec_health.
function recordCampaignMemory(novel: NovelState, category: "npcs" | "threads" | "locations", text: string, badge_scope: "game_master" | "shared" | "discovered" = "game_master"): void {
  novel.campaign_memory = novel.campaign_memory ?? [];
  novel.campaign_memory.push({ category, text, at: new Date().toISOString(), badge_scope, scene: novel.scene_description?.substring(0, 60) ?? "" });
  if (novel.campaign_memory.length > 200) novel.campaign_memory.shift();
}

// REQ-233a1 — a connected change traces one hop through the relationship
// graph. Targets are the relationship endpoints other than the change's own
// seeds; unknown ids pass through as tokens (the relationship store accepts
// ids and display names alike).
function worldChangeTargets(novel: NovelState, seedIds: string[]): string[] {
  const seeds = new Set(seedIds.filter(Boolean));
  const out = new Set<string>();
  for (const row of novel.relationships) {
    if (seeds.has(row.entity_a)) out.add(row.entity_b);
    if (seeds.has(row.entity_b)) out.add(row.entity_a);
  }
  for (const seed of seeds) out.delete(seed);
  return [...out];
}

// REQ-233a2 — enqueue a pending world change. Suppressed entirely while world
// reactivity is off (REQ-233a3); a non-terminal duplicate is not re-enqueued.
function enqueueWorldChange(novel: NovelState, source: WorldChange["source"], summary: string, seedIds: string[]): void {
  if (!worldReactivityOn()) return;
  const duplicate = novel.world_in_motion.some((c) =>
    c.source === source && c.summary === summary && c.state !== "dismissed" && c.state !== "accepted");
  if (duplicate) return;
  novel.world_in_motion.push({
    id: `${source}_${novel.world_in_motion.length + 1}_${Date.now().toString(36)}`,
    source,
    summary,
    targets: worldChangeTargets(novel, seedIds),
    state: "pending",
    defer_count: 0,
    created_at: new Date().toISOString(),
  });
  // Bounded like campaign memory so a long campaign cannot grow without limit.
  while (novel.world_in_motion.length > 50) novel.world_in_motion.shift();
}

// REQ-233a1/a2 — the transition-time reactivity cycle. Relationship markers
// accumulated during the closing scene become GM-facing pending changes. Defer
// re-surfacing is handled by rendering deferred entries; the cap is derived in
// spec_health, so no second persisted counter exists.
function runWorldReactivityCycle(novel: NovelState, markers: RelationshipMarker[]): void {
  if (!worldReactivityOn()) return;
  for (const marker of markers) {
    enqueueWorldChange(novel, "relationship", marker.text.replace(/^Relationship changed:\s*/, "Relationship shift: "), marker.entity_ids);
  }
}

// REQ-084a1/a2 — proactive Available Actions: mechanically legal actions for
// the active entity from scene type, capabilities, and active countdowns,
// capped at TTRPG_MAX_AVAILABLE_ACTIONS (default 8) and badge-filtered.
function availableActionsSection(novel: NovelState): string[] {
  const entity = state.getActiveEntity();
  const badge = getBadge();
  const isGM = badge === "game_master" || badge === "none";
  const sceneTypes = novel.scene_type ?? [];
  const actions: string[] = [];
  // REQ-087b — every active scene type contributes its family independently, so
  // a combined tag (["social", "exploration"]) orders both before unmatched actions.
  if (novel.combat?.active || sceneTypes.includes("combat")) {
    if (isGM) actions.push("manage_combat (action: advance — resolve the round)");
    actions.push("resolve an attack or skill check for the active entity");
  }
  if (sceneTypes.includes("social")) {
    actions.push("resolve a persuasion, deception, or intimidation check with a present NPC");
    if (isGM) {
      actions.push("manage_staging (action: next_speaker — pick the next NPC speaker)");
      actions.push("manage_relationship (action: set — record a social outcome)");
    }
  }
  if (sceneTypes.includes("exploration") || (sceneTypes.length === 0 && !novel.combat?.active && (isGM || !novel.ruleset))) {
    actions.push("run_command (action: execute, \"look\")");
    actions.push("run_command (action: execute, \"go <direction>\")");
    actions.push("run_command (action: execute, \"examine <thing>\")");
    if (novel.world.things.size > 0) actions.push("run_command (action: execute, \"take <thing>\")");
    if (isGM) {
      actions.push("run_command (action: visibility — who can see this?)");
      actions.push("run_command (action: audibility — who can hear this?)");
    }
  }
  if (actions.length === 0 && !isGM && novel.ruleset) {
    actions.push("run_command (action: suggest, \"<what you want to do>\")");
  }
  const inv = entity?.inventory ?? [];
  if (inv.length > 0) actions.push(`manage_character (action: sheet — use held item: ${inv.slice(0, 3).join(", ")})`);
  // REQ-084a2/a3 — capability gating: a spell is listed only while its slot
  // level has a positive remainder in entity.stats.spell_slots. Bare-name
  // spells and level 0 are cantrips and always legal.
  const slots: any = (entity as any)?.stats?.spell_slots ?? {};
  for (const spell of ((entity as any)?.spells ?? [])) {
    const name = typeof spell === "string" ? spell : String(spell?.name ?? "");
    const level = typeof spell === "string" ? 0 : Number(spell?.level ?? 0);
    if (!name) continue;
    if (level > 0 && !(Number(slots[String(level)] ?? 0) > 0)) continue;
    actions.push(level > 0 ? `Cast ${name} (level ${level} slot)` : `Cast ${name}`);
  }
  if (isGM) {
    const activeCd = [...novel.countdowns.values()].filter((c) => c.ticks > 0);
    if (activeCd.length > 0) actions.push(`manage_countdown (action: advance — ${activeCd[0].name}, ${activeCd[0].ticks} ticks)`);
    actions.push("manage_story (action: record — commit a story beat)");
  }
  const cap = configInt("TTRPG_MAX_AVAILABLE_ACTIONS", 8);
  return actions.slice(0, Math.max(0, cap));
}

function composeCampaignMemorySection(novel: NovelState, badge: string): string {
  const facts = novel.campaign_memory ?? [];
  const isGM = badge === "game_master" || badge === "none";
  // REQ-590 — the persisted campaign-bible tier renders through the existing
  // Campaign Memory section (GM-only; it contains secrets).
  const bible = isGM && (novel.compression_ladder?.campaign?.source_refs?.length ?? 0) > 0
    ? novel.compression_ladder!.campaign!.text
    : "";
  if (facts.length === 0 && !bible) return "";
  const maxFacts = configInt("TTRPG_CAMPAIGN_MEMORY_MAX_FACTS", 10);
  const visible = isGM ? facts : facts.filter((f) => (f.badge_scope === "shared" || f.badge_scope === "discovered"));
  const lines = visible.slice(-maxFacts).map((f) => {
    const tag = f.badge_scope === "discovered" ? " [discovered]" : "";
    return `- [${f.category}] ${f.text}${tag}`;
  });
  const blocks = [lines.join("\n"), bible].filter(Boolean);
  if (blocks.length === 0) return "";
  return `\n\n## Campaign Memory\n${blocks.join("\n")}`;
}

// REQ-626/REQ-634/REQ-644–REQ-648 — subjective-memory briefing section.
// Selection is deterministic (REQ-644), bounded by the record cap or the token
// budget (REQ-645), and reports both an evicted source and the omitted count.
// REQ-648 probes this render at declared budgets.
// The Game Master sees every present entity's records, non-`open` ones tagged
// with their disclosure level; the Player sees only the active entity's visible
// records, with `guarded` rendered as gist. The Observer badge never sees it.
function memoryScoreInputs(novel: NovelState): {
  latestOrdinal: number;
  logLength: number;
  reinforcements: ReinforcementEntry[];
  decayHalfLife: number;
  reinforcementBonus: number;
  reinforcementMax: number;
} {
  const log = novel.event_log ?? [];
  return {
    latestOrdinal: log.length > 0 ? log[log.length - 1].ordinal : 0,
    logLength: log.length,
    reinforcements: novel.subjective_reinforcement ?? [],
    decayHalfLife: configInt("TTRPG_SUBJECTIVE_MEMORY_DECAY_HALFLIFE", 200),
    reinforcementBonus: configInt("TTRPG_SUBJECTIVE_MEMORY_REINFORCEMENT_BONUS", 25),
    reinforcementMax: configInt("TTRPG_SUBJECTIVE_MEMORY_REINFORCEMENT_MAX", 6),
  };
}

// REQ-656 — a closed window whose successor disagrees overrides the base
// verdict with displaced; an agreeing successor leaves the verdict untouched.
function windowAwareVerdict(
  novel: NovelState,
  record: SubjectiveMemoryRecord,
  result: DivergenceResult,
  windows: Map<string, ValidityWindow>,
): DivergenceResult {
  const window = windows.get(record.id);
  if (!window || window.valid_until === null) return result;
  const successor = (novel.subjective_memory ?? []).find(
    (r) => r.id !== record.id && r.event_ordinal === window.valid_until && claimChainKey(r) === claimChainKey(record),
  );
  if (!successor) return result;
  if (
    successor.claim.object !== record.claim.object &&
    (result.verdict === "confirmed" || result.verdict === "conflated")
  ) {
    return { ...result, verdict: "displaced", reason: "the derived validity window closed with a later disagreeing claim" };
  }
  return result;
}

function composeSubjectiveMemorySection(novel: NovelState, badge: string): string {
  const isGM = badge === "game_master" || badge === "none";
  if (!isGM && badge !== "player") return "";
  const maxRecords = configInt("TTRPG_SUBJECTIVE_MEMORY_BRIEFING_MAX", 5);
  const budgetTokens = configInt("TTRPG_SUBJECTIVE_MEMORY_BRIEFING_TOKENS", 800);
  const inputs = memoryScoreInputs(novel);
  const retained = new Set((novel.event_log ?? []).map((e) => e.ordinal));
  const marker = (omitted: number) => `[truncated] ${omitted} memories omitted at budget`;
  const evictedTag = (r: SubjectiveMemoryRecord) =>
    eventState(r.event_ordinal, retained) === "evicted" ? ` [evicted #${r.event_ordinal}]` : "";

  if (badge === "player") {
    // REQ-634 — the Player section covers the active entity only and never
    // depends on scene presence. `secret` records leave the pool before packing
    // so the omitted count cannot hint at their existence (REQ-645).
    const activeId = state.getActiveEntity()?.id;
    if (!activeId) return "";
    const pool = selectForBriefing(novel.subjective_memory ?? [], new Set([activeId]), inputs)
      .filter((r) => r.disclosure !== "secret");
    const assembled = assembleMemorySection(
      pool,
      (r) => {
        const projected = playerProjection(r);
        if (!projected) return { text: "" };
        if (projected.disclosure === "open") {
          const claim = `${projected.claim.subject} ${projected.claim.predicate} ${projected.claim.object}`.trim();
          return {
            text: `- [${projected.origin}] ${projected.entity_id}: ${projected.gist}${claim ? ` (claims: ${claim})` : ""}${projected.felt_then ? ` (felt ${projected.felt_then})` : ""}`,
            suffix: evictedTag(projected),
          };
        }
        return { text: `- [guarded] ${projected.entity_id}: ${projected.gist}`, suffix: evictedTag(projected) };
      },
      { maxRecords, budgetTokens, marker },
    );
    if (assembled.lines.length === 0) return "";
    return `\n\n## Subjective Memory\n${assembled.lines.join("\n")}`;
  }

  const present = new Set<string>(presentEntityIds(novel) ?? novel.entities.keys());
  const sceneLoc = (novel.scene_location ?? "").toLowerCase();
  if (sceneLoc) {
    for (const npc of novel.npcs.values()) {
      if ((npc.room_id ?? "").toLowerCase() === sceneLoc || (npc.location ?? "").toLowerCase() === sceneLoc) {
        present.add(npc.id);
      }
    }
  }
  if (present.size === 0) return "";
  const pool = selectForBriefing(novel.subjective_memory ?? [], present, inputs);
  if (pool.length === 0) return "";
  // REQ-632 — the divergence marker derives from the same check as the truth
  // view; selection, order, and the render bounds are untouched.
  const facts = projectTruthFacts(novel);
  const alias = buildAliases(novel);
  const windows = deriveValidityWindows(novel.subjective_memory ?? []);
  const assembled = assembleMemorySection(
    pool,
    (r) => {
      // REQ-626 — a non-open record carries its disclosure level so the
      // narrator knows it may not be quoted.
      const tag = r.disclosure === "open" ? r.origin : `${r.origin}, ${r.disclosure}`;
      const text = `- [${tag}] ${r.entity_id}: ${r.gist}${r.felt_then ? ` (felt ${r.felt_then})` : ""}`;
      const result = windowAwareVerdict(novel, r, checkRecord(r, facts, novel, alias), windows);
      const divergence = result.verdict !== "confirmed" && result.verdict !== "unverifiable"
        ? ` [divergence: ${result.verdict.split("_").join(" ")}]`
        : "";
      return { text, suffix: divergence + evictedTag(r) };
    },
    { maxRecords, budgetTokens, marker },
  );
  return `\n\n## Subjective Memory\n${assembled.lines.join("\n")}`;
}

// REQ-255b — boundary signal propagation: when free-text input contains a
// substring matching an active boundary value, return [WARNING] identifying the
// match without suppressing the operation (advisory collision check).
function boundaryCollisionWarning(novel: NovelState, text: string): string | null {
  const boundary = novel.player_signals?.boundary?.value;
  if (!boundary) return null;
  const t = text.toLowerCase();
  if (t.includes(boundary.toLowerCase())) {
    return `Boundary collision: input contains the boundary value '${boundary}'. Advisory — do not narrate content evoking this topic.`;
  }
  return null;
}

// REQ-255b — append one advisory warning per matched boundary to an already
// successful tool result. The operation is never suppressed.
function appendBoundaryWarning(output: string, novel: NovelState, texts: Array<string | undefined>): string {
  const seen = new Set<string>();
  const warnings: string[] = [];
  for (const text of texts) {
    if (!text) continue;
    const warning = boundaryCollisionWarning(novel, text);
    if (warning && !seen.has(warning)) { seen.add(warning); warnings.push(warning); }
  }
  return warnings.length > 0 ? `${output}\n\n[WARNING] ${warnings.join("\n[WARNING] ")}` : output;
}

function audit(tool: string, args: any, prefix?: string): void {
  const novel = state.activeNovel;
  if (novel) state.audit(novel, getBadge(), tool, args, prefix);
  // REQ-433 — audit_delta topic: echo the recorded audit event as a read-only
  // server-to-client notification, badge-filtered so Player connections never
  // receive entries recorded under a GM badge.
  const badge = getBadge();
  notifyForBadge("audit_delta", { tool, prefix: prefix ?? null }, badge, badge === "game_master" || badge === "none");
}

// REQ-455 — append an observation to the Novel event log, capped by config.
// REQ-456 — the entry preserves source, ordinal, and time independently of any
// semantic interpretation. Callers persist the Novel after recording.
function recordEvent(kind: string, text: string, source?: EventSource): void {
  const novel = state.activeNovel;
  if (!novel) return;
  const badge = getBadge();
  const resolved: EventSource = source ?? (badge === "player" ? "player" : badge === "game_master" ? "game_master" : "system");
  const entry = appendEvent(novel.event_log, resolved, kind, text, new Date().toISOString());
  const cap = parseInt(process.env.TTRPG_EVENT_LOG_MAX_ENTRIES ?? "50000", 10);
  if (cap > 0 && novel.event_log.length > cap) novel.event_log = evictToCap(novel.event_log, cap);
  deriveWitnessPerceptions(novel, kind, text, entry.ordinal);
  // REQ-602 — the digest covers post-mutation state, after the perception
  // derivation side effect, so a clean Novel verifies.
  entry.state_hash = state.stateDigest(novel);
  entry.state_hash_projection = STATE_HASH_PROJECTION_VERSION;
}

// REQ-594 — append a perception with its witness provenance, honoring the cap.
function appendPerceptionRecord(novel: NovelState, fields: Omit<PerceptionRecord, "id" | "at">): PerceptionRecord {
  const record: PerceptionRecord = { id: nextPerceptionId(novel.perception_ledger), at: new Date().toISOString(), ...fields };
  novel.perception_ledger.push(record);
  const cap = parseInt(process.env.TTRPG_PERCEPTION_MAX_ENTRIES ?? "20000", 10);
  if (cap > 0 && novel.perception_ledger.length > cap) novel.perception_ledger = novel.perception_ledger.slice(novel.perception_ledger.length - cap);
  return record;
}

// REQ-595 — derive witnesses for an appended event: entities sharing the
// event's lit room see it, entities one open exit away hear it. The acting
// entity is the source and is not given a record for its own event.
function deriveWitnessPerceptions(novel: NovelState, kind: string, text: string, ordinal: number): void {
  if (!novel.world || novel.world.rooms.size === 0) return;
  const active = state.getActiveEntity();
  const sourceRoom = active?.current_room ?? novel.scene_location ?? null;
  if (!sourceRoom) return;
  const perceptionKind: PerceptionKind = kind === "scene" ? "scene" : "observation";
  const lit = roomIsLit(novel.world, sourceRoom);
  const candidates: Array<{ id: string; room: string | null }> = [];
  for (const entity of novel.entities.values()) candidates.push({ id: entity.id, room: entity.current_room });
  for (const npc of novel.npcs.values()) candidates.push({ id: npc.id, room: npc.room_id ?? npc.location ?? null });
  for (const candidate of candidates) {
    if (!candidate.room) continue;
    if (active && candidate.id === active.id) continue;
    let witness: WitnessKind | null = null;
    let sense: PerceptionSense = null;
    let confidence = 0;
    if (candidate.room.toLowerCase() === sourceRoom.toLowerCase() && lit) {
      witness = "saw"; sense = "sight"; confidence = 1;
    } else if (isAudibleFrom(novel.world, sourceRoom, candidate.room)) {
      witness = "heard"; sense = "sound"; confidence = 0.6;
    }
    if (!witness) continue;
    const duplicate = novel.perception_ledger.some((p) =>
      p.event_ordinal === ordinal && p.entity_id === candidate.id && p.source_entity === (active?.id ?? null));
    if (duplicate) continue;
    appendPerceptionRecord(novel, {
      entity_id: candidate.id,
      event_ordinal: ordinal,
      kind: perceptionKind,
      summary: text,
      witness,
      sense,
      source_entity: active?.id ?? null,
      room_id: sourceRoom,
      confidence,
    });
  }
}

// REQ-620 — adventure discovery scans the data-directory install target first,
// then the configured/build directory, so an installed module is visible to
// every adventure surface. A slug present in both resolves to the installed
// copy (first directory wins).
function adventureDirs(): string[] {
  const configured = process.env.TTRPG_ADVENTURE_DIR ?? path.join(__dirname, "..", "adventures");
  const installed = path.join(DATA_DIR, "adventures");
  return configured === installed ? [installed] : [installed, configured];
}

function adventureFiles(): { slug: string; file: string; dir: string }[] {
  const seen = new Set<string>();
  const out: { slug: string; file: string; dir: string }[] = [];
  for (const dir of adventureDirs()) {
    let files: string[];
    try { files = fs.readdirSync(dir).filter((f) => f.endsWith(".md")).sort(); } catch { continue; }
    for (const file of files) {
      const slug = file.replace(/\.md$/, "");
      if (seen.has(slug)) continue;
      seen.add(slug);
      out.push({ slug, file, dir });
    }
  }
  // REQ-079g — explicit pre-load file paths join the scan, lowest priority.
  for (const { slug, file } of adventureExplicitFiles()) {
    if (seen.has(slug)) continue;
    seen.add(slug);
    out.push({ slug, file, dir: path.dirname(file) });
  }
  return out;
}

function findAdventureFile(slug: string): string | null {
  const match = adventureFiles().find((entry) => entry.slug === slug);
  return match ? path.join(match.dir, match.file) : null;
}

// REQ-292 — count adventure modules on disk (empty → 0).
function countAdventureModules(): number {
  return adventureFiles().length;
}

// REQ-079g — optional comma-separated adventure Markdown files pre-loaded at
// startup, in addition to the directory scan.
function adventureExplicitFiles(): { slug: string; file: string }[] {
  return (process.env.TTRPG_ADVENTURE ?? "")
    .split(",")
    .map((p) => p.trim())
    .filter(Boolean)
    .map((file) => ({ slug: path.basename(file).replace(/\.md$/i, ""), file }));
}

// REQ-170/171b/172 — the build-time index lives beside the modules it describes.
// Resolution is per directory so an installed index cannot shadow a configured
// one (and vice versa).
interface AdventureIndexEntry {
  title: string;
  content_hash: string;
  player_visible: boolean;
  source: string;
  malformed: Array<{ flag: string; convention: string; disposition: "skipped" | "partial" }>;
}

function readAdventureIndex(dir: string): Record<string, AdventureIndexEntry> | null {
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(dir, "index.json"), "utf-8"));
    return parsed?.modules && typeof parsed.modules === "object" ? parsed.modules as Record<string, AdventureIndexEntry> : null;
  } catch {
    // No index in this directory: its modules are treated as installed.
    return null;
  }
}

function adventureIndexEntryFor(slug: string, dir: string): AdventureIndexEntry | null {
  return readAdventureIndex(dir)?.[slug] ?? null;
}

let adventureIndexCache: Record<string, AdventureIndexEntry> | null = null;
let adventureDriftCache: Array<{ flag: string; slug: string; stored_hash: string; current_hash: string; detected_at: string }> = [];

function adventureIndexSnapshot(): Record<string, AdventureIndexEntry> {
  if (adventureIndexCache) return adventureIndexCache;
  const out: Record<string, AdventureIndexEntry> = {};
  const addInstalled = (slug: string, file: string) => {
    if (out[slug]) return;
    try {
      const content = fs.readFileSync(file, "utf-8");
      const structure = extractAdventureStructure(content, slug);
      out[slug] = {
        title: structure.title,
        content_hash: crypto.createHash("sha256").update(content).digest("hex"),
        player_visible: structure.player_visible,
        source: "installed",
        malformed: structure.malformed.map((m) => ({ flag: "[malformed-adventure]", ...m })),
      };
    } catch {
      // An unreadable module contributes nothing to the discovery surface.
    }
  };
  for (const dir of adventureDirs()) {
    const index = readAdventureIndex(dir);
    let files: string[] = [];
    try { files = fs.readdirSync(dir).filter((f) => f.endsWith(".md")).sort(); } catch { continue; }
    for (const file of files) {
      const slug = file.replace(/\.md$/i, "");
      const entry = index?.[slug];
      if (entry) { if (!out[slug]) out[slug] = entry; } else addInstalled(slug, path.join(dir, file));
    }
  }
  for (const { slug, file } of adventureExplicitFiles()) addInstalled(slug, file);
  adventureIndexCache = out;
  return out;
}

function skippedAdventureSlugs(): Set<string> {
  const out = new Set<string>();
  for (const [slug, entry] of Object.entries(adventureIndexSnapshot())) {
    if ((entry.malformed ?? []).some((m) => m.disposition === "skipped")) out.add(slug);
  }
  return out;
}

// REQ-172 — compare each indexed module's build hash against the file on disk.
function warmAdventureIndex(): void {
  adventureIndexCache = null;
  const drift: typeof adventureDriftCache = [];
  for (const dir of adventureDirs()) {
    const index = readAdventureIndex(dir);
    if (!index) continue;
    for (const [slug, entry] of Object.entries(index)) {
      const file = path.join(dir, `${slug}.md`);
      if (!fs.existsSync(file)) continue;
      let current = "";
      try { current = crypto.createHash("sha256").update(fs.readFileSync(file)).digest("hex"); } catch { continue; }
      if (current === entry.content_hash) continue;
      const record = { flag: "[adventure-drift]", slug, stored_hash: entry.content_hash, current_hash: current, detected_at: new Date().toISOString() };
      drift.push(record);
      process.stderr.write(`[holonovel] [adventure-drift] ${slug}: build hash ${entry.content_hash.slice(0, 12)} != current ${current.slice(0, 12)}\n`);
    }
  }
  adventureDriftCache = drift;
  adventureIndexSnapshot();
}

function adventureStructureFor(slug: string): { structure: AdventureStructure; content: string; filePath: string } | null {
  const filePath = findAdventureFile(slug);
  if (!filePath) return null;
  const content = fs.readFileSync(filePath, "utf-8");
  const { body } = parseAdventureProvenance(content);
  return { structure: extractAdventureStructure(body, slug), content, filePath };
}

// REQ-079c/d — pre-populate Novel state from the structural extraction. Skips
// duplicate names with a note; creates skeletal NPCs (name + prose only).
function prepopulateAdventure(novel: NovelState, structure: AdventureStructure, slug: string): { npcs: number; lore: number; factions: number; notes: string[]; suggestions: string[] } {
  const notes: string[] = [];
  const suggestions: string[] = [];
  let npcs = 0;
  let lore = 0;
  let factions = 0;
  const takenNpc = new Set([...novel.npcs.values()].map((n) => n.name.toLowerCase()));
  for (const entity of novel.entities.values()) takenNpc.add(entity.name.toLowerCase());
  const sceneLocation = structure.locations[0]?.name ?? novel.scene_location ?? undefined;
  for (const npc of structure.npcs) {
    const key = npc.name.toLowerCase();
    if (takenNpc.has(key)) { notes.push(`Skipped duplicate NPC '${npc.name}'.`); continue; }
    if (capGuard("npcs", novel.npcs.size)) { notes.push(`Skipped NPC '${npc.name}' — NPC limit reached.`); continue; }
    takenNpc.add(key);
    const id = `npc_${slug.replace(/[^a-z0-9]+/g, "_")}_${npcs + 1}`;
    novel.npcs.set(id, {
      id, name: npc.name, description: npc.description ?? npc.role ?? "",
      disposition: "neutral", location: sceneLocation, conditions: [], condition_rounds: {},
    } as any);
    npcs++;
    const rulesetSlug = novel.ruleset ?? null;
    if (rulesetSlug && rulesets.isInstalled(rulesetSlug)) {
      const normalize = (v: string) => v.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
      const hit = rulesets.search(rulesetSlug, npc.name, 5)
        .find((h) => normalize(h.id ?? "").includes(normalize(npc.name)) || (h.content ?? "").toLowerCase().includes(npc.name.toLowerCase()));
      if (hit) suggestions.push(`NPC '${npc.name}' may match ruleset entry '${hit.id || hit.anchor}'. Confirm to populate stats.`);
    }
  }
  for (const loc of structure.locations) {
    const key = adventureKey(loc.name);
    if (!key) continue;
    if (novel.lore.has(key)) { notes.push(`Skipped duplicate lore entry '${key}'.`); continue; }
    if (capGuard("lore", novel.lore.size)) { notes.push(`Skipped lore '${key}' — lore limit reached.`); continue; }
    novel.lore.set(key, {
      key, content: loc.description, triggers: [loc.name], badge_scope: loc.gm_only ? "game_master" : "shared",
      priority: 0, sticky: 0, sticky_remaining: 0, enabled: true, visibility: loc.gm_only ? "gm_only" : "shared", known_by: [],
    } as any);
    lore++;
  }
  const takenFaction = new Set(novel.factions.map((f) => f.name.toLowerCase()));
  for (const faction of structure.factions) {
    const key = faction.name.toLowerCase();
    if (takenFaction.has(key)) { notes.push(`Skipped duplicate faction '${faction.name}'.`); continue; }
    takenFaction.add(key);
    novel.factions.push({
      id: `faction_${slug.replace(/[^a-z0-9]+/g, "_")}_${factions + 1}`,
      name: faction.name,
      description: faction.description ?? "",
      goals: faction.goals ? [faction.goals] : [],
      resources: "",
      clock: 0,
      clock_max: 4,
      status: "active",
    } as any);
    factions++;
  }
  return { npcs, lore, factions, notes, suggestions };
}

// REQ-132e — generated world-model objects are Novel-scoped and removed when
// the generated adventure is replaced.
function removeRoomsByName(novel: NovelState, names: string[]): void {
  const norm = new Set(names.map((n) => n.toLowerCase()));
  if (norm.size === 0) return;
  for (const [id, room] of [...novel.world.rooms]) {
    if (norm.has(room.name.toLowerCase())) novel.world.rooms.delete(id);
  }
  for (const room of novel.world.rooms.values()) {
    for (const [dir, dest] of [...room.exits]) {
      if (norm.has(String(dest).toLowerCase())) room.exits.delete(dir);
    }
  }
  for (const [id, thing] of [...novel.world.things]) {
    if (norm.has(String((thing as any).location ?? "").toLowerCase())) novel.world.things.delete(id);
  }
}

// REQ-229a-d — one synthesis renderer for every load branch. An empty term
// never matches (the previous implementation counted every item because
// `includes("")` is always true).
function adventureSynthesisMatches(structure: AdventureStructure): { voice: number; lore: number; community: number } {
  const manifest: any = state.wisdomManifest ?? {};
  const locationTerms = structure.locations.map((l) => l.name.toLowerCase());
  const loreTerms = structure.sections.flatMap((sec) =>
    [...sec.body.matchAll(/@lore\(([^)]+)\)/g)].map((m) => m[1].trim().toLowerCase()));
  const npcTerms = structure.npcs.map((n) => n.name.toLowerCase()).filter((n) => n.length > 2);
  const premiseTerms = structure.premise.toLowerCase().split(/\W+/).filter((w) => w.length > 4);
  const patternTerms = structure.sections.filter((sec) => /^encounters?$/i.test(sec.heading))
    .flatMap((sec) => sec.body.toLowerCase().split(/\W+/)).filter((w) => w.length > 4);
  const hit = (hay: string, terms: string[]) => terms.some((t) => t.length > 2 && hay.includes(t));
  const playerVoice = (state.activeNovel?.player_synthesis?.voice_examples ?? []) as any[];
  const playerLore = (state.activeNovel?.player_synthesis?.lore_templates ?? []) as any[];
  const voiceItems = [...((manifest.voice_examples ?? []) as any[]), ...playerVoice];
  const loreItems = [...((manifest.lore_templates ?? []) as any[]), ...playerLore];
  const actionItems = (manifest.action_patterns ?? []) as any[];
  const adviceItems = (manifest.adventure_advice?.templates ?? []) as any[];
  const voiceMatched = voiceItems.filter((v) => hit(`${v.content ?? ""} ${v.context ?? ""} ${v.dialogue ?? ""} ${v.entity_name ?? ""} ${v.name ?? ""}`.toLowerCase(), npcTerms));
  const loreMatched = loreItems.filter((l) => hit(`${l.content ?? ""} ${l.keyword ?? ""} ${l.key ?? ""} ${l.category ?? ""}`.toLowerCase(), [...locationTerms, ...loreTerms]));
  const actionMatched = actionItems.filter((a) => hit(`${a.content ?? ""} ${a.category ?? ""}`.toLowerCase(), patternTerms));
  const adviceMatched = adviceItems.filter((a) => hit(`${a.content ?? ""} ${a.title ?? ""}`.toLowerCase(), [...premiseTerms, ...locationTerms]));
  // Community items stay inert (REQ-080/229c): every supplementary item is
  // reported for activation, whether or not this adventure matched it.
  const community = [...voiceItems, ...loreItems, ...actionItems, ...adviceItems]
    .filter((m) => String(m?.tag ?? "") === "supplementary").length;
  return { voice: voiceMatched.length, lore: loreMatched.length, community };
}

function adventureAugmentation(structure: AdventureStructure): string {
  const m = adventureSynthesisMatches(structure);
  const parts: string[] = [];
  if (m.voice > 0 || m.lore > 0) {
    parts.push(`Synthesis found ${m.voice} voice examples for adventure NPCs, ${m.lore} lore templates for adventure locations. Review at \`synthesis://status\`.`);
  }
  if (m.community > 0) {
    parts.push(`Synthesis ${m.community} items found. Review at \`synthesis://status\` and activate individually.`);
  }
  return parts.length > 0 ? `\n\n${parts.join(" ")}` : "";
}

function getActiveEntity() {
  return state.getActiveEntity();
}

function resolveEntity(id?: string) {
  return state.resolveEntity(id);
}

// REQ-120 — NPC rendering: an NPC identifier produces a stat block via the same
// mechanism as entity character sheets; an ID resolving to neither returns
// [NOT_FOUND]. Player badge sees only fields visible in badge_briefing.
function resolveEntityOrNpc(id?: string): any {
  const novel = state.activeNovel;
  if (!novel) return undefined;
  if (id && novel.npcs.has(id)) return novel.npcs.get(id);
  if (id && novel.entities.has(id)) return novel.entities.get(id);
  return state.resolveEntity(id);
}

// REQ-548a — structured tool-result payload: every response carries a
// machine-readable result alongside its text envelope. REQ-312e — narration
// grounding set: with validation enabled, the result names the entities,
// values, and conditions it establishes. REQ-548d — enumerable decisions carry
// a machine-readable option set.
function groundingSet(): Record<string, any> | undefined {
  if (!narrationValidationOn()) return undefined;
  const novel = state.activeNovel;
  if (!novel) return undefined;
  return {
    entities: [...novel.entities.keys()],
    npcs: [...novel.npcs.keys()],
    scene: novel.scene_description ?? null,
    rooms: novel.world.rooms.size,
    things: novel.world.things.size,
  };
}
function structured(status: string, text: string, extra?: Record<string, any>) {
  const fields: Record<string, any> = { status, text, ...(extra ?? {}) };
  const g = groundingSet();
  if (g) fields.grounding = g;
  return fields;
}
// REQ-042b / REQ-191 / REQ-548d — every [NEED_INPUT] decision carries a
// machine-readable option set as kebab `value` + human `label` pairs, capped at
// 25 entries, with an empty-string (free-text) option and `cancel` always last.
function kebabOptionValue(raw: string): string {
  return raw
    .toLowerCase()
    .replace(/[`*_]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
function clampOptionLabel(raw: string): string {
  const label = raw.replace(/[`*_]/g, "").replace(/[.\s]+$/, "").trim();
  return label.length > 60 ? `${label.slice(0, 57)}...` : label;
}
function parseDecisionOptions(text: string): Array<{ value: string; label: string }> {
  const parsed: Array<{ value: string; label: string }> = [];
  const seen = new Set<string>();
  const push = (value: string, label: string) => {
    const v = value.trim() === "" ? "" : kebabOptionValue(value);
    if (v === "" || v === "cancel" || seen.has(v)) return;
    seen.add(v);
    parsed.push({ value: v, label: clampOptionLabel(label) });
  };
  // Multi-line choice lists: `  **<id>** — <label>[: <description>]`.
  for (const m of text.matchAll(/\*\*([^*\n]+)\*\*\s*[—–-]\s*([^\n:]+)/g)) {
    push(m[1], m[2]);
  }
  // Single-line option lists: `Options: a, b, c` or `Options: a (A), b (B)`;
  // the classes step phrases its list as `Classes: ...` (REQ-042b).
  const line = text.match(/(?:Options|Classes):\s*([^\n]+)/);
  if (line) {
    for (const raw of line[1].split(",").map((s) => s.trim()).filter(Boolean)) {
      const pair = raw.match(/^([^(]+?)\s*\((.+)\)\.?$/);
      push(pair ? pair[1] : raw, pair ? pair[2] : raw);
    }
  }
  // REQ-042b — free-text (empty-string) and cancel are always available.
  const capped = parsed.slice(0, 23);
  capped.push({ value: "", label: "(free-text)" });
  capped.push({ value: "cancel", label: "Cancel" });
  return capped;
}
function ok(text: string) {
  const expanded = expandMacros(text, buildMacroContext());
  return { content: [{ type: "text" as const, text: `[OK] ${expanded}` }], structuredContent: structured("OK", expanded) };
}

// REQ-548a — an OK envelope that also carries a typed payload. `structured`
// merges the fields and appends `grounding`, so the recap cannot drop it.
function okWith(text: string, fields: Record<string, any>) {
  const expanded = expandMacros(text, buildMacroContext());
  return { content: [{ type: "text" as const, text: `[OK] ${expanded}` }], structuredContent: structured("OK", expanded, fields) };
}

// REQ-002 — error taxonomy: every failure surfaces [ERROR] [CODE] + corrective
// action; REQ-001 — response contract (OK/raw/err) and REQ-032 server-side
// gating via requireGM/requirePlayer.
const CORRECTIVE_ACTIONS: Record<string, string> = {
  NOT_FOUND: "Check the name or id for typos, or list valid values with help.",
  INVALID_INPUT: "Supply a valid value for every required parameter.",
  STATE_CONFLICT: "Resolve the conflicting state before retrying.",
  FORBIDDEN: "Switch badges with set_badge to gain access, or use a permitted tool.",
  RULE_VIOLATION: "Choose an action the rules permit.",
  AMBIGUOUS: "Disambiguate by supplying the full name.",
  UNIMPLEMENTED: "This operation is not supported by the current ruleset host.",
};

function err(code: string, msg: string, correctiveAction?: string) {
  const expanded = expandMacros(msg, buildMacroContext());
  const action = correctiveAction ?? CORRECTIVE_ACTIONS[code];
  const text = action ? `[ERROR] [${code}] ${expanded}\nCorrective action: ${action}` : `[ERROR] [${code}] ${expanded}`;
  const values = parseValidValues(expanded);
  return {
    content: [{ type: "text" as const, text }],
    // REQ-001b1 — a tool-level [ERROR] response is a normal result carrying
    // `isError: true`, so the calling model can react to it.
    isError: true as const,
    structuredContent: structured("ERROR", expanded, { category: code, corrective_action: action ?? null, ...(values ? { values } : {}) }),
  };
}

// REQ-548c — the valid-value enumeration the text already carries, as a
// structured array. One source, so the two cannot disagree; badge filtering of
// that source is the caller's responsibility (REQ-002c).
function parseValidValues(text: string): string[] | null {
  const match = text.match(/Valid values:\s*([^\n]+)/);
  if (!match) return null;
  const rawList = match[1].replace(/\.\s*$/, "").trim();
  if (!rawList) return null;
  const values = rawList.split(",").map((value) => value.trim().replace(/…$/, "").trim()).filter(Boolean);
  return values.length > 0 ? values : null;
}

// REQ-001/REQ-548c — every error envelope that reaches a caller whose former
// SDK path threw now flows through `err()`, which carries `isError: true`
// (REQ-001b1) alongside the structured result.

// REQ-129a/c — cardinality refusal naming the affected group and the current
// and maximum counts; a configured maximum of zero disables the group.
function capGuard(group: string, current: number) {
  const r = capRefusal(group, current);
  if (!r) return null;
  const detail = r.max === 0
    ? `${r.group} is disabled (configured maximum 0).`
    : `${r.group} at maximum (${r.current}/${r.max}).`;
  return err("STATE_CONFLICT", detail);
}

// REQ-322c — a mission clock reads as a progress fraction and is "filled" at
// total; a decrement clock keeps its remaining count until then.
function countdownDisplay(cd: { ticks: number; total?: number; clock_type?: string }): string {
  if (cd.clock_type === "mission") {
    if (cd.total && cd.ticks >= cd.total) return "filled";
    return `${cd.ticks}/${cd.total ?? "?"}`;
  }
  return `${cd.ticks} remaining`;
}

// REQ-079a — `@npc`/`@lore` materialization. The world layer parses the
// directives because it owns room/thing resolution; this adapter layer owns
// the Novel writes. A duplicate skips with a note (REQ-079d) and a group at
// its maximum skips with a warning (REQ-129b1) — an annotation never blocks a
// load, and the enclosing handler owns persistence and audit.
function annotationKey(name: string): string {
  return annotationName(name).replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") || "annotation";
}

function annotationNpcId(novel: NovelState, name: string): string {
  const base = `npc_${annotationKey(name)}`;
  if (!novel.npcs.has(base)) return base;
  for (let suffix = 2; ; suffix++) {
    const candidate = `${base}_${suffix}`;
    if (!novel.npcs.has(candidate)) return candidate;
  }
}

function materializeAnnotations(
  novel: NovelState,
  directives: AnnotationDirective[],
  slug: string | null,
): { counts: { npcs: number; lore: number }; warnings: string[] } {
  const counts = { npcs: 0, lore: 0 };
  const warnings: string[] = [];

  for (const directive of directives) {
    if (directive.category === "npc") {
      const comma = directive.target.indexOf(",");
      const name = directive.target.slice(0, comma).trim();
      const roomName = directive.target.slice(comma + 1).trim();
      const duplicate = [...novel.npcs.values()].some((npc) => annotationName(npc.name) === annotationName(name));
      if (duplicate) {
        warnings.push(`@npc(${directive.target}) skipped (duplicate) — a Novel NPC named '${name}' already exists.`);
        continue;
      }
      const cap = capRefusal("npcs", novel.npcs.size);
      if (cap) {
        warnings.push(`@npc(${directive.target}) skipped — npcs at maximum (${cap.current}/${cap.max}).`);
        continue;
      }
      const wanted = annotationName(roomName);
      const roomEntry = [...novel.world.rooms.entries()].find(([, room]) => annotationName(room.name) === wanted);
      const id = annotationNpcId(novel, name);
      const npc: NpcState = {
        id,
        name,
        ...(directive.content ? { description: directive.content } : {}),
        location: roomEntry ? roomEntry[1].name : roomName,
        ...(roomEntry ? { room_id: roomEntry[0] } : {}),
        ...(slug ? { provenance: { source: `loaded:${slug}` } } : {}),
        conditions: [],
        condition_rounds: {},
      };
      novel.npcs.set(id, npc);
      if (roomEntry) roomEntry[1].annotations.npc = name;
      counts.npcs += 1;
      continue;
    }

    const key = annotationKey(directive.target);
    if (novel.lore.has(key)) {
      warnings.push(`@lore(${directive.target}) skipped (duplicate) — lore entry '${key}' already exists.`);
      continue;
    }
    const cap = capRefusal("lore", novel.lore.size);
    if (cap) {
      warnings.push(`@lore(${directive.target}) skipped — lore at maximum (${cap.current}/${cap.max}).`);
      continue;
    }
    const wanted = annotationName(directive.target);
    const roomEntry = [...novel.world.rooms.entries()].find(([, room]) => annotationName(room.name) === wanted);
    const thingEntry = [...novel.world.things.entries()].find(([, thing]) => annotationName(thing.name) === wanted);
    const worldTarget = roomEntry?.[0] ?? thingEntry?.[0];
    if (!worldTarget) {
      warnings.push(`@lore(${directive.target}) target is not in the world model — entry created without a world_target.`);
    }
    const entry: LoreEntry = {
      key,
      content: directive.content,
      triggers: [wanted],
      badge_scope: "shared",
      // REQ-083d — module lore is player-facing content; state the read gate
      // explicitly rather than relying on the gm_only default.
      visibility: "shared",
      known_by: [],
      priority: 0,
      sticky: 0,
      sticky_remaining: 0,
      enabled: true,
      ...(worldTarget ? { world_target: worldTarget } : {}),
    };
    novel.lore.set(key, entry);
    if (roomEntry) roomEntry[1].annotations.lore = key;
    counts.lore += 1;
  }

  return { counts, warnings };
}

// REQ-054 — input safety: all tool inputs are validated server-side (Zod);
// adversarial free-text is stored and echoed verbatim as inert data with no
// behavior change. The server trusts nothing client-supplied.
let narrationRejectionCount = 0;
// REQ-312 — pre-narration validation gate: TTRPG_NARRATION_VALIDATION (on|off)
// controls mechanical-claim validation of AI narration; rejected proposals
// increment narration_rejection_count and surface a [REJECTED] corrective.
function narrationValidationOn(): boolean { return (process.env.TTRPG_NARRATION_VALIDATION ?? "off") === "on"; }
// REQ-388 / REQ-412a — guidance profile: `full` (default) or `lean`. `lean`
// tightens briefing scaffolding for constrained narrators.
function guidanceProfile(): "full" | "lean" { return (process.env.TTRPG_GUIDANCE_PROFILE ?? "full") === "lean" ? "lean" : "full"; }
function validateNarration(claim: string, novel: NovelState): string | null {
  if (!narrationValidationOn()) return null;
  const t = claim.toLowerCase();
  // REQ-312c — state conformance: a dead NPC speaking is rejected.
  for (const [, npc] of novel.npcs) {
    const hp = (npc as any).stats?.hp ?? (npc as any).stats?.current_hp;
    if (hp !== undefined && Number(hp) <= 0 && t.includes(npc.name.toLowerCase())) {
      narrationRejectionCount++;
      return `[REJECTED] ${npc.name} is incapacitated (HP ${hp}) and cannot act or speak.`;
    }
  }
  // REQ-312b — permission conformance: a spellcast claim with no spell resources is rejected.
  if (/(casts|cast)\s+\w+/.test(t) && !/(spell slot|mana|focus)/.test(t)) {
    narrationRejectionCount++;
    return "[REJECTED] Casting requires a spell resource the entity may not possess.";
  }
  return null;
}

function raw(text: string) {
  const expanded = expandMacros(text, buildMacroContext());
  const status = classifyStatus(expanded);
  return {
    content: [{ type: "text" as const, text: expanded }],
    // REQ-001b1 — a raw payload whose declared status is ERROR is a tool-level
    // error; the JSON body stays byte-verbatim (REQ-001).
    ...(status === "ERROR" ? { isError: true as const } : {}),
    structuredContent: structured(status, expanded),
  };
}

function warn(text: string) {
  const expanded = expandMacros(text, buildMacroContext());
  return { content: [{ type: "text" as const, text: `[WARNING] ${expanded}` }], structuredContent: structured("WARNING", expanded) };
}

function needInput(text: string) {
  const expanded = expandMacros(text, buildMacroContext());
  return { content: [{ type: "text" as const, text: `[NEED_INPUT] ${expanded}` }], structuredContent: structured("NEED_INPUT", expanded, { options: parseDecisionOptions(expanded) }) };
}

// REQ-050a — seed conflict. A caller-supplied per-call seed while TTRPG_SEED is
// set appends one advisory line; the tool's own status is unchanged (the draw
// completed, and the per-call seed won).
function seedWarningSuffix(seed: unknown): string {
  const warning = seedConflictWarning(seed);
  return warning ? `\n${warning}` : "";
}

// REQ-050a — a JSON-bodied result stays parseable: the conflict line rides as a
// second content block plus a `warnings` field, never inside the JSON text.
function withSeedWarning<T extends { content: Array<{ type: "text"; text: string }>; structuredContent?: any }>(result: T, seed: unknown): T {
  const warning = seedConflictWarning(seed);
  if (!warning) return result;
  result.content = [...result.content, { type: "text" as const, text: warning }];
  if (result.structuredContent) result.structuredContent.warnings = [...(result.structuredContent.warnings ?? []), warning];
  return result;
}

// ── §5.1 Output and Error Contracts ────────────────────────────────
//
// REQ-004 — truncation: tool output longer than a configurable limit is
// truncated with `… [truncated — full content: output://<tool>/<counter>]`.
// The full payload is stored in `outputStore` (session-local, badge-filtered
// on read via REQ-179/REQ-179c); the store evicts the oldest entry past the
// session limit, after which the pointer resolves to `[ERROR] [NOT_FOUND]`.
// REQ-180b — the limit is measured in UTF-8 bytes of the joined text content.
const outputLimit = (): number => configInt("TTRPG_OUTPUT_LIMIT", 32000);
const outputSessionLimit = (): number => configInt("TTRPG_OUTPUT_SESSION_LIMIT", 20);
let outputCounter = 0;
// REQ-179c — a payload records the badge that produced it; only that badge (or
// the Editor badge) may read it, through any reader.
interface OutputPayload { text: string; pointer: string; badge: Badge }
const outputStore: Map<string, OutputPayload> = new Map();
function outputReadable(payload: OutputPayload): boolean {
  const badge = getBadge();
  return badge === "none" || badge === payload.badge;
}
const OUTPUT_NOT_FOUND = "[ERROR] [NOT_FOUND] No output payload resolves for this pointer under the active badge; it may have been evicted. Corrective action: switch badges with set_badge to the badge that produced it, or re-run the tool.";
function storeOutput(tool: string, text: string): { key: string; pointer: string } {
  const key = `${tool}/${++outputCounter}`;
  const pointer = `… [truncated — full content: output://${key}]`;
  outputStore.set(key, { text, pointer, badge: getBadge() });
  while (outputStore.size > outputSessionLimit()) {
    const oldest = outputStore.keys().next().value;
    if (oldest === undefined) break;
    outputStore.delete(oldest);
  }
  return { key, pointer };
}
// REQ-004 — the single channel every tool result passes through (host and
// package tools alike). A result over the byte limit becomes a pointer in its
// text content and in its structured `text` mirror; other structured fields
// survive.
function truncateResult(tool: string, result: any): any {
  if (!result || typeof result !== "object" || !Array.isArray(result.content)) return result;
  const joined = result.content
    .filter((c: any) => typeof c?.text === "string")
    .map((c: any) => c.text)
    .join("\n");
  if (Buffer.byteLength(joined, "utf8") <= outputLimit()) return result;
  // REQ-180c — a machine-readable body is delivered intact: clients parse it,
  // and a pointer would make it invalid JSON. The pointer mechanism covers
  // human-readable text and JSON-plus-source-block payloads.
  try {
    JSON.parse(joined.trim());
    return result;
  } catch { /* not one JSON document — fall through to truncation */ }
  const { pointer } = storeOutput(tool, joined);
  const nonText = result.content.filter((c: any) => typeof c?.text !== "string");
  result.content = [{ type: "text", text: pointer }, ...nonText];
  const structured = result.structuredContent;
  if (structured && typeof structured === "object" && typeof structured.text === "string") {
    result.structuredContent = { ...structured, text: pointer };
  }
  return result;
}
function truncateHandler(tool: string, handler: any) {
  return async (...args: any[]) => truncateResult(tool, await handler(...args));
}

// REQ-194 — anchor derivation (implemented in core/anchors.ts; used by the
// §5.3 lookup tools and source-anchor citation below). When an index entry
// lacks an explicit anchor, the heading path is derived deterministically.
function sourceAnchor(entry: any): Record<string, any> {
  const f = entry?.source_file ?? null;
  const raw = entry?.anchor ?? entry?.id ?? null;
  const a = raw !== null ? deriveAnchor(String(raw)) : null;
  if (f || a) return { source_anchor: { file: f, heading: a, line_range: entry?.line_range ?? null } };
  // No derivable anchor: preserve any anchor the model entry itself carries
  // rather than overwriting it with null (the spread order earlier clobbered it).
  return { source_anchor: entry?.source_anchor ?? null };
}

// Normalize an index id or a lookup key for joining: index ids are hyphenated
// (`stat-checks`, `gain-stress`) while model/lookup keys are underscored
// (`stat_check`, `stress`).
function normId(s: any): string {
  return String(s ?? "").trim().toLowerCase().replace(/[\s_]+/g, "-");
}
function sourceBlock(entry: any): string {
  const f = entry?.source_file;
  const raw = entry?.anchor ?? entry?.id;
  const a = raw !== null && raw !== undefined ? deriveAnchor(String(raw)) : null;
  if (!f && !a) return "";
  const label = f && a ? `${f}#${a}` : (f ?? a);
  const excerpt = entry?.content ?? "";
  return `\n---\n${label}\n${excerpt.split("\n").slice(0, 3).join("\n")}`;
}

// REQ-113 — result count reporting: a collection-returning tool reports both
// the returned count and the total match count.
function countReport(returned: number, total: number): string {
  if (total <= returned) return "";
  return `\n[${returned} of ${total} results]`;
}

// REQ-112 — cross-reference discovery: when a canonical entry's text names
// another indexed section by its anchor or heading, return a non-recursive
// pointer (anchor + one-line description). No cross-references → no pointers.
function discoverCrossRefs(pkg: any, entry: any, idxEntry: any): Record<string, unknown> {
  const text = `${entry?.content ?? ""} ${entry?.description ?? ""} ${idxEntry?.content ?? ""}`.toLowerCase();
  const pointers: Array<{ anchor: string; description: string }> = [];
  for (const i of pkg.index ?? []) {
    const anchor = i?.anchor ?? i?.id;
    if (!anchor) continue;
    const needle = String(anchor).toLowerCase();
    if (text.includes(needle) && needle.length > 4) {
      pointers.push({ anchor: deriveAnchor(String(anchor)), description: (i?.content ?? "").slice(0, 80) });
    }
  }
  return pointers.length > 0 ? { cross_references: pointers } : {};
}

// "Did you mean?" hint: closest valid value by Levenshtein distance (≤3 edits).
function closestMatch(input: string, values: string[]): string | null {
  let best: string | null = null;
  let bestDist = 4;
  for (const v of values) {
    const d = levenshtein(input, v.toLowerCase());
    if (d < bestDist) { bestDist = d; best = v; }
  }
  return best;
}
function levenshtein(a: string, b: string): number {
  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 0; j <= b.length; j++) dp[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
  }
  return dp[a.length][b.length];
}

// REQ-070 / REQ-184 — Appendix J anti-slop synopsis (badge-filtered).
const APPENDIX_J_ANTI_SLOP: Array<{ scope: string; severity: string; pattern: string; forbidden: string; correct: string }> = [
  { scope: "GM", severity: "Soft", pattern: "Purple prose", forbidden: "Over-ornamented description burying detail", correct: "Concrete, sensory, actionable — \"The hall is old. Cracked pillars.\"" },
  { scope: "GM", severity: "Soft", pattern: "Negation framing", forbidden: "Describing by what is absent (\"you don't see…\")", correct: "Describing what is present (\"The corridor is still. Dust settles.\")" },
  { scope: "GM", severity: "Soft", pattern: "Rushing to closure", forbidden: "Resolving all tension in one response", correct: "Ending on an image or choice, not a resolution" },
  { scope: "GM", severity: "Hard", pattern: "Declaring player actions", forbidden: "Narrating what a PC thinks, feels, or decides", correct: "Describing the world; letting the player react" },
  { scope: "Player", severity: "Hard", pattern: "Establishing world facts", forbidden: "Declaring what exists as established truth", correct: "Asking whether elements exist" },
  { scope: "Player", severity: "Hard", pattern: "Assuming outcomes", forbidden: "Narrating results before adjudication", correct: "Describing intent and attempt, waiting for resolution" },
  { scope: "Player", severity: "Hard", pattern: "Declaring NPC reactions", forbidden: "Stating how an NPC responds", correct: "Laying out reasoning, waiting for GM response" },
  { scope: "GM", severity: "Soft", pattern: "Echoing", forbidden: "Restating player action without adding new information", correct: "Advancing the scene with new sensory detail or consequence" },
  { scope: "GM", severity: "Soft", pattern: "Passive voice dominance", forbidden: "Describing events without engaging player agency", correct: "Centering the player's senses or actions" },
  { scope: "GM", severity: "Soft", pattern: "Motif repetition", forbidden: "Reusing the same adjective or descriptive template", correct: "Varying sensory register between responses" },
  { scope: "GM", severity: "Hard", pattern: "Constraint forgetting", forbidden: "Narrating in contradiction of established scene state", correct: "Checking active scene state and conditions before narrating" },
  { scope: "Both", severity: "Soft", pattern: "Meta-commentary leakage", forbidden: "Breaking character with out-of-character commentary", correct: "Staying in the narrative register; reserving OOC for explicit markers" },
  { scope: "GM", severity: "Hard", pattern: "State and counter leakage", forbidden: "Stating counters, dials, tick totals, resource numbers, dispositions, inventory lists, exit lists, or tool output in narrative prose", correct: "Rendering state as sensory consequence — the flame shortens, the cold deepens — and keeping any permitted numeric status on a separate line" },
  { scope: "GM", severity: "Hard", pattern: "Unrevealed place naming", forbidden: "Naming a floor, room, or destination the character has not entered or been told about", correct: "Describing only what the character can perceive or has learned; let the map reveal itself on arrival" },
  { scope: "GM", severity: "Hard", pattern: "Theme labeling", forbidden: "Naming an authorial theme or allegory (a sin, a virtue, an act label) in the fiction", correct: "Rendering the concrete detail and letting the reader infer the theme" },
  { scope: "GM", severity: "Soft", pattern: "Voice homogeneity", forbidden: "Giving every NPC the same clipped, aphoristic cadence", correct: "Distinguishing speakers by syntax, diction, and what each refuses to say" },
];
function antiSlopFor(badge: string): string {
  const rows = APPENDIX_J_ANTI_SLOP.filter((r) => r.scope === "Both" || r.scope === (badge === "game_master" ? "GM" : "Player"));
  if (rows.length === 0) return "";
  return rows.map((r) => `- [anti-slop] [${r.severity}] ${r.pattern}: ${r.forbidden} → ${r.correct}`).join("\n");
}

// REQ-118 — prompt length budget. When a constructed prompt exceeds its budget,
// low-priority sections are replaced with `[truncated]` markers plus a pointer
// to the matching guidance resource. Section headers survive; required contract
// elements (badge boundary REQ-064, intro pointer REQ-063) are never truncated.
// REQ-135 — badge briefing size budget: same truncation discipline, never
// touching badge foundations and the intro pointer; REQ-180 — byte-UTF-8
// thresholds (characters ≈ bytes for UTF-8 Markdown here).
// REQ-135 — the briefing budget is the spec-declared
// `TTRPG_MAX_BRIEFING_TOKENS` (04-runtime.md config table); the historical
// `TTRPG_PROMPT_BUDGET` remains a fallback so existing callers keep working.
const briefingBudget = (): number =>
  configInt("TTRPG_MAX_BRIEFING_TOKENS", configInt("TTRPG_PROMPT_BUDGET", 16000));
// REQ-135 — sections that always render in full. REQ-400 (State-Persistence
// Directive), REQ-401 (state_ledger token), and REQ-407 (Persistence tools)
// each name the never-truncated tier explicitly. The intro pointer (REQ-063)
// and the consistency footer are appended after the budget pass, so they need
// no member here.
const NEVER_TRUNCATED = new Set(["badge boundary", "turn handoff", "play loop", "state persistence", "state_ledger", "persistence tools", "player signals"]);
// REQ-118 — every prompts/get result stays within the per-prompt budget.
// Sections are truncated lowest-priority first, preserving headers and the
// never-truncated contract elements. Prefer the deepest heading level present
// (badge_briefing's ### sections) so existing truncation is unchanged; fall
// back to ## sections, then to a structure-less prefix for prompts with no
// headings.
function applyPromptBudget(text: string): string {
  const budget = briefingBudget();
  if (text.length <= budget) return text;
  const level = text.includes("\n### ") ? "###" : text.includes("\n## ") ? "##" : null;
  if (!level) {
    const marker = "\n\n[truncated — full content: guidance://current]";
    return text.slice(0, Math.max(0, budget - marker.length)) + marker;
  }
  const sections = text.split(new RegExp(`\\n(?=${level} )`));
  const headerRe = new RegExp(`^${level} ([^\\n]+)`);
  let kept = "";
  for (const section of sections) {
    const header = section.match(headerRe)?.[1]?.toLowerCase() ?? "";
    const required = [...NEVER_TRUNCATED].some((n) => header.includes(n));
    if (required || kept.length + section.length <= budget) {
      kept += kept ? "\n" : "";
      kept += section;
    } else {
      const slug = header.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
      kept += `\n${level} ${header.charAt(0).toUpperCase() + header.slice(1)} [truncated — full content: guidance://${slug || "current"}]`;
    }
  }
  return kept;
}

function buildMacroContext() {
  const novel = state.activeNovel;
  const entity = state.getActiveEntity();
  const countdowns: Record<string, { remaining: number; total: number; scope?: string; direction?: string }> = {};
  if (novel) {
    for (const [name, cd] of novel.countdowns) {
      countdowns[name] = { remaining: cd.ticks, total: cd.total, scope: cd.scope, direction: cd.direction };
    }
  }
  return {
    entityName: entity?.name,
    sceneCurrent: novel?.scene_description,
    sceneLocation: novel?.scene_location,
    sceneTimeOfDay: novel?.scene_time_of_day,
    sceneAtmosphere: novel?.scene_atmosphere,
    sceneType: novel?.scene_type?.join(", "),
    countdowns,
    novelSlug: novel?.slug,
    badgeActive: novel?.badge ?? undefined,
    partySize: novel ? novel.entities.size : undefined,
    currentRoom: entity?.current_room ?? undefined,
    worldRoomCount: novel ? novel.world.rooms.size : undefined,
    worldThingCount: novel ? novel.world.things.size : undefined,
  };
}

function worldSnapshot(): void {
  novelSnapshot();
}

