// REQ-383a — per-ruleset health, computed from each installed package's
// metadata and index WITHOUT hydrating it (REQ-390b). Fields a package does
// not declare report `not-declared` rather than a fabricated value.
function buildRulesetHealthSections(): Record<string, any> {
  const out: Record<string, any> = {};
  const alerts = rulesets.toolQualityAlerts();
  const incompatible = new Set(rulesets.incompatibleSlugs().map((e) => e.slug));
  for (const { slug, manifest } of rulesets.manifests()) {
    const entries = rulesets.indexForReport(slug);
    const totals: Record<string, number> = {};
    const perFile: Record<string, Record<string, number>> = {};
    for (const e of entries) {
      const c = String((e as any).confidence ?? "unknown").toUpperCase();
      totals[c] = (totals[c] ?? 0) + 1;
      const f = (e as any).source_file ?? "(unknown)";
      (perFile[f] ??= {})[c] = (perFile[f][c] ?? 0) + 1;
    }
    const n = entries.length;
    const high = totals.HIGH ?? 0;
    const overall = n === 0 ? "N/A" : high / n >= 0.9 ? "HIGH" : high / n >= 0.5 ? "MEDIUM" : "LOW";
    const counts = manifest.counts ?? {};
    out[slug] = {
      confidence: { overall, entries: n, totals, per_file: perFile },
      indexed_counts: {
        anchors: n,
        concepts: counts.concepts ?? 0,
        entity_types: counts.entities ?? 0,
        actions: counts.actions ?? 0,
        tables: counts.tables ?? 0,
        procedures: counts.resolution ?? 0,
        guidance_items: counts.guidance ?? 0,
        synthesis_items: counts.synthesis ?? 0,
      },
      must_action_coverage: manifest.must_action_coverage ?? "not-declared",
      defect_count: alerts.filter((a) => a.slug === slug).length + (incompatible.has(slug) ? 1 : 0),
      verification_dispositions: manifest.verification_dispositions ?? "not-declared",
    };
  }
  return out;
}

// ── REQ-138a / REQ-139 — prompt references and live resource presence ──

// A tool reference is a name on the host verb grammar (or a live package tool
// name); a bare snake_case state field (`max_hp`), a badge value
// (`game_master`), or prose must not be treated as one.
const TOOL_REFERENCE = /\b(?:manage|resolve|run|set|open|close|take|respond)_[a-z0-9_]+\b/g;
const URI_REFERENCE = /\b([a-z][a-z0-9+.-]*):\/\/[^\s"'`)\]>,;]*/gi;

interface LiveResourceIndex {
  entries: Map<string, { name: string; title?: string; mime_type?: string; package_slug?: string }>;
  templates: Set<string>;
  schemes: Set<string>;
}

function liveResourceIndex(): LiveResourceIndex {
  const entries: LiveResourceIndex["entries"] = new Map();
  const templates = new Set<string>();
  const schemes = new Set<string>();
  const fixed: Record<string, any> = (server as any)._registeredResources ?? {};
  for (const [uri, r] of Object.entries(fixed)) {
    const name = typeof r?.name === "string" ? r.name : uri;
    const slug = name.startsWith("pkg:") ? name.slice(4).split(":")[0] : undefined;
    // A removed package's registration survives until its handle is removed;
    // while the slug is uninstalled it is not part of the live surface.
    if (slug && !rulesets.isInstalled(slug)) continue;
    const mime = r?.metadata?.mimeType;
    entries.set(uri, {
      name,
      title: typeof r?.title === "string" ? r.title : undefined,
      mime_type: typeof mime === "string" ? mime : undefined,
      package_slug: slug,
    });
    if (uri.includes("://")) schemes.add(uri.split("://")[0].toLowerCase());
  }
  const templated: Record<string, any> = (server as any)._registeredResourceTemplates ?? {};
  for (const [regName, r] of Object.entries(templated)) {
    const raw = r?.resourceTemplate?.uriTemplate ?? r?.template?.uriTemplate;
    const template = typeof raw === "string" ? raw : (raw?.toString?.() ?? "");
    if (!template) continue;
    templates.add(template);
    entries.set(template, {
      name: typeof r?.name === "string" ? r.name : regName,
      title: typeof r?.title === "string" ? r.title : undefined,
      mime_type: typeof r?.metadata?.mimeType === "string" ? r.metadata.mimeType : undefined,
    });
    if (template.includes("://")) schemes.add(template.split("://")[0].toLowerCase());
  }
  // Catalog and declared schemes are known even when the registration is
  // missing, so an absent URI referenced by a prompt still reads as a reference.
  for (const { template } of REQ022_URI_CATALOG) {
    if (template.includes("://")) schemes.add(template.split("://")[0].toLowerCase());
  }
  for (const slug of rulesets.installedSlugs()) {
    for (const d of rulesets.resourceDeclarations(slug)) {
      if (typeof d?.uri === "string" && d.uri.includes("://")) schemes.add(d.uri.split("://")[0].toLowerCase());
    }
  }
  return { entries, templates, schemes };
}

// REQ-139 — every drawn URI with its live presence: the REQ-022 catalog, the
// installed packages' declared resources, and the live registrations. Ordered
// catalog-first, then lexicographic. `presence` is derived from the live maps
// only; no state survives a call.
function resourceURIReport(): Array<{ uri: string; title: string; presence: "present" | "absent"; name?: string; mime_type?: string }> {
  const live = liveResourceIndex();
  const drawn = new Map<string, string>();
  for (const { template, title } of REQ022_URI_CATALOG) drawn.set(template, title);
  for (const slug of rulesets.installedSlugs()) {
    for (const d of rulesets.resourceDeclarations(slug)) {
      const name = typeof d?.name === "string" ? d.name.trim() : "";
      const uri = typeof d?.uri === "string" && d.uri ? d.uri : (name ? `ruleset://${slug}/${name}` : "");
      if (!uri || drawn.has(uri)) continue;
      drawn.set(uri, typeof d?.title === "string" && d.title ? d.title : uri);
    }
  }
  for (const [uri, entry] of live.entries) {
    if (!drawn.has(uri)) drawn.set(uri, entry.title ?? uri);
  }
  const catalogOrder = REQ022_URI_CATALOG.map(({ template }) => template);
  const ordered = [
    ...catalogOrder.filter((uri) => drawn.has(uri)),
    ...[...drawn.keys()].filter((uri) => !catalogOrder.includes(uri)).sort(),
  ];
  return ordered.map((uri) => {
    let entry = live.entries.get(uri);
    // A catalog template is present when a live registration matches its
    // pattern: `guidance://{badge}/anti-slop` is served by the concrete
    // `guidance://player/anti-slop` and `guidance://game_master/anti-slop`.
    if (!entry && uri.includes("{")) {
      const re = templateMatcher(uri);
      for (const [liveUri, liveEntry] of live.entries) {
        if (re.test(liveUri)) { entry = liveEntry; break; }
      }
    }
    const title = drawn.get(uri) ?? entry?.title ?? uri;
    if (!entry) return { uri, title, presence: "absent" as const };
    return {
      uri,
      title,
      presence: "present" as const,
      name: entry.name,
      ...(entry.mime_type ? { mime_type: entry.mime_type } : {}),
    };
  });
}

// The active Novel's user-authored strings. A candidate reference that occurs
// inside this text is Novel data (a name, a description, a journal entry), not
// a prompt reference.
function userAuthoredText(): string {
  const parts: string[] = [];
  const push = (v: unknown): void => {
    if (typeof v === "string" && v.trim() !== "") parts.push(v);
  };
  for (const [, n] of state.novels) {
    push(n.name);
    push(n.description);
  }
  const novel = state.activeNovel;
  if (novel) {
    push(novel.name);
    push(novel.description);
    push(novel.scene_location);
    push(novel.scene_description);
    for (const e of novel.entities.values()) { push(e.name); push((e as any).description); }
    for (const n of novel.npcs.values()) { push(n.name); push((n as any).description); push((n as any).location); }
    for (const r of novel.world.rooms.values()) { push(r.name); push((r as any).description); }
    for (const t of novel.world.things.values()) { push(t.name); push((t as any).description); }
    for (const [key, l] of novel.lore) { push(key); push((l as any).content); }
    for (const s of novel.story_journal ?? []) push(s.entry);
    const notes: any = (novel as any).notes;
    if (notes && typeof notes.values === "function") for (const v of notes.values()) push(v);
    const gm: any = novel.gm_context ?? {};
    for (const key of ["current_scene", "immediate_situation", "pending_player_action", "short_term_plans", "long_term_plans", "player_goals"]) {
      push(gm[key]);
    }
  }
  for (const r of state.roster.values()) push(r.name);
  return parts.join("\n");
}

function templateMatcher(template: string): RegExp {
  const escaped = template.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`^${escaped.replace(/\\\{[^}]*\\\}/g, "[^/]+")}$`);
}

// REQ-138a — tool or resource names in a prompt that no live registration
// carries. Registered-but-hidden REQ-581 tombstones count as present.
function staleReferencesFor(text: string, live: LiveResourceIndex, userText: string): string[] {
  if (!text) return [];
  const registered = new Set(Object.keys(registeredToolMap()));
  const stale = new Set<string>();
  for (const match of text.matchAll(TOOL_REFERENCE)) {
    const token = match[0];
    if (registered.has(token) || userText.includes(token)) continue;
    stale.add(token);
  }
  const matchers = [...live.templates].map((template) => templateMatcher(template));
  for (const match of text.matchAll(URI_REFERENCE)) {
    const token = match[0].replace(/[.,;:]+$/, "");
    const scheme = token.includes("://") ? token.split("://")[0].toLowerCase() : "";
    if (!scheme || !live.schemes.has(scheme)) continue;
    if (live.entries.has(token) || matchers.some((re) => re.test(token))) continue;
    if (userText.includes(token)) continue;
    stale.add(token);
  }
  return [...stale].sort();
}

function buildSpecHealth(): Record<string, unknown> {
  const novel = state.activeNovel;
  const badge = getBadge();
  const isGM = badge === "game_master" || badge === "none";
  const entities = novel ? novel.entities.size : 0;
  const npcs = novel ? novel.npcs.size : 0;
  const loreCount = novel ? novel.lore.size : 0;
  const countdowns = novel ? novel.countdowns.size : 0;
  const rooms = novel ? novel.world.rooms.size : 0;
  const things = novel ? novel.world.things.size : 0;
  const hiddenTools = hiddenAliasNames(surfaceRegistry());
  const visibleToolCount = toolRegistry.names()
    .filter((name) => !hiddenTools.has(name) && packageToolVisible(name)).length;
  const promptCount = ((server as any)._registeredPrompts ? Object.keys((server as any)._registeredPrompts).length : 0) + packagePrompts.size;
  // REQ-139 — one report drives both the presence list and the count, so the
  // payload cannot disagree with itself.
  const resourceReport = resourceURIReport();
  const resourceCount = resourceReport.filter((entry) => entry.presence === "present").length;
  // REQ-383a/REQ-383b — per-ruleset health plus the `combined` summary. A
  // Player badge sees only the active Novel's ruleset section (or none), while
  // `combined` stays visible to every badge.
  const rulesetHealth = (() => {
    const sections = buildRulesetHealthSections();
    const combined = {
      tool_count: visibleToolCount,
      resource_count: resourceCount,
      prompt_count: promptCount,
      active_novels: state.novels.size,
      ruleset_prefix_map: rulesets.prefixMap(),
    };
    const visible = isGM
      ? sections
      : (novel?.ruleset && sections[novel.ruleset] ? { [novel.ruleset]: sections[novel.ruleset] } : {});
    return { ...visible, combined };
  })();

  const prompts: [string, any][] = (server as any)._registeredPrompts ? Object.entries((server as any)._registeredPrompts) : [];
  const promptBudget = briefingBudget();
  // REQ-138a — both texts come from the one renderer call: `served` measures
  // the budget the client receives, `source` is scanned for stale references.
  const liveResources = liveResourceIndex();
  const userText = userAuthoredText();
  const prompt_health = [
    ...prompts.map(([registeredName, p]: [string, any]) => {
      const name = typeof p?.name === "string" ? p.name : registeredName;
      const rendered = renderHostPromptText(name);
      const source = rendered?.source ?? "";
      const served = rendered?.served ?? "";
      return {
        name,
        present: true,
        presence: "present" as const,
        length: served.length,
        budget: promptBudget,
        within: served.length <= promptBudget,
        stale_references: staleReferencesFor(source, liveResources, userText),
      };
    }),
    ...packagePromptList().map((p) => {
      const entry = packagePrompts.get(p.name)!;
      const length = entry.prompt.text.length;
      return {
        name: p.name,
        present: true,
        presence: "present" as const,
        length,
        budget: promptBudget,
        within: length <= promptBudget,
        stale_references: staleReferencesFor(entry.prompt.text, liveResources, ""),
        source: entry.slug,
      };
    }),
  ];

  const synthesisCounts = synthesisModuleCounts();
  const synthesis_active = state.enriched;

  // REQ-129c / REQ-097a1 — per-group count/max/overflow, health warnings, and
  // the `healthy` flag.
  const caps = groupCaps();
  const groupCount = (g: string): number => {
    switch (g) {
      case "npcs": return npcs;
      case "lore": return loreCount;
      case "countdowns": return countdowns;
      case "synthesis": return novel ? Object.values(novel.synthesis_activated ?? {}).reduce<number>((a, b) => a + (Array.isArray(b) ? b.length : 0), 0) : 0;
      case "story": return novel ? novel.story_journal.length : 0;
      case "entities": return entities;
      case "roster": return state.roster.size;
      case "snapshots": return novel ? Math.max(0, ...Object.values(novel.undo_stacks ?? {}).map((s) => s.length)) : 0;
      default: return 0;
    }
  };
  const cardinality: Record<string, { count: number; max: number; overflow: boolean }> = {};
  for (const [g, cap] of Object.entries(caps)) {
    const count = groupCount(g);
    cardinality[g] = { count, max: cap.max, overflow: cap.max > 0 && count >= cap.max };
  }
  const storyChars = novel ? novel.story_journal.reduce((n, s) => n + (s.entry?.length ?? 0), 0) : 0;
  const snapshotDepthUsed = groupCount("snapshots");
  const novelFilePath = novel ? path.join(DATA_DIR, "novels", `${novel.slug}.json`) : null;
  let fileSize = 0;
  try { if (novelFilePath) fileSize = fs.statSync(novelFilePath).size; } catch { /* file may not exist before the first write */ }
  // REQ-097a1 — activated Tier 1 keys that no longer resolve against the build.
  const synthesis_gap_count = (() => {
    if (!novel) return 0;
    let gaps = 0;
    for (const [module, keys] of Object.entries(novel.synthesis_activated ?? {})) {
      if (!Array.isArray(keys)) continue;
      const available = new Set(moduleItemKeys(module));
      for (const k of keys) if (!available.has(k)) gaps++;
    }
    return gaps;
  })();
  const health_warnings: string[] = [];
  for (const g of ["npcs", "lore", "snapshots", "entities", "countdowns", "synthesis", "story", "roster"]) {
    if (cardinality[g].overflow) health_warnings.push(`${g} at maximum (${cardinality[g].count}/${cardinality[g].max}).`);
  }
  if (caps.entities.max > 0 && entities > caps.entities.max * 0.8 && !cardinality.entities.overflow) {
    health_warnings.push(`entities above 80% of maximum (${entities}/${caps.entities.max}).`);
  }
  if (fileSize > 4 * 1024 * 1024) health_warnings.push(`Novel file size ${fileSize} bytes exceeds the 4 MB ceiling.`);
  if (novel && fileSize === 0) health_warnings.push("Novel file size is zero after write (durability failure).");
  // REQ-233b1 — a filled faction clock is surfaced as a [WARNING]; the notice
  // list is session-scoped and GM-only (it names a goal).
  if (isGM && novel) {
    for (const notice of factionFillNotices.get(novel.slug) ?? []) health_warnings.push(notice);
  }
  const healthy = health_warnings.length === 0;

  // REQ-558d — confidence reflects installed ruleset content even with no active
  // Novel: aggregate each installed package's index confidence by file and
  // category, read without hydrating (REQ-390b). Falls back to the ruleset-free
  // placeholder only when nothing is installed.
  const rulesetConfidence = (() => {
    const slugs = rulesets.installedSlugs();
    if (slugs.length === 0) return { overall: "N/A — ruleset-free", per_file: {}, per_category: {} };
    const perFile: Record<string, Record<string, number>> = {};
    const perCategory: Record<string, Record<string, number>> = {};
    const totals: Record<string, number> = {};
    let entries = 0;
    for (const s of slugs) {
      const index = rulesets.indexForReport(s);
      for (const e of index) {
        const c = String((e as any).confidence ?? "UNKNOWN").toUpperCase();
        entries++;
        totals[c] = (totals[c] ?? 0) + 1;
        const f = (e as any).source_file ?? "(unknown)";
        perFile[f] = perFile[f] ?? {};
        perFile[f][c] = (perFile[f][c] ?? 0) + 1;
        const cat = (e as any).category ?? "uncategorized";
        perCategory[cat] = perCategory[cat] ?? {};
        perCategory[cat][c] = (perCategory[cat][c] ?? 0) + 1;
      }
    }
    if (entries === 0) return { overall: "N/A — ruleset-free", per_file: {}, per_category: {} };
    const high = totals["HIGH"] ?? 0;
    const overall = high / entries >= 0.9 ? "HIGH" : high / entries >= 0.5 ? "MEDIUM" : "LOW";
    return { overall, entries, totals, per_file: perFile, per_category: perCategory };
  })();

  const health: Record<string, unknown> = {
    // REQ-106 — spec repository URL (informational; identical for both badges).
    spec_repo_url: specRepoUrl(),
    spec_version: state.buildFingerprint.specVersion,
    spec_hash: state.storedFingerprint?.specHash ?? state.buildFingerprint.specHash,
    spec_hash_current: state.specHashCurrent,
    source_hash: state.buildFingerprint.sourceHash,
    build_drift: state.buildDrift,
    ruleset_hash: rulesets.installedSlugs().length > 0 ? rulesets.installedSlugs().join(",") : "ruleset-free",
    ruleset_guidance: rulesets.installedSlugs().length > 0
      ? `Installed: ${rulesets.installedSlugs().join(", ")}.`
      : "No rulesets installed — install a package with manage_artifact (action: install, kind: ruleset); the base server is playable without one.",
    active_ruleset: isGM ? (novel?.ruleset ?? null) : undefined,
    rulesets_installed: rulesets.installedSlugs().length,
    rulesets_hydrated: rulesets.installedSlugs().filter((s) => rulesets.isHydrated(s)).length,
    // REQ-390b — aggregate installed index bytes, read without hydrating.
    ruleset_index_bytes: rulesets.installedIndexBytes(),
    // REQ-383a/REQ-383b — per-ruleset health keyed by slug plus `combined`.
    ruleset_health: rulesetHealth,
    ruleset_prefix_map: isGM ? rulesets.prefixMap() : undefined,
    // REQ-420 — incompatible packages, held inactive (REQ-393);
    // REQ-430 — non-conformant ruleset-derived tools, flagged (never blocked).
    ruleset_package_alerts: isGM
      ? [
          ...rulesets.incompatibleSlugs(),
          // REQ-389b — packages that failed to load (e.g. content-hash mismatch),
          // recorded at startup so the rejection is surfaced in spec_health.
          ...rulesetLoadErrors.map((e) => ({ slug: e.slug, reason: `[load-rejected] ${e.reason}` })),
          ...rulesets.loadFailuresFor(),
          ...rulesets.toolQualityAlerts().map((a) => ({ slug: a.slug, reason: `[tool-quality] ${a.tool}: ${a.defects.join("; ")}` })),
        ]
      : undefined,
    // REQ-430 — conformant vs non-conformant ruleset-derived tool counts.
    ruleset_tool_quality: isGM ? rulesets.toolQualityCounts() : undefined,
    // REQ-579 — packages whose tools predate the surface contract; the Update
    // workflow rebuilds those with a committed emitter and defers the rest.
    legacy_package_rebuilds: isGM
      ? rulesets.toolQualityAlerts()
          .filter((a) => a.defects.some((d) => d.includes("surface group") || d.includes("surface phases")))
          .map((a) => ({ slug: a.slug, tool: a.tool, reason: "missing surface declaration" }))
      : undefined,
    // REQ-450 — deterministic host-tool quality signals (report-only).
    host_tool_quality: hostToolQuality(),
    // REQ-552/553/554/555 — deterministic TDQS conformance report over the live
    // registered surface (host and ruleset-derived).
    tdqs: tdqsHealth(),
    // REQ-372 — imported supplementary rulesets and any missing-source gap.
    supplementary_rulesets: isGM ? (novel?.supplementary_rulesets ?? []).map((s) => ({ slug: s.slug, source: s.source, hash: s.hash, wisdom_items: s.wisdom.length })) : undefined,
    supplementary_gap: isGM
      ? (novel?.supplementary_rulesets ?? [])
          .filter((s) => s.source !== "(inline)" && !fs.existsSync(s.source))
          .map((s) => ({ slug: s.slug, source: s.source, reason: "[supplementary-gap] source missing" }))
      : undefined,
    // REQ-423 — [data-stale] artifacts, advisory (never block loading);
    // REQ-397 — where persistent state lives and whether a git operation on the
    // surrounding work tree can delete it. GM-only, like the rest of health.
    state_location: isGM
      ? {
          path: STATE_LOCATION.dir,
          source: STATE_LOCATION.source,
          in_git_work_tree: STATE_LOCATION.inGitWorkTree,
          work_tree_root: STATE_LOCATION.workTreeRoot,
          warning: STATE_IN_TREE_WARNING,
        }
      : undefined,
    // REQ-652 — structured detail names stored/current and the remedy;
    // REQ-001a — [WARNING] enumeration of corrupted Novels (corruptData).
    data_health: isGM
      ? {
          data_format: state.dataFormat,
          stale: Object.fromEntries(state.staleData),
          stale_detail: Object.fromEntries(
            [...state.staleDetail].map(([name, detail]) => [
              name,
              { ...detail, remedy: "Run `holonovel update` to re-stamp this artifact." },
            ]),
          ),
          stale_count: state.staleData.size,
          remedy: state.staleData.size > 0 ? "Run `holonovel update` to re-stamp stale artifacts." : null,
          corrupted: Object.fromEntries(state.corruptData),
          // REQ-092c/REQ-238 — operator recovery detail: the primary path plus
          // every backup-chain path for each corrupt Novel.
          corrupted_detail: Object.fromEntries(state.corruptDetail),
          // REQ-092g — Novels written by a newer server, keyed by slug.
          format_future: Object.fromEntries(state.formatFuture),
          // Data-level markers (a Novel named here need not be the active one);
          // play-state markers live in state_health.markers.
          markers: [
            ...(state.corruptData.size > 0 ? ["[corrupted-novel]"] : []),
            ...(state.formatFuture.size > 0 ? ["[format-future]"] : []),
          ],
          compression_mismatch: Object.fromEntries(state.compressionMismatch),
        }
      : undefined,
    // REQ-402/REQ-403a/REQ-406 — persistence guardrail markers. The fields
    // expose narration timing and an audit gap, so they are GM-gated like
    // data_health (REQ-097c). Markers are observational (REQ-402).
    state_health: isGM ? {
      markers: [
        ...(novel && state.stateDriftActive(novel) ? ["[state-drift]"] : []),
        ...(novel && (novel.session_no_mutation_windows?.length ?? 0) > 0 ? ["[session-no-mutations]"] : []),
        ...(novel?.state_regression ? ["[state-regression]"] : []),
      ],
      drift_active: novel ? state.stateDriftActive(novel) : false,
      drift_since: novel?.gm_context?.saved_at ?? null,
      session_no_mutation_windows: novel?.session_no_mutation_windows ?? [],
      regression: novel?.state_regression ?? null,
    } : undefined,
    // REQ-565, REQ-566 — bundled starter Novel seed outcome (informational).
    starter: state.starterStatus,
    build_timestamp: state.buildFingerprint.buildTimestamp,
    // REQ-515–REQ-521 — the event-log cursor this health/briefing reflects and
    // derived-surface freshness (read-only advisory).
    briefing_consistency: briefingConsistency(),
    tool_count: visibleToolCount,
    prompt_count: promptCount,
    package_prompts: { installed: packagePrompts.size, errors: packagePromptErrors },
    resource_count: resourceCount,
    resource_uris: resourceReport, // REQ-139 — presence and count from one live-map report.
    prompt_health, // REQ-138 — per-prompt presence, length, budget, stale refs.
    // REQ-425d — the output format catalog (universal + surface sets + any
    // ruleset-declared formats) and whether the MCP Apps extension (REQ-426c)
    // is negotiated by the current client.
    output_formats: {
      universal: [...UNIVERSAL_FORMATS],
      statblock: [...STATBLOCK_FORMATS],
      session: [...SESSION_FORMATS],
      interchange: [...INTERCHANGE_FORMATS],
      declared: [...declaredFormats],
    },
    mcp_apps: { negotiated: appsNegotiated() },
    confidence: rulesetConfidence,
    indexed_counts: {
      // REQ-389b — a package that fails hydration (e.g. content-hash mismatch)
      // contributes nothing and must not crash the health report; its rejection
      // is surfaced by `manage_ruleset (action: list)`.
      anchors: rulesets.installedSlugs().reduce((n, s) => n + rulesets.indexForReport(s).length, 0),
      concepts: 0, entity_types: 0, actions: 0,
      tables: 0, procedures: 0, guidance_items: 0,
    },
    must_action_coverage: "100% (infrastructure only)",
    pending_sections: 0,
    defect_count: 0,
    world_model: { rooms, things },
    // REQ-043d — Novel-lifetime combat round counter (cumulative; combat start
    // and end do not reset it).
    total_combat_rounds: novel?.metadata.total_combat_rounds ?? 0,
    novels_available: [...state.novels.keys()].length,
    // REQ-334 — archived Novels surface with slug + archive timestamp.
    archived_novels: isGM ? state.archivedNovels() : undefined,
    server_notes: state.serverNotes.size,
    // REQ-321l — the codex count is partitioned by kind.
    codex: isGM
      ? (() => {
        const by_kind: Record<string, number> = {};
        for (const entry of state.codex.values()) {
          const kind = String((entry as any).kind ?? "unknown");
          by_kind[kind] = (by_kind[kind] ?? 0) + 1;
        }
        return { total: state.codex.size, by_kind };
      })()
      : undefined,
    // REQ-332 — codex provenance register for the active Novel.
    codex_sources: isGM && novel ? (novel.codex_sources ?? []) : undefined,
    // REQ-332b — a source entry modified after the import makes the Novel
    // artifact stale.
    codex_stale: isGM && novel
      ? (novel.codex_sources ?? [])
        .filter((cs: any) => {
          const entry: any = state.codex.get(cs.id);
          return entry && String(entry.codex_modified_at ?? "") > String(cs.codex_modified_at ?? "");
        })
        .map((cs: any) => ({
          artifact: cs.id,
          kind: cs.kind,
          codex_id: cs.id,
          imported_at: cs.imported_at,
          codex_modified_at: cs.codex_modified_at,
          flag: "[codex-stale]",
        }))
      : undefined,
    // REQ-233a2 — a fourth deferral escalates to a warning; derived from the
    // persisted change list, never a second counter.
    world_reactivity_warnings: isGM && novel
      ? novel.world_in_motion
        .filter((c) => c.defer_count >= 4)
        .map((c) => ({ id: c.id, summary: c.summary, deferrals: c.defer_count, flag: "[WARNING]" }))
      : undefined,
    // REQ-170 — adventure discovery surface: indexed adventure slugs + content
    // hashes (informational; adventure modules ship with the build).
    // REQ-170 — indexed adventure slugs with their build-time content hashes;
    // the Player badge sees only the player-visible rows.
    indexed_adventures: (() => {
      const out: Record<string, { title: string; content_hash: string; player_visible: boolean; source: string; malformed: AdventureIndexEntry["malformed"] }> = {};
      for (const [slug, entry] of Object.entries(adventureIndexSnapshot())) {
        if (!isGM && !entry.player_visible) continue;
        out[slug] = { title: entry.title, content_hash: entry.content_hash, player_visible: entry.player_visible, source: entry.source, malformed: entry.malformed };
      }
      return out;
    })(),
    // REQ-172 — drift is a diagnostic, never a startup interlock.
    adventure_drift: adventureDriftCache,
    // REQ-292b — adventure catalog count.
    adventure_catalog_count: countAdventureModules(),
    // REQ-620 — host-level artifact registry counts per kind.
    artifacts_registered: registryCounts(artifactRegistry()),
    // REQ-325a — counts by constraint type and mechanic source (GM only).
    constraint_override_counts: isGM ? (() => {
      const list = novel?.constraint_overrides ?? [];
      const by_type: Record<string, number> = {};
      const by_source: Record<string, number> = {};
      for (const o of list as any[]) {
        const t = String(o.type ?? "untyped");
        const s = String(o.source ?? "unsourced");
        by_type[t] = (by_type[t] ?? 0) + 1;
        by_source[s] = (by_source[s] ?? 0) + 1;
      }
      return { total: list.length, by_type, by_source };
    })() : undefined,
    active_novel: novel?.slug ?? null,
    // REQ-294 — genre declaration surfaced in spec_health when set.
    active_genre: novel?.genre && novel.genre.length > 0 ? novel.genre : undefined,
    active_badge: novel?.badge ?? null,
    autonomy: isGM ? (novel?.autonomy ?? null) : undefined,
    creativity_mapping: {
      predictable: "least surprise — stick to expected outcomes",
      standard: "balanced variation — the default",
      chaotic: "most surprise — dramatic twists",
      reported: true,
    },
    entities, npcs, lore_entries: loreCount, countdowns,
    // REQ-097a1 / REQ-129c — Novel health: counts, maxima, overflow, warnings.
    healthy,
    health_warnings,
    synthesis_gap_count,
    // REQ-083a — rendered lore budget accounting for the briefing lore section.
    lore_budget: recordedLoreBudget ?? { max_tokens: state.maxLoreTokens, used_tokens: 0, omitted_entries: 0 },
    story_journal_entries: novel ? novel.story_journal.length : 0,
    story_journal_chars: storyChars,
    snapshot_depth: snapshotDepthUsed,
    file_size: fileSize,
    cardinality,
    // REQ-241c — checkpoint count and storage size.
    checkpoint_count: novel ? novel.checkpoints.length : 0,
    checkpoint_bytes: novel ? JSON.stringify(novel.checkpoints).length : 0,
    perception_ledger_count: novel ? novel.perception_ledger.length : 0,
    // REQ-627 — subjective-memory count, Game Master only.
    subjective_memory_count: isGM && novel ? (novel.subjective_memory ?? []).length : undefined,
    compression_ladder: novel ? { arc: novel.compression_ladder?.arc?.length ?? 0, campaign: !!novel.compression_ladder?.campaign } : undefined,
    social_cast: isGM && novel ? { strategy: novel.social_cast.strategy, muted: novel.social_cast.muted, spoken: novel.social_cast.spoken.length } : undefined,
    storage_caps: novel ? {
      event_log: storageCapStatus(novel.event_log.length, process.env.TTRPG_EVENT_LOG_MAX_ENTRIES, 50000),
      perception_ledger: storageCapStatus(novel.perception_ledger.length, process.env.TTRPG_PERCEPTION_MAX_ENTRIES, 20000),
      subjective_memory: storageCapStatus((novel.subjective_memory ?? []).length, process.env.TTRPG_SUBJECTIVE_MEMORY_MAX_ENTRIES, 20000),
      checkpoints: storageCapStatus(novel.checkpoints.length, process.env.TTRPG_MAX_CHECKPOINTS, 25),
    } : undefined,
    // REQ-589 — GM-only ruling-ledger counts.
    ruling_ledger_count: isGM && novel ? (novel.ruling_ledger ?? []).length : undefined,
    ruling_ledger_reverted_count: isGM && novel ? (novel.ruling_ledger ?? []).filter((e) => e.reverted).length : undefined,
    // REQ-311f — NPC memory count across all NPCs in the active Novel.
    npc_memory_count: novel ? [...novel.npcs.values()].reduce((n, npc) => n + (npc.memory ? Object.keys(npc.memory.contacts ?? {}).length + (npc.memory.witnessed_events?.length ?? 0) : 0), 0) : 0,
    // REQ-224b / REQ-193a — pending workflow staleness surfaced to operators.
    pending_workflow: isGM ? (novel?.pending_workflow ? { decision: novel.pending_workflow.decision, connections: novel.pending_staleness_counter, threshold: parseInt(process.env.TTRPG_WORKFLOW_STALENESS_CONNECTIONS ?? "5", 10) } : null) : undefined,
    pending_workflow_warning: isGM && novel?.pending_workflow && novel.pending_staleness_counter >= 3
      ? { decision: novel.pending_workflow.decision, connections: novel.pending_staleness_counter }
      : undefined,
    // REQ-237 — session segmentation: per-session metrics from [session-boundary]
    // markers, badge-filtered (Player sees timespans without session ids).
    sessions: novel ? (isGM ? novel.metadata.sessions : novel.metadata.sessions.map((s) => ({ session_id: undefined, entry_count: s.entry_count, timespan_start: s.timespan_start, timespan_end: s.timespan_end }))) : undefined,
    synthesis_active,
    synthesis_status: { modules: synthesisCounts, last_run: state.wisdomManifest?.collected_at ?? null },
    synthesis_health: {
      synthesis_active,
      module_counts: synthesisCounts,
      stale_count: state.getWisdomHealth().stale_count,
      activated_count: novel ? Object.values(novel.synthesis_activated ?? {}).reduce<number>((a, b) => a + (Array.isArray(b) ? b.length : 0), 0) : 0,
      // §11.3 idempotence — the synthesis fingerprint, not the spec hash.
      fingerprint: state.wisdomManifest?._fingerprint ?? "",
      // REQ-129c/§11.3 budgets — internal item count against the effective cap,
      // with the per-module breakdown the overflow report needs.
      caps: synthesisCapStatus(state.wisdomManifest),
      empty: state.wisdomManifest?._empty ?? {},
    },
    // REQ-388a–d — behavioral-config coverage, available to every badge and
    // reported from server-level defaults when no Novel is active.
    holodeck_config: buildHolodeckConfig(),
    audit_chain: novel ? state.verifyAuditChain(novel) : null, // REQ-169
    safety_protocols: { // REQ-269 — safety protocol status per property.
      state_loss: "online",
      badge_boundary: "online",
      data_corruption: "online",
      unrecoverable_crash: isGM ? "unverified" : undefined,
    },
    // REQ-408 (amended), REQ-410, REQ-411, REQ-409 — token/efficiency contracts.
    // Per-action ceiling (REQ-413): action-discriminator tools are evaluated on
    // their required-per-action parameters, not the union of optional fields.
    parameter_ceiling: PARAMETER_CEILING,
    parameter_ceiling_exceeded: (() => {
      const meta = cachedMetadata();
      for (const [name, count] of Object.entries(meta.toolParameterCounts)) {
        const effective = meta.actionToolNames.has(name) ? (meta.toolRequiredParamCounts[name] ?? count) : count;
        if (effective > PARAMETER_CEILING) return true;
      }
      return false;
    })(),
    tool_parameter_counts: cachedMetadata().toolParameterCounts,
    tool_required_param_counts: cachedMetadata().toolRequiredParamCounts,
    tools_list_bytes: measuredSurface().active.bytes,
    // REQ-567, REQ-568, REQ-569, REQ-570, REQ-571, REQ-572, REQ-580 — Tool Surface Contract report, derived from the
    // committed registry and the live registrations at call time.
    tool_surface: (() => {
      const measured = measuredSurface();
      const ledger = contextLedgerReport();
      return {
        ...buildSurfaceReport({
          registry: surfaceRegistry(),
          live: liveSurfaceActions(),
          profile: surfaceProfile(),
          catalogBytes: measured.active.bytes,
          catalogProfiles: {
            full: measured.full,
            standard: measured.standard,
            small: measured.small,
          },
          overrides: surfaceOverrideCount,
          budgets: { standard: Math.ceil(measured.full.tokens * 0.9), small: Math.ceil(measured.full.tokens * 0.1) },
        }),
        // REQ-587, REQ-607 — the serialized default catalog is the cacheable
        // prefix; the ledger adds its hash and token ratio. No provider
        // cache-hit rate is claimed.
        cacheable_prefix_bytes: measured.active.bytes,
        cacheable_prefix_sha256: ledger.stable_prefix.sha256,
        prefix_ratio: ledger.stable_prefix.ratio,
        ledger_total_tokens: ledger.total_tokens,
      };
    })(),
    // REQ-583 — observed selection signals; absent when no package is loaded.
    ...(rulesets.installedSlugs().length > 0 ? { selection_telemetry: { ...selectionTelemetry } } : {}),
    // REQ-588 — search result budget and the last call's returned/suppressed counts.
    search_budget: { ...searchBudgetStats, max_tokens: searchMaxTokens() },
    // REQ-586 — installed end-to-end performance record, when present.
    ...(performanceRecord ? { performance_record: performanceRecord } : {}),
    cache_coverage: { hits: cacheHits, misses: cacheMisses },
    enumeration_verbosity: enumerationVerbosity,
    // REQ-253 — active tool-output verbosity mode; REQ-197c — detail level.
    verbosity_mode: detailLevel === "terse" ? "terse" : "normal",
    detail_level: detailLevel,
    // REQ-447 — audit-log growth cap utilization.
    audit_at_capacity: novel ? state.auditLogAtCapacity(novel) : false,
    audit_log_entries: novel ? novel.audit_log.length : 0,
    // REQ-283 — parser verb coverage tiers: core (base vocabulary), standard
    // (IF-community), extended (ruleset-derived). Advisory completeness signal.
    parser_verb_coverage: (() => {
      const tiers = verbCatalog(novel?.world);
      return {
        core: tiers.core.length,
        core_available: tiers.core.filter((v) => v.available).length,
        standard: tiers.standard.length,
        standard_available: tiers.standard.filter((v) => v.available).length,
        extended: tiers.extended.length,
      };
    })(),
    // REQ-197 — effective room description mode (session-scoped; the detail
    // level overrides the player's chosen mode).
    description_mode: effectiveRoomDescriptionMode(),
    // REQ-185 section token vocabulary + REQ-186 discoverability: valid tokens with
    // their REQ-109 groups and whether the group currently has runtime content.
    section_tokens: BRIEFING_TOKENS.map((row) => ({
      token: row.token,
      group: row.group,
      has_content: novel ? row.hasContent(novel) : false,
    })),
    // REQ-263 — synthesis auto-trigger threshold (visible).
    synthesis_auto_trigger: process.env.TTRPG_SYNTHESIS_AUTO_TRIGGER ?? "off",
    // REQ-266 — last synthesis run timestamp.
    synthesis_last_run: state.wisdomManifest?.collected_at ?? null,
    campaign_memory: novel ? {
      npcs: (novel.campaign_memory ?? []).filter((f) => f.category === "npcs").length,
      threads: (novel.campaign_memory ?? []).filter((f) => f.category === "threads").length,
      locations: (novel.campaign_memory ?? []).filter((f) => f.category === "locations").length,
      total: (novel.campaign_memory ?? []).length,
    } : { npcs: 0, threads: 0, locations: 0, total: 0 },
    // REQ-312d1 — narration validation gate status and rejection count.
    narration_validation: narrationValidationOn() ? "on" : "off",
    narration_rejection_count: narrationRejectionCount,
    // REQ-417 — non-blocking startup probes: startup completes without awaiting
    // slow probes; probe state reported as pending then completed.
    startup_probes: { ruleset_scan: "completed", wisdom: "completed" }, // REQ-417
    // REQ-413 — action-discriminator tools; REQ-414 — nested-form input count;
    // REQ-415 — active catalog verbosity (summary default, detail on request).
    catalog_verbosity: enumerationVerbosity,
    ...schemaSurfaceMetrics(),
    token_footprint: {
      tools_list_bytes: measuredSurface().active.bytes,
      prompt_scaffold_bytes: cachedMetadata().promptBytes,
    },
    // REQ-346b — narrative coherence disposition (G7). `implemented`, `total`,
    // `disposition`, and `reqs` keep their shape; `missing` and `attestation`
    // are additive, so the G7 evidence record and the coverage register can opt
    // into the detail without a schema break.
    narrative_coherence: narrativeCoherenceReport(),
  };

  const fingerprintPath = path.join(DATA_DIR, "build-order-fingerprint.json");
  if (fs.existsSync(fingerprintPath)) {
    try {
      health.build_order = JSON.parse(fs.readFileSync(fingerprintPath, "utf-8"));
    } catch { /* ignore unreadable fingerprint */ }
  }

  return health;
}

