// Scene resources
server.registerResource("scene-current", "scene://current", { title: "Current Scene" }, async () => {
  const novel = state.activeNovel;
  if (!novel) return { contents: [{ uri: "scene://current", text: JSON.stringify({ error: "no active novel" }), mimeType: "application/json" }] };
  // REQ-326b — carry the resolved room identity when the scene location names
  // a world-model room, so consumers need not re-resolve it.
  const bare = (s: string) => s.toLowerCase().replace(/^the\s+/, "");
  const sceneRoom = novel.scene_location
    ? [...novel.world.rooms.values()].find((r) => r.name.toLowerCase() === novel.scene_location!.toLowerCase() || bare(r.name) === bare(novel.scene_location!))
      ?? [...novel.world.rooms.values()].find((r) => r.name.toLowerCase().includes(novel.scene_location!.toLowerCase()))
      ?? null
    : null;
  return { contents: [{ uri: "scene://current", text: JSON.stringify({ description: novel.scene_description, location: novel.scene_location, room_id: sceneRoom?.name.toLowerCase() ?? null, room_name: sceneRoom?.name ?? null, time_of_day: novel.scene_time_of_day, atmosphere: novel.scene_atmosphere, type: novel.scene_type }), mimeType: "application/json" }] };
});

server.registerResource("scene-history", "scene://history", { title: "Scene History" }, async () => {
  const novel = state.activeNovel;
  if (!novel) return { contents: [{ uri: "scene://history", text: "[]", mimeType: "application/json" }] };
  // REQ-032 — attendance snapshots are GM-only; strip them for other badges.
  const badge = getBadge();
  const filtered = badge === "game_master" || badge === "none"
    ? novel.scene_history
    : novel.scene_history.map(({ characters_present_ids: _presence, ...entry }) => entry);
  // REQ-076b2 — a configurable maximum of the most recent entries, with the
  // suppressed count and a [truncated] marker. The cap applies at read time
  // only; the audit log remains the unbounded record.
  const cap = (() => {
    const raw = Number(process.env.TTRPG_SCENE_HISTORY_MAX ?? 50);
    return Number.isFinite(raw) && raw > 0 ? Math.floor(raw) : 50;
  })();
  let history: any[] = filtered;
  if (filtered.length > cap) {
    const suppressed = filtered.length - cap;
    history = [{ suppressed, truncated: true, marker: "[truncated]" }, ...filtered.slice(-cap)];
  }
  return { contents: [{ uri: "scene://history", text: JSON.stringify(history), mimeType: "application/json" }] };
});

// Identity resource (REQ-476/REQ-480/REQ-481/REQ-643) — the compiled identity
// kernel for a roster character. Secret-perspective facets are excluded from
// the kernel; a Player badge reads only the active character, projected.
server.registerResource("identity-kernel", new ResourceTemplate("identity://{id}", { list: () => {
  const badge = getBadge();
  const novel = state.activeNovel;
  const active = novel?.active_entity_id;
  const ids = [...new Set([
    ...state.roster.keys(),
    ...(novel ? [...novel.entities.keys(), ...novel.npcs.keys()] : []),
  ])].filter((id) => badge !== "player" || id === active);
  return { resources: ids.map(id => ({ uri: `identity://${id}`, name: id })) };
} }), { title: "Identity Kernel" }, async (uri) => {
  const id = resourceKey(uri);
  const badge = getBadge();
  if (badge === "player" && id !== state.activeNovel?.active_entity_id) {
    return { contents: [{ uri: uri.href, text: JSON.stringify({ error: "FORBIDDEN", message: "Player badge reads only the active character's identity. Corrective action: set_badge to the Game Master badge to read others." }), mimeType: "application/json" }] };
  }
  const identity = identityFor(id);
  if (!identity) return { contents: [{ uri: uri.href, text: JSON.stringify({ error: "not found" }), mimeType: "application/json" }] };
  const kernel = compileKernel(identity);
  return { contents: [{ uri: uri.href, text: JSON.stringify(badge === "player" ? playerIdentityProjection(kernel) : kernel, null, 2), mimeType: "application/json" }] };
});

