// REQ-260/231/265 — single read-time resolver consulted by every synthesis
// surface: module toggle (REQ-231), per-item activation (REQ-260), and badge
// scope (REQ-265). This is the "effective view" the whole subsystem reads.
// §11.2 — `SYNTHESIS_MODULES` now lives beside the analysis that produces them
// (`core/synthesis.ts`) so the module list, the caps and the rules cannot drift.

// REQ-231b — modules default to enabled; only an explicit disable turns one off.
// REQ-266 — Novel-derived synthesis items: MEDIUM-confidence voice examples for
// entities/NPCs with an explicit personality voice or description, and one
// LOW-confidence theme item when the story journal is non-empty. Deterministic
// (sorted ids), additive only, and never touches mechanics (REQ-080).
// REQ-080g2/T288 — synthesis status appended to an adventure load response.
function adventureSynthesisLines(): string {
  const manifest: any = state.wisdomManifest;
  if (!manifest) return "";
  const tier1 = (list: any[]): number => (list ?? []).filter((i: any) => ["vendor", "ruleset"].includes(String(i?.tag ?? ""))).length;
  const inert = (list: any[]): number => (list ?? []).filter((i: any) => ["supplementary", "player"].includes(String(i?.tag ?? ""))).length;
  const active = tier1(manifest.voice_examples) + tier1(manifest.lore_templates);
  const inertCount = inert(manifest.voice_examples) + inert(manifest.lore_templates);
  const parts: string[] = [];
  if (active > 0) parts.push(`Synthesis: ${active} item(s) active for this adventure. Review at \`synthesis://status\`.`);
  if (inertCount > 0) parts.push(`Community synthesis items: ${inertCount} inert — activate with manage_synthesis (action: activate).`);
  return parts.length > 0 ? `\n\n${parts.join(" ")}` : "";
}

// §11.2/§11.3 — Novel-derived synthesis now lives in `core/synthesis.ts`
// (`synthesizeFromNovel`): all eight category rules, the per-pass and total
// caps, the fingerprint and the per-module hashes. This file only wires it to
// state, the Novel and the read surfaces.

function isModuleEnabled(module: string): boolean {
  return state.activeNovel?.synthesis_module_enabled?.[module] !== false;
}

// REQ-260/265 — an item is active when it is not explicitly deactivated and it
// either defaults active (Tier-1 ruleset/vendor, player-authored) or was
// explicitly activated (Tier-2 supplementary, inert by default).
function isWisdomItemActive(module: string, item: any): boolean {
  if (!isModuleEnabled(module)) return false;
  const key = String(item?.key ?? "");
  if (!key) return false;
  const novel = state.activeNovel;
  if ((novel?.synthesis_deactivated?.[module] ?? []).includes(key)) return false;
  // §11.3.4 — action patterns are gated by the Novel-scoped action-pattern
  // toggle (REQ-115), not per-item activation, so they default active here.
  if (module === "action_patterns") return true;
  const tag = String(item?.tag ?? "");
  if (tag === "vendor" || tag === "ruleset" || tag === "player") return true;
  return (novel?.synthesis_activated?.[module] ?? []).includes(key);
}

// Flattened, activation- and module-gated item view. `briefing_order` is a
// single object, not an array, and carries its own synthetic key.
function effectiveWisdomItems(module: string): any[] {
  const manifest: any = state.wisdomManifest;
  if (!manifest) return [];
  if (module === "briefing_order") {
    const bo: any = manifest.briefing_order;
    if (!bo) return [];
    return isWisdomItemActive(module, { ...bo, key: bo.key ?? "briefing-order", tag: bo.tag ?? "vendor" }) ? [bo] : [];
  }
  let items: any[];
  if (module === "adventure_advice") {
    const adv = manifest.adventure_advice ?? {};
    items = [...(adv.templates ?? []), ...(adv.scenario_starters ?? []), ...(adv.table_expansions ?? [])];
  } else {
    items = manifest[module] ?? [];
  }
  return (Array.isArray(items) ? items : []).filter((i) => isWisdomItemActive(module, i));
}

// Every addressable key in a module (manifest items plus player-authored items),
// used for bulk activation (REQ-260a) and for list/detail output.
function moduleItemKeys(module: string): string[] {
  const manifest: any = state.wisdomManifest;
  const novel = state.activeNovel;
  const keys: string[] = [];
  if (manifest) {
    if (module === "briefing_order") keys.push("briefing-order");
    else if (module === "adventure_advice") {
      const adv = manifest.adventure_advice ?? {};
      [...(adv.templates ?? []), ...(adv.scenario_starters ?? []), ...(adv.table_expansions ?? [])].forEach((i: any) => i?.key && keys.push(i.key));
    } else {
      (manifest[module] ?? []).forEach((i: any) => i?.key && keys.push(i.key));
    }
  }
  (novel?.player_synthesis?.[module] ?? []).forEach((i: any) => i?.key && keys.push(i.key));
  return keys;
}

// REQ-080h — every stored synthesis item carrying a claim, with the text its
// citation is verified against. Player-authored items are excluded: they cite
// nothing. Supplementary imports cite their ruleset slug.
function synthesisCitationItems(): Array<{ module: string; key: string | number; claim: string; item: any }> {
  const manifest: any = state.wisdomManifest;
  const out: Array<{ module: string; key: string | number; claim: string; item: any }> = [];
  const push = (module: string, key: string | number, claim: string, item: any): void => {
    out.push({ module, key: key ?? "", claim, item });
  };
  if (manifest) {
    (manifest.voice_examples ?? []).forEach((i: any) => push("voice_examples", i.key, i.content ?? "", i));
    (manifest.lore_templates ?? []).forEach((i: any) => push("lore_templates", i.key, i.content ?? "", i));
    (manifest.action_patterns ?? []).forEach((i: any) => push("action_patterns", i.key, i.intent ?? "", i));
    (manifest.supplementary_guidance ?? []).forEach((i: any) => push("supplementary_guidance", i.key, i.content ?? "", i));
    (manifest.narrative_voices ?? []).forEach((i: any) => push("narrative_voices", i.key, i.description ?? "", i));
    if (manifest.briefing_order) {
      push("briefing_order", "briefing-order", manifest.briefing_order.reason ?? "", manifest.briefing_order);
    }
    const adv = manifest.adventure_advice ?? {};
    [...(adv.templates ?? []), ...(adv.scenario_starters ?? []), ...(adv.table_expansions ?? [])]
      .forEach((i: any) => push("adventure_advice", i.key, i.content ?? "", i));
  }
  for (const s of state.activeNovel?.supplementary_rulesets ?? []) {
    for (const w of (s as any).wisdom ?? []) {
      push((w as any).module ?? "supplementary_guidance", (w as any).key, (w as any).content ?? "", { ...(w as any), source_url: (w as any).source_url ?? `supplementary://${(s as any).slug}` });
    }
  }
  return out;
}

function rulingConfidence(values: Array<string | undefined>): "HIGH" | "MEDIUM" | "LOW" {
  const rank: Record<string, number> = { HIGH: 3, MEDIUM: 2, LOW: 1 };
  let lowest = "HIGH";
  for (const v of values) {
    const key = String(v ?? "LOW").toUpperCase();
    const normalized = rank[key] ? key : "LOW";
    if ((rank[normalized] ?? 0) < (rank[lowest] ?? 0)) lowest = normalized;
  }
  return lowest as "HIGH" | "MEDIUM" | "LOW";
}

// REQ-589 — deterministic id: the smallest unused positive integer suffix.
function nextRulingId(entries: Array<{ id: string }>): string {
  const used = new Set<number>();
  for (const e of entries) {
    const m = /^ruling_(\d+)$/.exec(e.id);
    if (m) used.add(parseInt(m[1], 10));
  }
  let n = 1;
  while (used.has(n)) n++;
  return `ruling_${n}`;
}

function rulingCap(): number {
  return Math.max(0, parseInt(process.env.TTRPG_MAX_RULING_ENTRIES ?? "500", 10));
}

// REQ-265a — GM sees every item; Player/observer badges see non-GM-scoped items.
function badgeCanSeeWisdom(item: any): boolean {
  const badge = getBadge();
  if (badge === "game_master" || badge === "none") return true;
  return item?.badge_scope !== "game_master";
}

// REQ-022a/REQ-071a + §11.3 — badge guidance views that draw from the Novel's
// live synthesis state. `viewBadge` selects the view (the badge named by the
// URI); the caller's badge is a separate content filter (`canSeeGuidanceItem`),
// so a Player caller never receives a GM-scoped item through the GM view.
interface GuidanceItemBase {
  badge_scope?: string;
  provenance: string;
  confidence: "HIGH" | "MEDIUM" | "LOW";
}

interface GuidanceVoiceItem extends GuidanceItemBase {
  key: string;
  name: string;
  media_title: string;
  media_type: string;
  source: string;
  description: string;
}

interface GuidanceToneItem extends GuidanceItemBase {
  text: string;
  anchor: string | null;
}

const GUIDANCE_CONFIDENCE_RANK: Record<string, number> = { HIGH: 0, MEDIUM: 1, LOW: 2 };

function guidanceConfidence(item: any): "HIGH" | "MEDIUM" | "LOW" {
  const c = String(item?.confidence ?? "").toUpperCase();
  return c === "MEDIUM" || c === "LOW" ? (c as "MEDIUM" | "LOW") : "HIGH";
}

// Parameterised mirror of `badgeCanSeeWisdom`: the caller badge is an argument,
// never read from global state, so view selection and content filtering cannot
// be confused (REQ-032a).
function canSeeGuidanceItem(item: { badge_scope?: string }, callerBadge: string): boolean {
  if (callerBadge === "game_master" || callerBadge === "none") return true;
  return item?.badge_scope !== "game_master";
}

function guidanceRank(a: GuidanceItemBase, b: GuidanceItemBase): number {
  return (GUIDANCE_CONFIDENCE_RANK[a.confidence] ?? 0) - (GUIDANCE_CONFIDENCE_RANK[b.confidence] ?? 0);
}

// Ruleset Wisdom is always present (§11.3): before synthesis has run there is no
// manifest, so the shipped vendor profiles stand in for it. `withWisdomKeys`
// normalises their keys so the payload is stable and addressable.
function guidanceVoiceItems(viewBadge: string): GuidanceVoiceItem[] {
  const source = state.wisdomManifest
    ? effectiveWisdomItems("narrative_voices")
    : withWisdomKeys(DEFAULT_WISDOM).narrative_voices;
  return (Array.isArray(source) ? source : [])
    .filter((i: any) => i?.badge_scope === viewBadge || i?.badge_scope === "shared")
    .map((i: any) => ({
      badge_scope: i?.badge_scope,
      key: String(i?.key ?? ""),
      name: String(i?.name ?? ""),
      media_title: String(i?.media_title ?? ""),
      media_type: String(i?.media_type ?? ""),
      source: String(i?.source ?? ""),
      description: String(i?.description ?? ""),
      confidence: guidanceConfidence(i),
      provenance: provenanceTag(i),
    }))
    .sort((a, b) => guidanceRank(a, b) || a.name.localeCompare(b.name) || a.key.localeCompare(b.key));
}

// REQ-071a — `[narrative-tone]` samples: the ruleset composer's lines (always
// present, no anchor) plus synthesis items filed under the narrative-tone
// category. The tag survives rendering so the resource is the same retrievable
// artifact the briefing composes.
function guidanceToneItems(viewBadge: string): { ruleset: GuidanceToneItem[]; synthesis: GuidanceToneItem[] } {
  const ruleset = composeNarrativeTone(promptInputsFor(state.activeNovel))
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.startsWith("[narrative-tone]"))
    .map((text) => ({
      badge_scope: "shared",
      text,
      anchor: null,
      confidence: "HIGH" as const,
      provenance: provenanceTag({ tag: "ruleset" }),
    }));
  const synthesis = effectiveWisdomItems("supplementary_guidance")
    .filter((i: any) => i?.category === "narrative-tone")
    .filter((i: any) => i?.badge_scope === viewBadge || i?.badge_scope === "shared")
    .map((i: any) => ({
      badge_scope: i?.badge_scope,
      text: `[narrative-tone] ${String(i?.content ?? i?.text ?? "")}`,
      anchor: typeof i?.anchor === "string" && i.anchor ? String(i.anchor) : null,
      confidence: guidanceConfidence(i),
      provenance: provenanceTag(i),
    }))
    .sort((a, b) => guidanceRank(a, b) || a.text.localeCompare(b.text));
  return { ruleset, synthesis };
}

function renderGuidanceVoice(badgeLabel: string, items: GuidanceVoiceItem[]): string {
  const body = items.length === 0
    ? "(no voice profiles — module empty)"
    : items.map((i) => {
      const heading = [i.name, i.media_title, i.media_type ? `(${i.media_type})` : ""].filter(Boolean).join(" — ");
      const source = i.source ? `\n\nsource: ${i.source}` : "";
      return `## ${i.provenance} ${heading}\n${i.description}${source}\n\nconfidence: ${i.confidence}`;
    }).join("\n\n");
  return `# ${badgeLabel} Voice Guidance\n\n## Ruleset Wisdom\n${body}`;
}

function renderGuidanceTone(badgeLabel: string, payload: { ruleset: GuidanceToneItem[]; synthesis: GuidanceToneItem[] }): string {
  const section = (items: GuidanceToneItem[], empty: string): string => items.length === 0
    ? empty
    : items.map((i) => `${i.text}\n\nprovenance: ${i.provenance}\nconfidence: ${i.confidence}${i.anchor ? `\nanchor: ${i.anchor}` : ""}`).join("\n\n");
  return `# ${badgeLabel} Tone Guidance\n\n## Ruleset Wisdom\n${section(payload.ruleset, "(no tone items — module empty)")}\n\n## Synthesis\n${section(payload.synthesis, "(no tone items — module empty)")}`;
}

// Provenance tag rendered in the briefing (§11.3, REQ-159) and in synthesis
// resource output. Unknown tags are Tier-2 supplementary. §11.3 LOW-confidence
// presentation (REQ-264a) — a LOW item carries the visible `[LOW]` marker with
// its provenance tag so the pair reads `[supplementary] [LOW]` on every view.
function provenanceTag(item: any): string {
  const t = String(item?.tag ?? "");
  const base = t === "vendor" ? "[vendor]" : t === "ruleset" ? "[ruleset]" : t === "player" ? "[player]" : "[supplementary]";
  return String(item?.confidence ?? "").toUpperCase() === "LOW" ? `${base} [LOW]` : base;
}

// Lore groups (REQ-083a, REQ-083b) — grouped entries keyed by group name.
server.registerResource("lore-groups", "lore://groups", { title: "Lore Groups" }, async () => {
  const novel = state.activeNovel;
  const groups: Record<string, string[]> = {};
  if (novel) {
    for (const entry of [...novel.lore.values()].filter((e) => e.group && loreVisible(e, getBadge()))) {
      const group = String(entry.group);
      (groups[group] ??= []).push(entry.key);
    }
  }
  return { contents: [{ uri: "lore://groups", text: JSON.stringify(groups), mimeType: "application/json" }] };
});

// Lore templates (REQ-159, REQ-231, REQ-265)
server.registerResource("lore-templates", "lore://templates", { title: "Lore Templates" }, async () => {
  const templates = effectiveWisdomItems("lore_templates").filter(badgeCanSeeWisdom);
  return { contents: [{ uri: "lore://templates", text: JSON.stringify(templates, null, 2), mimeType: "application/json" }] };
});

// Guidance foundations resources (REQ-062)
server.registerResource("guidance-player-foundations", "guidance://player/foundations", { title: "Player Foundations" }, async () => ({
  contents: [{ uri: "guidance://player/foundations", text: "Describe what your character does in the fiction. Do not prescribe world facts or other characters' actions. Surface your intent; the narrative resolves it.", mimeType: "text/markdown" }],
}));
server.registerResource("guidance-gm-foundations", "guidance://game_master/foundations", { title: "GM Foundations" }, async () => ({
  contents: [{ uri: "guidance://game_master/foundations", text: "Describe situations and surface information. Never take action or make decisions on behalf of the player. Separate mechanics from fiction.", mimeType: "text/markdown" }],
}));

// REQ-022a/REQ-071a + §11.3 — badge guidance views rendered from the Novel's
// live synthesis state. The URI badge selects the view; the caller's badge
// filters content (`canSeeGuidanceItem`), so both roles stay explicit.
function guidanceViewText(badgeLabel: string, viewBadge: string, kind: "voice" | "tone"): string {
  const caller = getBadge();
  if (kind === "voice") {
    return renderGuidanceVoice(badgeLabel, guidanceVoiceItems(viewBadge).filter((i) => canSeeGuidanceItem(i, caller)));
  }
  const payload = guidanceToneItems(viewBadge);
  return renderGuidanceTone(badgeLabel, {
    ruleset: payload.ruleset.filter((i) => canSeeGuidanceItem(i, caller)),
    synthesis: payload.synthesis.filter((i) => canSeeGuidanceItem(i, caller)),
  });
}

server.registerResource("guidance-player-voice", "guidance://player/voice", { title: "Player Voice Guidance" }, async () => ({
  contents: [{ uri: "guidance://player/voice", text: guidanceViewText("Player", "player", "voice"), mimeType: "text/markdown" }],
}));
server.registerResource("guidance-gm-voice", "guidance://game_master/voice", { title: "GM Voice Guidance" }, async () => ({
  contents: [{ uri: "guidance://game_master/voice", text: guidanceViewText("Game Master", "game_master", "voice"), mimeType: "text/markdown" }],
}));
server.registerResource("guidance-player-tone", "guidance://player/tone", { title: "Player Tone Guidance" }, async () => ({
  contents: [{ uri: "guidance://player/tone", text: guidanceViewText("Player", "player", "tone"), mimeType: "text/markdown" }],
}));
server.registerResource("guidance-gm-tone", "guidance://game_master/tone", { title: "GM Tone Guidance" }, async () => ({
  contents: [{ uri: "guidance://game_master/tone", text: guidanceViewText("Game Master", "game_master", "tone"), mimeType: "text/markdown" }],
}));

// Synthesis status + per-module resources (REQ-230, REQ-160)
// total = full module size; activated = items the effective view exposes.
function synthesisModuleCounts(): Record<string, { total: number; activated: number }> {
  const manifest = state.wisdomManifest;
  const out: Record<string, { total: number; activated: number }> = {};
  for (const m of SYNTHESIS_MODULES) out[m] = { total: 0, activated: 0 };
  if (!manifest) return out;
  if (manifest.voice_examples) out.voice_examples.total = manifest.voice_examples.length;
  if (manifest.lore_templates) out.lore_templates.total = manifest.lore_templates.length;
  if (manifest.action_patterns) out.action_patterns.total = manifest.action_patterns.length;
  if (manifest.supplementary_guidance) out.supplementary_guidance.total = manifest.supplementary_guidance.length;
  if (manifest.adventure_advice) out.adventure_advice.total = (manifest.adventure_advice.templates?.length ?? 0) + (manifest.adventure_advice.scenario_starters?.length ?? 0) + (manifest.adventure_advice.table_expansions?.length ?? 0);
  if (manifest.narrative_voices) out.narrative_voices.total = manifest.narrative_voices.length;
  for (const m of SYNTHESIS_MODULES) out[m].activated = effectiveWisdomItems(m).length;
  return out;
}

// REQ-226 — narrative voice profiles: media-cited narrative voice profiles
// stored at synthesis://narrative_voices; ruleset-free/vendor-absent → empty.
server.registerResource("synthesis-narrative-voices", "synthesis://narrative_voices", { title: "Narrative Voice Profiles" }, async () => {
  const profiles = effectiveWisdomItems("narrative_voices").filter(badgeCanSeeWisdom);
  const list = (Array.isArray(profiles) ? profiles : []).map((p: any) => `## ${provenanceTag(p)} ${p?.name ?? "voice"}\n${p?.description ?? ""}`).join("\n\n");
  return { contents: [{ uri: "synthesis://narrative_voices", text: `# Narrative Voice Profiles\n\n${list || "(no profiles — module empty)"}`, mimeType: "text/markdown" }] };
});

// REQ-231b / §11.3 — per-module synthesis resource family, gated by module
// toggle, per-item activation, and badge scope. narrative_voices is registered
// above with its own Markdown rendering.
for (const module of SYNTHESIS_MODULES.filter((m) => m !== "narrative_voices")) {
  server.registerResource(
    `synthesis-${module}`,
    `synthesis://${module}`,
    { title: `Synthesis ${module}` },
    async () => {
      const manifest: any = state.wisdomManifest;
      const rank = (i: any): number => (i?.confidence === "LOW" ? 2 : i?.confidence === "MEDIUM" ? 1 : 0);
      const items = effectiveWisdomItems(module)
        .filter(badgeCanSeeWisdom)
        .map((i: any) => ({ ...i, provenance: provenanceTag(i), confidence: i?.confidence ?? "HIGH", collected_at: manifest?.collected_at ?? i?.collected_at ?? null }))
        .sort((a: any, b: any) => rank(a) - rank(b));
      return { contents: [{ uri: `synthesis://${module}`, text: JSON.stringify(items, null, 2), mimeType: "application/json" }] };
    },
  );
}

server.registerResource("synthesis-status", "synthesis://status", { title: "Synthesis Status" }, async () => {
  const counts = synthesisModuleCounts();
  const active = state.enriched;
  const caps = synthesisCapStatus(state.wisdomManifest);
  let md = "Synthesis Status\n";
  for (const [m, c] of Object.entries(counts)) {
    const lowItems: any[] = state.wisdomManifest
      ? (m === "adventure_advice"
        ? [...(state.wisdomManifest.adventure_advice?.templates ?? []), ...(state.wisdomManifest.adventure_advice?.scenario_starters ?? []), ...(state.wisdomManifest.adventure_advice?.table_expansions ?? [])]
        : (Array.isArray(state.wisdomManifest[m]) ? state.wisdomManifest[m] : []))
      : [];
    const low = lowItems.filter((i: any) => String(i?.confidence ?? "").toUpperCase() === "LOW").length;
    md += `## ${m}\nRuleset Wisdom: ${active ? c.total : 0}\nSynthesis activated/total: ${c.activated}/${active ? c.total : 0}\nLOW confidence: ${low}\nCap: ${caps.modules[m]?.count ?? 0}/${caps.modules[m]?.max ?? 0}${caps.modules[m]?.overflow ? " [OVERFLOW]" : ""}\n`;
  }
  const empties = Object.entries((state.wisdomManifest?._empty ?? {}) as Record<string, string>);
  if (empties.length > 0) md += `Empty modules: ${empties.map(([m, why]) => `${m} [empty — ${why}]`).join(", ")}\n`;
  if (state.wisdomManifest?._fingerprint) md += `Fingerprint: ${state.wisdomManifest._fingerprint}\n`;
  return { contents: [{ uri: "synthesis://status", text: md, mimeType: "text/markdown" }] };
});

